window.READING_CLASS_DATA = {"version":1,"cases":[{"id":"class-1주-문1","unit":"u11","title":"1주차 · 문1 · 간접사실의 자백과 이유부 부인","year":"1주차 수업","facts":"갑은 을에게 매매대금 1억 원의 반환을 청구했다. 을은 계약 성립 당시 해외 출장 중이었다고 주장했고, 갑은 양쪽 이름과 인장이 있는 매매계약서를 제출했다.\n갑은 2회 변론기일에 을의 해외 출장 주장을 모두 인정했다가 3회 변론기일에 이를 철회하려 한다.","prompt":"갑은 위 진술을 임의로 철회할 수 있는가? 법원은 그 진술을 반드시 판결의 기초로 삼아야 하는가?","sourceId":"sa975940342","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"원문은 매매계약서·매매계약을 전제로 하면서 문2·문3 및 답안에서 ‘차용증서·소비대차계약’ 표현을 혼용한다. 계약 종류와 문서 명칭을 추측하여 통일하지 않고 원문대로 수록했다. 답안은 교수님 자료의 채점기준이며 별도의 현행법 검증이나 답안 보충은 하지 않았다.","references":[],"classMaterial":true,"important":true,"classKey":"1주-문1","learningSummary":true},{"id":"class-1주-문2","unit":"u12","title":"1주차 · 문2 · 인영 인정·날인 부인과 사문서의 2단 추정","year":"1주차 수업","facts":"갑은 을에게 매매대금 1억 원의 반환을 청구하며 매매계약서를 제출했다. 증거조사에서 을은 문서의 인영이 자기 인장에 의한 것임은 인정하지만, 직접 날인한 사실은 부인했다. 을의 의사에 따른 날인인지가 진위불명이다.","prompt":"법원은 위 문서의 진정성립을 인정할 수 있는가? (원문은 해당 문서를 ‘매매계약서’와 ‘차용증서’로 혼용한다.)","sourceId":"sa975940342","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"원문은 매매계약서·매매계약을 전제로 하면서 문2·문3 및 답안에서 ‘차용증서·소비대차계약’ 표현을 혼용한다. 계약 종류와 문서 명칭을 추측하여 통일하지 않고 원문대로 수록했다. 답안은 교수님 자료의 채점기준이며 별도의 현행법 검증이나 답안 보충은 하지 않았다.","references":[],"classMaterial":true,"important":true,"classKey":"1주-문2","learningSummary":true},{"id":"class-1주-문3","unit":"u12","title":"1주차 · 문3 · 처분문서의 형식적·실질적 증거력","year":"1주차 수업","facts":"갑은 을에게 매매대금 1억 원의 반환을 청구하며 계약서를 제출했다. 그 문서의 진정성립이 인정되었다.","prompt":"법원은 문서에 적힌 내용대로 계약체결 사실도 인정해야 하는가? (원문은 ‘매매계약서·차용증서’ 및 계약 종류를 혼용한다.)","sourceId":"sa975940342","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"원문은 매매계약서·매매계약을 전제로 하면서 문2·문3 및 답안에서 ‘차용증서·소비대차계약’ 표현을 혼용한다. 계약 종류와 문서 명칭을 추측하여 통일하지 않고 원문대로 수록했다. 답안은 교수님 자료의 채점기준이며 별도의 현행법 검증이나 답안 보충은 하지 않았다.","references":[],"classMaterial":true,"important":true,"classKey":"1주-문3","learningSummary":true},{"id":"class-1주-문4","unit":"u12","title":"1주차 · 문4 · 백지날인 문서와 보충권한의 증명책임","year":"1주차 수업","facts":"갑이 제출한 매매계약서에 관해 을은 날인사실을 인정했다. 다만 문서가 백지상태로 작성·교부되었고, 갑이 나중에 그 내용을 보충했다는 사실이 증명되었다.","prompt":"이 상태에서 법원은 문서의 진정성립을 인정할 수 있는가?","sourceId":"sa975940342","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"원문은 매매계약서·매매계약을 전제로 하면서 문2·문3 및 답안에서 ‘차용증서·소비대차계약’ 표현을 혼용한다. 계약 종류와 문서 명칭을 추측하여 통일하지 않고 원문대로 수록했다. 답안은 교수님 자료의 채점기준이며 별도의 현행법 검증이나 답안 보충은 하지 않았다.","references":[],"classMaterial":true,"important":true,"classKey":"1주-문4","learningSummary":true},{"id":"class-1주-문5","unit":"u11","title":"1주차 · 문5 · 문서 진정성립 자백의 구속력과 취소요건","year":"1주차 수업","facts":"갑의 매매대금 반환청구소송에서 을은 제출된 계약서의 진정성립을 인정했다. 이후 소송이 불리해지자 문서가 위조되었다고 주장하며 종전의 인정을 뒤집었다.","prompt":"법원은 을의 위조 항변을 어떻게 판단해야 하는가?","sourceId":"sa975940342","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"원문은 매매계약서·매매계약을 전제로 하면서 문2·문3 및 답안에서 ‘차용증서·소비대차계약’ 표현을 혼용한다. 계약 종류와 문서 명칭을 추측하여 통일하지 않고 원문대로 수록했다. 답안은 교수님 자료의 채점기준이며 별도의 현행법 검증이나 답안 보충은 하지 않았다.","references":[],"classMaterial":true,"important":true,"classKey":"1주-문5","learningSummary":true},{"id":"class-2주-문제1-1","unit":"u17","title":"2주차 · 문제1-1 · 소송계속 중 계쟁물 승계와 인수승계","year":"2주차 수업","facts":"갑 소유의 2층 건물을 갑의 아들 A에게서 임차한 을이 1층을 병에게 전대했다. 갑은 을과 병의 점유가 무권원이라며 각 점유부분의 인도와 차임 상당 부당이득반환을 청구했다. 점유이전금지가처분은 하지 않았다.\n사실심 변론종결 전에 병이 1층을 정에게 다시 전대하여 정이 점유한다는 사실을 갑이 알았다.","prompt":"갑은 정을 상대로 어떠한 소송법적 조치를 할 수 있는가?","sourceId":"s3844552031","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"2주-문제1-1","learningSummary":true},{"id":"class-2주-문제1-2","unit":"u14","title":"2주차 · 문제1-2 · 변론종결 후 승계인과 승계집행문","year":"2주차 수업","facts":"갑은 무권원 점유를 주장하며 을·병에게 건물 인도와 차임 상당 부당이득반환을 청구했고, 전부 승소한 판결이 확정되었다. 점유이전금지가처분은 하지 않았다.\n집행 중 병이 판결 확정 후 1층을 정에게 전대하여 정이 점유한다는 사실이 드러났다. 갑은 정에게 전소와 같은 내용의 후소를 제기했다.","prompt":"후소 법원은 어떠한 판결을 선고해야 하는가?","sourceId":"s3844552031","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"2주-문제1-2","learningSummary":true},{"id":"class-2주-문제1-3","unit":"u14","title":"2주차 · 문제1-3 · 건물인도·부당이득청구와 기판력의 주관적 범위","year":"2주차 수업","facts":"갑은 을·병을 상대로 건물의 각 점유부분 인도와 차임 상당 부당이득반환을 청구했으나 전부 패소하여 판결이 확정되었다. 이후 갑은 건물 전체를 정에게 매도하고 소유권이전등기를 마쳤다. 정은 을·병에게 전소와 같은 내용의 후소를 제기했다.","prompt":"정의 후소는 전소 확정판결의 기판력에 저촉되는가?","sourceId":"s3844552031","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"원문 답안 제목의 ‘정의 을과 정에 대한’은 설문의 상대방에 맞춰 ‘정의 을과 병에 대한’으로 교정했다. 법리·결론은 변경하지 않았다.","references":[],"classMaterial":true,"important":true,"classKey":"2주-문제1-3","learningSummary":true},{"id":"class-2주-문제1-4","unit":"u16","title":"2주차 · 문제1-4 · 통상공동소송인 한 사람만 항소한 경우","year":"2주차 수업","facts":"갑은 을·병을 상대로 건물의 각 점유부분 인도와 차임 상당 부당이득반환을 청구해 1심에서 전부 승소했다. 을만 항소했다. 항소법원은 심리 결과 갑의 청구가 부당하다고 판단했다.","prompt":"항소심은 항소하지 않은 병에 대해서도 1심과 다른 판결을 선고할 수 있는가?","sourceId":"s3844552031","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"2주-문제1-4","learningSummary":true},{"id":"class-2주-문제2-1","unit":"u09","title":"2주차 · 문제2-1 · 사기로 인한 소취하의 구제와 재소금지","year":"2주차 수업","facts":"갑은 을에게 매매를 원인으로 한 A부동산 소유권이전등기를 청구하여 승소했다. 항소심 중 갑·을은 부동산 대신 1억 원을 지급하고 소를 취하하기로 소송 외에서 화해했고, 갑은 소를 취하했다.\n을은 처음부터 지급 의사·능력이 없으면서 갑을 속였고, 화해금도 지급하지 않았다. 갑은 원래의 소유권이전등기를 받고 싶다.","prompt":"갑이 취할 수 있는 소송법상 구제수단은 무엇인가?","sourceId":"s5f94d32e5d","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"2주-문제2-1","learningSummary":true},{"id":"class-2주-문제2-2","unit":"u15","title":"2주차 · 문제2-2 · 예비적 병합의 판단누락과 후소","year":"2주차 수업","facts":"갑은 주위적으로 유효한 매매계약에 따른 대금 지급을, 예비적으로 계약이 무효라면 인도한 A물건의 반환을 청구했다. 법원은 대금청구만 기각하고 물건 반환청구에는 판단하지 않았다. 갑은 항소하지 않고 판결을 확정시킨 뒤, 계약 무효를 이유로 A물건 반환의 별도 소를 제기했다.","prompt":"이 후소는 허용되는가?","sourceId":"s5f94d32e5d","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"2주-문제2-2","learningSummary":true},{"id":"class-2주-문제2-3","unit":"u14","title":"2주차 · 문제2-3 · 건물매수청구권의 표준시 후 행사","year":"2주차 수업","facts":"갑의 토지를 임차한 을이 지상 건물을 신축했다. 임대차 종료 후 갑은 건물철거·토지인도를 청구했다. 을은 행사할 수 있던 건물매수청구권을 행사하지 않아 패소판결이 확정되었다. 이후 을은 갑에게 건물매수청구권을 행사하며 대금청구소송을 제기했다.","prompt":"확정판결 후 제기한 을의 건물대금 청구는 허용되는가?","sourceId":"s5f94d32e5d","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"2주-문제2-3","learningSummary":true},{"id":"class-2주-문제2-4","unit":"u14","title":"2주차 · 문제2-4 · 상계항변 기판력과 부당이득반환청구","year":"2주차 수업","facts":"갑의 1,000만 원 지급청구에 대해 을이 1,500만 원의 매매대금채권으로 상계항변을 했다. 상계가 인정되어 갑의 청구가 기각되고 판결이 확정되었다.","prompt":"각각 독립하여 검토하라.\n(1) 갑이 을의 채권은 처음부터 없었다며 부당이득반환을 청구하는 후소는 허용되는가?\n(2) 을이 갑의 채권은 처음부터 없었다며 부당이득반환을 청구하는 후소는 허용되는가?","sourceId":"s5f94d32e5d","sourcePages":[1,2],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"2주-문제2-4","learningSummary":true},{"id":"class-2주-문제2-5","unit":"u15","title":"2주차 · 문제2-5 · 반소의 관련성과 상계금지","year":"2주차 수업","facts":"두 설문은 서로 다른 본소에 대한 반소의 허용 여부를 묻는다.","prompt":"(1) 고의의 명예훼손에 따른 손해배상 본소에 대해, 전혀 별개의 영업방해를 이유로 손해배상 반소를 제기할 수 있는가?\n(2) 고의의 상해에 따른 손해배상 본소에 대해, 대여금채권으로 상계를 주장하면서 나머지 대여금의 지급을 구하는 반소를 제기할 수 있는가?","sourceId":"s5f94d32e5d","sourcePages":[2],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"2주-문제2-5","learningSummary":true},{"id":"class-3주-사례1","unit":"u08","title":"3주차 · 사례1 · 증거공통·주장책임·간접적 주장이론","year":"3주차 수업","facts":"갑은 2021.10.16. 을에게 5,000만 원을 변제기 2021.12.16., 월 이율 1%로 빌려주었다며 2022.5.1. 대여금소송을 제기했다. 을은 갑의 주장을 전부 부인하고 청구기각을 구했다.\n을이 신청한 증인 병은 대여 장면과 2021.12.16. 원금·2개월분 이자를 지급한 장면을 목격했다고 증언했다. 법원은 증인신문 후 그대로 변론을 종결했다. 원문에는 변제일과 ‘변제기로부터 두 달이 지난’이라는 표현의 모순이 있다.","prompt":"법원은 병의 증언을 토대로 대여와 변제를 모두 인정해 갑의 청구를 기각할 수 있는가?","sourceId":"s3e7fff1fe8","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"원문에서 변제기와 ‘두 달이 지난’ 변제일이 모두 2021.12.16.로 되어 있어 날짜가 모순된다. 답안 각주2의 연도 ‘198.8.11.’도 불완전하다. 추측하여 교정하지 않았다.","references":[],"classMaterial":true,"important":true,"classKey":"3주-사례1","learningSummary":true},{"id":"class-3주-사례2","unit":"u10","title":"3주차 · 사례2 · 간접부인과 항변의 구별·증명책임·판결이유","year":"3주차 수업","facts":"갑은 을에게 매매대금 2,000만 원을, 병에게 대여금 3,000만 원을 청구했다. 을은 매수가 아니라 증여라고, 병은 갑이 대여금채무를 면제했다고 주장했다. 증거조사 결과 매매·대여 사실은 인정되지만 증여·면제 여부는 진위불명인 채 변론이 종결되었다.","prompt":"(1) 법원은 을·병이 주장한 사실의 존부를 어떻게 판단해야 하는가?\n(2) 각 청구에 어떤 판결을 선고하고, 판결이유에는 무엇을 판단·설시해야 하는가?","sourceId":"s3e7fff1fe8","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"3주-사례2","learningSummary":true},{"id":"class-3주-사례3","unit":"u10","title":"3주차 · 사례3 · 소송상 상계 후 조정과 반대채권의 존속","year":"3주차 수업","facts":"갑의 공사대금 1억 원 청구에 대해 을은 전액 변제를 주장하고, 예비적으로 손해배상채권 5,000만 원으로 상계했다. 소송은 ‘을은 6,000만 원 지급, 갑은 나머지 청구 포기’라는 조정으로 종료되었다.\n이후 을이 위 손해배상채권 5,000만 원을 청구하자 갑은 그 채권이 전소의 상계권 행사로 소멸했다고 항변했다.","prompt":"법원은 후소에서 갑의 채권 소멸 항변을 어떻게 판단해야 하는가?","sourceId":"s3e7fff1fe8","sourcePages":[2],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"3주-사례3","learningSummary":true},{"id":"class-3주-사례4-1","unit":"u09","title":"3주차 · 사례4-1 · 소취하 합의의 법적 성질과 소각하","year":"3주차 수업","facts":"갑의 건강기능식품 대금 500만 원 청구에 을은 중대한 하자를 이유로 지급을 거절했고, 갑이 1심에서 패소하여 항소했다. 항소심 중 ‘을이 200만 원을 지급하면 갑은 즉시 소를 취하한다’고 합의했다.\n을은 200만 원을 지급했으나 갑은 소를 취하하지 않았다. 을은 합의서를 제출했다. 심리 결과 매매계약과 매매대금 미지급, 합의서의 진정성립과 합의 후 200만 원 지급이 모두 인정되었다.","prompt":"법원은 어떤 판결을 선고해야 하는가?","sourceId":"s3e7fff1fe8","sourcePages":[2],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"3주-사례4-1","learningSummary":true},{"id":"class-3주-사례4-2","unit":"u09","title":"3주차 · 사례4-2 · 특정승계인·사정변경과 재소금지","year":"3주차 수업","facts":"갑은 건강기능식품 대금 500만 원 청구에서 패소해 항소했다. 항소심 중 을이 200만 원을 지급하면 갑이 소를 취하하기로 합의했다. 갑은 먼저 취하하면 곧 지급하겠다는 을의 말을 믿고 소를 취하했으나 을은 지급하지 않았다.\n갑은 합의금채권을 병에게 양도하고 을에게 통지했다. 병은 을에게 합의금 200만 원을 청구했다.","prompt":"병이 제기한 합의금 청구의 소는 적법한가?","sourceId":"s3e7fff1fe8","sourcePages":[2],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"3주-사례4-2","learningSummary":true},{"id":"class-4주-문1","unit":"u14","title":"4주차 · 문1 · 상계 재항변과 수동채권의 기판력 범위","year":"4주차 수업","facts":"갑은 을에게 X토지의 소유권이전등기를 청구했다. 을은 계약 실효를 주장하면서 예비적으로 잔금 지급과의 동시이행을 항변했고, 갑은 대여금채권으로 상계재항변을 했다.\n법원은 매매는 유효하지만 대여금채권은 인정되지 않는다고 보아 잔금 지급과 상환으로 등기하라는 판결을 선고했고 확정되었다. 갑이 다시 대여금 지급을 청구하자 을은 전소의 기판력에 저촉된다고 항변했다.","prompt":"후소 법원은 을의 기판력 항변을 어떻게 판단해야 하는가?","sourceId":"s05455e5f8f","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"4주-문1","learningSummary":true},{"id":"class-4주-문2","unit":"u12","title":"4주차 · 문2 · 영수증의 진정성립·증거력·자백 취소","year":"4주차 수업","facts":"갑이 대여금 반환을 청구하자 을은 변제를 주장하며 갑 명의·인장이 있는 영수증을 제출했다. 갑은 변제를 다투었고 법원이 영수증을 증거조사했다.","prompt":"각각 독립하여 검토하라.\n(1) 갑이 인영은 인정하지만 직접 날인한 사실을 부인하면, 영수증의 형식적·실질적 증거력을 어떻게 판단해야 하는가?\n(2) 갑이 진정성립을 인정한 뒤 소송이 불리해지자 위조를 주장하며 부인하면, 법원은 어떻게 처리해야 하는가?","sourceId":"s05455e5f8f","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"수업 답안은 채점요지 형식이다. 문2 (2)의 진정성립 자백·취소 부분은 검토할 질문만 제시하며 완성된 답안 문장을 수록하지 않는다. 없는 답안을 생성하여 원문처럼 넣지 않았다.","references":[],"classMaterial":true,"important":true,"classKey":"4주-문2","learningSummary":true},{"id":"class-4주-문3-1","unit":"u10","title":"4주차 · 문3-1 · 자백 취지 답변서와 무변론판결","year":"4주차 수업","facts":"갑은 해외근무 중 을에게 X건물 관리를 맡겼는데 을이 자기 명의로 이전등기를 했다. 귀국한 갑은 2021.4.1. 등기의 원인무효를 주장하며 말소를 청구했다.\n을은 2021.5.1. 소장부본을 받고 ‘갑의 승낙 없이 등기한 것은 사실이며 말소하라면 말소하겠다’는 답변서를 제출했다. 답변서는 2021.5.6. 접수되었고 을은 이후 아무런 소송행위를 하지 않았다.","prompt":"법원은 이 상태에서 소송을 종결할 수 있는가?","sourceId":"s05455e5f8f","sourcePages":[2],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"4주-문3-1","learningSummary":true},{"id":"class-4주-문3-2","unit":"u13","title":"4주차 · 문3-2 · 등기의 추정력과 원인무효의 증명책임","year":"4주차 수업","facts":"갑이 해외근무 중 건물 관리를 맡은 을이 자기 명의로 이전등기를 했다. 갑은 등기의 원인무효를 주장하며 말소를 청구했다.\n을은 갑의 대리인 A에게 적법하게 매수했다고 주장하며 적극적으로 다투었다. 심리 결과 갑이 A에게 대리권을 수여했는지는 진위불명이다.","prompt":"법원은 어떤 내용의 판결을 선고해야 하는가?","sourceId":"s05455e5f8f","sourcePages":[2,3],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"4주-문3-2","learningSummary":true},{"id":"class-4주-문3-3","unit":"u16","title":"4주차 · 문3-3 · 통상공동소송의 자백·부인과 주장공통","year":"4주차 수업","facts":"갑은 관리인 을이 X건물에 한 자기 명의 이전등기가 원인무효라며 말소를 청구했다. 을이 소장부본을 받은 뒤 사망하자 공동상속인 병·정이 수계했고, 갑은 상속분에 따라 청구취지를 변경했다.\n병은 갑의 주장사실을 인정했지만 정은 을 명의 등기가 적법하다며 적극적으로 다투었다.","prompt":"정의 진술은 병에게, 병의 자백은 정에게 각각 어떤 영향을 미치는가?","sourceId":"s05455e5f8f","sourcePages":[2,3],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"4주-문3-3","learningSummary":true},{"id":"class-5주-문1","unit":"u01","title":"5주차 · 문1 · 전속적 합의관할·변론관할·이송","year":"5주차 수업","facts":"수원 거주 갑은 서울 서초구 거주 을에게서 서울 노원구의 X부동산을 2억 원에 매수해 대금을 모두 지급했다. 을이 이전등기를 지체하자 갑은 계약을 해제하고 수원지법에 대금반환을 청구했다. 계약서에는 ‘1심 관할법원은 서울중앙지법으로 한다’고 적혀 있다.\n을은 관할위반과 예비적으로 해제의 최고 요건 불비를 답변서에서 다투었고, 1회 변론기일에 소장·답변서가 진술되었다. 석명 후에도 관할조항의 의미는 불명확했다. 추가 준비서면 없이 2회 기일에 을이 관할위반을 이유로 이송을 신청했다.","prompt":"수원지법은 을의 관할위반 주장과 이송신청에 어떻게 판단·조치해야 하는가?\n원문 지시: ‘문제의 소재’ 또는 ‘쟁점’을 별도로 기재하지 말 것.","sourceId":"s3fd74e102d","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"5주-문1","learningSummary":true},{"id":"class-5주-문2","unit":"u02","title":"5주차 · 문2 · 당사자 사망과 소송대리인의 항소","year":"5주차 수업","facts":"갑은 매매계약 해제로 을에게 부동산 매매대금 2억 원의 반환을 청구했다. 을은 소장부본을 받은 뒤 A변호사를 선임하고 1심의 소취하·청구 포기·인낙·상소 제기 특별수권을 부여했으나, 1회 변론기일 전에 사망했다. 상속인은 병·정이다.\n병만 수계했고 법원은 갑 승소판결을 선고하면서 판결문에 병만 피고로 적었다. A는 병이 상속인 전부라고 생각하고 병만 항소인으로 하여 항소했다.","prompt":"A가 제기한 항소는 정에게도 효력이 있는가?\n원문 지시: ‘문제의 소재’ 또는 ‘쟁점’을 별도로 기재하지 말 것.","sourceId":"s3fd74e102d","sourcePages":[1,2],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"5주-문2","learningSummary":true},{"id":"class-5주-문3","unit":"u03","title":"5주차 · 문3 · 피보전채권 패소확정과 채권자대위소송","year":"5주차 수업","facts":"갑이 을에게 제기한 매매대금 반환소송에서 을은 소송대리인을 선임한 뒤 사망했고, 상속인 병·정이 모두 수계했다. 갑의 청구를 모두 기각한 1심 판결이 적법하게 송달되었으나 아무도 항소하지 않아 확정되었다.\n갑은 위 반환채권을 보전하려 병·정을 대위하여 무에게 부당이득반환을 청구하고 병·정에게 소송계속을 알렸다. 전소 경과 자료가 모두 제출되었고, 병·정의 무에 대한 부당이득반환청구권은 실체적 요건을 갖춘 것으로 밝혀졌다.","prompt":"대위소송의 1심 법원은 어떤 판결을 선고해야 하는가?\n원문 지시: ‘문제의 소재’ 또는 ‘쟁점’을 별도로 기재하지 말 것.","sourceId":"s3fd74e102d","sourcePages":[2],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"5주-문3","learningSummary":true},{"id":"class-5주-문4","unit":"u13","title":"5주차 · 문4 · 일응의 추정과 간접반증","year":"5주차 수업","facts":"파란 보행등이 켜진 횡단보도에서 갑의 자동차에 치인 을이 갑의 보험회사 병에게 손해배상을 청구했다. 병은 갑이 정지선에 멈춰 있었는데 정의 뒷차 충격으로 횡단보도에 진입했다고 항변했다.\n법원은 갑의 차가 파란 보행등이 켜진 횡단보도에 진입한 사실은 확신하지만, 뒷차 충격 때문이라는 사실은 확신하지 못했다.","prompt":"법원은 갑의 과실을 인정할 수 있는가?\n원문 지시: ‘문제의 소재’ 또는 ‘쟁점’을 별도로 기재하지 말 것.","sourceId":"s3fd74e102d","sourcePages":[2],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"5주-문4","learningSummary":true},{"id":"class-6주-문제1-1","unit":"u03","title":"6주차 · 문제1-1 · 대위소송의 소각하판결과 피보전채권의 기판력","year":"6주차 수업","facts":"갑의 물품대금채권 1억 원 성립 후 을은 유일한 재산인 X부동산을 병에게 매도·이전등기했다. 갑은 통정허위표시로 무효라고 주장하며 을을 대위해 병에게 등기말소를 청구하고 을에게 제소 사실을 고지했다.\n갑의 을에 대한 피보전채권 부존재를 이유로 소각하판결이 확정되었다. 갑이 다시 을에게 물품대금을 청구하자 을은 전소의 기판력에 저촉된다고 주장했다.","prompt":"후소 법원은 을의 기판력 주장을 어떻게 판단해야 하는가?","sourceId":"s27b66636e3","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"6주-문제1-1","learningSummary":true},{"id":"class-6주-문제1-2","unit":"u07","title":"6주차 · 문제1-2 · 사해행위취소의 범위·가액배상·처분권주의","year":"6주차 수업","facts":"갑의 물품대금채권 1억 원 성립 후 을은 유일한 X부동산을 병에게 매도·이전등기했다. 부동산에는 갑의 채권 성립 전부터 정의 근저당권이 있었으나, 병이 피담보채무를 전액 변제하여 말소되었다.\n갑은 매매의 사해행위 전부취소와 병 명의 등기말소를 청구했다. 병은 선의를 주장하며, 취소되더라도 전부취소·원물반환은 부당하다고 다투었다. 갑은 변론종결까지 청구취지를 유지했고 사해행위의 실체적 요건에 관한 갑의 주장은 모두 인정되었다.","prompt":"법원은 어떤 판결을 선고해야 하는가?","sourceId":"s27b66636e3","sourcePages":[1],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"6주-문제1-2","learningSummary":true},{"id":"class-6주-문제2-1","unit":"u17","title":"6주차 · 문제2-1 · 보조참가인의 항소·피참가인의 항소취하","year":"6주차 수업","facts":"갑은 2018.4.1. 을에게 1억 원을 대여하고 병의 대리인 정에게서 병 명의 연대보증 지급각서를 받았다. 갑이 병에게 보증채무 이행을 청구하자 병은 을이 2018.10.1. 변제했다고 주장했다. 소송고지를 받은 을이 병을 위해 보조참가했다.\n병이 증명에 실패해 패소했고 판결정본은 을에게 2019.6.11., 갑·병에게 6.15. 송달되었다. 을만 6.17. 항소했고 병은 7.20. 그 항소를 취하했다. 병이 8.1. 을에게 구상금을 청구하자 을은 다시 2018.10.1. 주채무 변제를 주장했다.","prompt":"을의 항소와 병의 항소취하는 각각 적법한가? 후소에서 을의 주채무 변제소멸 주장은 적법한가?","sourceId":"s27b66636e3","sourcePages":[2],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"6주-문제2-1","learningSummary":true},{"id":"class-6주-문제2-2","unit":"u17","title":"6주차 · 문제2-2 · 보조참가신청 취하 후 참가적 효력","year":"6주차 수업","facts":"갑은 2018.4.1. 을에게 1억 원을 대여하고 병 명의 연대보증 지급각서를 받아 병에게 보증채무 이행을 청구했다. 병은 을의 변제로 주채무가 소멸했다고 주장했다. 소송고지에 따라 보조참가한 을은 2019.4.1. 참가신청을 취하했다.\n병은 변제 증명에 실패하여 2019.5.30. 패소했고 판결이 확정되었다. 이후 병의 구상금 청구에 대해 을은 ‘2017.10.1. 변제로 주채무가 소멸했다’고 주장했다. 원문은 이 날짜를 대여일보다 앞선 것으로 기재한다.","prompt":"후소에서 을의 주채무 변제소멸 주장은 적법한가?","sourceId":"s27b66636e3","sourcePages":[2],"answerKind":"supplied","sourceExcerpts":[],"caution":"원문은 대여일 2018.4.1.보다 앞선 2017.10.1.을 변제일로 기재한다. 원문대로 수록하며 날짜를 임의로 고치지 않았다.","references":[],"classMaterial":true,"important":true,"classKey":"6주-문제2-2","learningSummary":true},{"id":"class-6주-문제2-3","unit":"u12","title":"6주차 · 문제2-3 · 인장도용과 정당한 날인권한의 증명책임","year":"6주차 수업","facts":"갑은 을에게 빌려준 1억 원에 대한 병의 연대보증채무 이행을 청구하며, 병의 대리인 정에게 받은 지급각서를 제출했다. 병은 자기 인영임은 인정하지만 정이 인장을 도용해 날인했다고 주장했다. 갑은 정이 날인한 것은 인정하면서 병에게 위임받은 정당한 권원에 따른 것이라고 주장했다.\n법원은 정의 정당한 날인권한에 확신을 갖지 못했다.","prompt":"법원은 지급각서를 증거로 병의 연대보증사실을 인정할 수 있는가?","sourceId":"s27b66636e3","sourcePages":[2],"answerKind":"supplied","sourceExcerpts":[],"caution":"","references":[],"classMaterial":true,"important":true,"classKey":"6주-문제2-3","learningSummary":true}],"meta":{"class-1주-문1":{"primary":{"sourceId":"sa975940342","pages":[1]},"related":[{"sourceId":"sa975940342","pages":[2]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":2,"supplement":false,"classMaterial":true},"class-1주-문2":{"primary":{"sourceId":"sa975940342","pages":[1]},"related":[{"sourceId":"sa975940342","pages":[2,3]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":2,"supplement":false,"classMaterial":true},"class-1주-문3":{"primary":{"sourceId":"sa975940342","pages":[1]},"related":[{"sourceId":"sa975940342","pages":[3]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":3,"supplement":false,"classMaterial":true},"class-1주-문4":{"primary":{"sourceId":"sa975940342","pages":[1]},"related":[{"sourceId":"sa975940342","pages":[3]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":3,"supplement":false,"classMaterial":true},"class-1주-문5":{"primary":{"sourceId":"sa975940342","pages":[1]},"related":[{"sourceId":"sa975940342","pages":[3,4]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":3,"supplement":false,"classMaterial":true},"class-2주-문제1-1":{"primary":{"sourceId":"s3844552031","pages":[1]},"related":[{"sourceId":"sd518de2552","pages":[1]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-2주-문제1-2":{"primary":{"sourceId":"s3844552031","pages":[1]},"related":[{"sourceId":"sd518de2552","pages":[1]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-2주-문제1-3":{"primary":{"sourceId":"s3844552031","pages":[1]},"related":[{"sourceId":"sd518de2552","pages":[1,2]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-2주-문제1-4":{"primary":{"sourceId":"s3844552031","pages":[1]},"related":[{"sourceId":"sd518de2552","pages":[2]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":2,"supplement":false,"classMaterial":true},"class-2주-문제2-1":{"primary":{"sourceId":"s5f94d32e5d","pages":[1]},"related":[{"sourceId":"sbdd46b414e","pages":[1]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-2주-문제2-2":{"primary":{"sourceId":"s5f94d32e5d","pages":[1]},"related":[{"sourceId":"sbdd46b414e","pages":[1,2]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-2주-문제2-3":{"primary":{"sourceId":"s5f94d32e5d","pages":[1]},"related":[{"sourceId":"sbdd46b414e","pages":[2]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":2,"supplement":false,"classMaterial":true},"class-2주-문제2-4":{"primary":{"sourceId":"s5f94d32e5d","pages":[1,2]},"related":[{"sourceId":"sbdd46b414e","pages":[2,3]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":2,"supplement":false,"classMaterial":true},"class-2주-문제2-5":{"primary":{"sourceId":"s5f94d32e5d","pages":[2]},"related":[{"sourceId":"sbdd46b414e","pages":[3]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":3,"supplement":false,"classMaterial":true},"class-3주-사례1":{"primary":{"sourceId":"s3e7fff1fe8","pages":[1]},"related":[{"sourceId":"s1deb1ca0bb","pages":[1,2,3]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-3주-사례2":{"primary":{"sourceId":"s3e7fff1fe8","pages":[1]},"related":[{"sourceId":"s1deb1ca0bb","pages":[3,4,5,6]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":3,"supplement":false,"classMaterial":true},"class-3주-사례3":{"primary":{"sourceId":"s3e7fff1fe8","pages":[2]},"related":[{"sourceId":"s1deb1ca0bb","pages":[6,7,8,9]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":6,"supplement":false,"classMaterial":true},"class-3주-사례4-1":{"primary":{"sourceId":"s3e7fff1fe8","pages":[2]},"related":[{"sourceId":"s1deb1ca0bb","pages":[9,10]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":9,"supplement":false,"classMaterial":true},"class-3주-사례4-2":{"primary":{"sourceId":"s3e7fff1fe8","pages":[2]},"related":[{"sourceId":"s1deb1ca0bb","pages":[11,12]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":11,"supplement":false,"classMaterial":true},"class-4주-문1":{"primary":{"sourceId":"s05455e5f8f","pages":[1]},"related":[{"sourceId":"s7d6eb58f2f","pages":[1]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-4주-문2":{"primary":{"sourceId":"s05455e5f8f","pages":[1]},"related":[{"sourceId":"s7d6eb58f2f","pages":[1,2]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-4주-문3-1":{"primary":{"sourceId":"s05455e5f8f","pages":[2]},"related":[{"sourceId":"s7d6eb58f2f","pages":[2,3]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":2,"supplement":false,"classMaterial":true},"class-4주-문3-2":{"primary":{"sourceId":"s05455e5f8f","pages":[2,3]},"related":[{"sourceId":"s7d6eb58f2f","pages":[3,4]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":3,"supplement":false,"classMaterial":true},"class-4주-문3-3":{"primary":{"sourceId":"s05455e5f8f","pages":[2,3]},"related":[{"sourceId":"s7d6eb58f2f","pages":[4]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":4,"supplement":false,"classMaterial":true},"class-5주-문1":{"primary":{"sourceId":"s3fd74e102d","pages":[1]},"related":[{"sourceId":"sd944ab8460","pages":[1]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-5주-문2":{"primary":{"sourceId":"s3fd74e102d","pages":[1,2]},"related":[{"sourceId":"sd944ab8460","pages":[1,2]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-5주-문3":{"primary":{"sourceId":"s3fd74e102d","pages":[2]},"related":[{"sourceId":"sd944ab8460","pages":[2,3]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":2,"supplement":false,"classMaterial":true},"class-5주-문4":{"primary":{"sourceId":"s3fd74e102d","pages":[2]},"related":[{"sourceId":"sd944ab8460","pages":[3]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":3,"supplement":false,"classMaterial":true},"class-6주-문제1-1":{"primary":{"sourceId":"s27b66636e3","pages":[1]},"related":[{"sourceId":"sa8c509fa84","pages":[1]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-6주-문제1-2":{"primary":{"sourceId":"s27b66636e3","pages":[1]},"related":[{"sourceId":"sa8c509fa84","pages":[1,2]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":1,"supplement":false,"classMaterial":true},"class-6주-문제2-1":{"primary":{"sourceId":"s27b66636e3","pages":[2]},"related":[{"sourceId":"sa8c509fa84","pages":[2,3]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":2,"supplement":false,"classMaterial":true},"class-6주-문제2-2":{"primary":{"sourceId":"s27b66636e3","pages":[2]},"related":[{"sourceId":"sa8c509fa84","pages":[3]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":3,"supplement":false,"classMaterial":true},"class-6주-문제2-3":{"primary":{"sourceId":"s27b66636e3","pages":[2]},"related":[{"sourceId":"sa8c509fa84","pages":[3,4]}],"hasModelAnswer":true,"hasPrimaryModelAnswer":true,"answerRefIndex":1,"answerStart":3,"supplement":false,"classMaterial":true}},"transcripts":{"class-1주-문1":{"id":"class-1주-문1","question":{"segments":[{"sourceId":"sa975940342","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","pages":[1],"text":"<연습문제2>\n\n갑은 을을 상대로 금 1억 원의 지급을 구하는 매매대금 반환청구의 소를 제기하였다. 그 이후 진행된 1회 변론기일에 출석한 갑이 을과의 매매계약체결 사실을 주장하자 을은 ‘갑이 주장하는 매매계약의 성립 시에 나는 외국에 출장 중이었다’고 주장하였고 이에 대해 갑은 갑 자신과 을의 이름이 기재되어 있고 갑 자신의 인장과 을의 인장이 각 날인되어 있는 매매계약서를 증거방법으로 제출하였다. (아래 각 설문은 상호 독립적이고 무관한 것임).\n\n문1.\n\n갑은 2회 변론기일에 출석하여 ‘갑이 주장하는 매매계약의 성립 시에 외국에 출장 중이었다’는 을의 위 주장에 대하여 ‘이를 그대로 다 인정한다’고 진술하였다. 갑은 그 후 열린 3회 변론기일에 자신의 위 진술을 임의로 철회할 수 있는가? 아니면 법원은 이러한 갑의 진술을 반드시 판결의 기초로 삼아야 하는가? (15점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sa975940342","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","pages":[2],"text":"1. (15점)\n\n가. 결론\n\n갑은 자신의 진술을 임의로 철회할 수 있다(또는 법원은 이러한 갑의 진술을 반드시 판결의 기초로 삼아야 하는 것은 아니고 그와 다른 사실을 인정할 수 있다) (3점).\n\n나. 논거\n\n자백의 의의. 변론주의의 내용 중 하나로서 자백에는 법원 및 당사자에 대한 구속력이 발생. 그 대상이 되는 사실은 원칙적으로 주요사실에 한한다는 것이 통설, 판례의 입장. 그렇지 않을 경우 자유심증주의에 반하게 됨. 사안의 경우 을이 계약 성립 시에 외국에 출장 중이었다는 주장 내지 진술(현장에 부재하였다는 진술)은 갑이 주장, 증명책임을 부담하는 계약체결 사실과는 양립되지 않는 별개의 사실을 부가하면서 갑의 주장사실을 부정하는 것이기 때문에 이유부 부인에 해당함. 즉 이는 주요사실이 아니라 갑이 주장하는 계약체결사실의 부존재를 추인케 하는 간접사실에 불과하므로 이를 자백하였다 하더라도 자백으로서의 효력(구속력)은 발생하지 않는다(12점)."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-1주-문2":{"id":"class-1주-문2","question":{"segments":[{"sourceId":"sa975940342","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","pages":[1],"text":"<연습문제2>\n\n갑은 을을 상대로 금 1억 원의 지급을 구하는 매매대금 반환청구의 소를 제기하였다. 그 이후 진행된 1회 변론기일에 출석한 갑이 을과의 매매계약체결 사실을 주장하자 을은 ‘갑이 주장하는 매매계약의 성립 시에 나는 외국에 출장 중이었다’고 주장하였고 이에 대해 갑은 갑 자신과 을의 이름이 기재되어 있고 갑 자신의 인장과 을의 인장이 각 날인되어 있는 매매계약서를 증거방법으로 제출하였다. (아래 각 설문은 상호 독립적이고 무관한 것임).\n\n문2.\n\n법원은 2회 변론기일에 위 매매계약서에 대해 증거결정을 한 후 증거조사를 진행하였다. 을은 위 매매계약서에 대한 성립의 인부를 함에 있어 위 매매계약서에 찍혀 현출되어 있는 인영은 자신의 인장에 의한 것이지만(인영부분은 인정하지만), 자신은 스스로 날인행위를 한 적이 없다고 부인하였다. 을의 의사에 기한 날인행위가 있었는지의 여부에 관하여 진위불명에 빠진 경우, 법원은 위 차용증서의 진정성립을 인정할 수 있는가? (15점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sa975940342","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","pages":[2,3],"text":"2. (15점)\n\n가. 결론\n\n진정성립을 인정할 수 있다(3점).\n\n나. 논거\n\n차용증서는 사문서이다. 사문서의 경우 거증자가 그 진정성립을 증명하여야 한다(제357조). 그런데 제358조는 사문서에 본인이나 대리인의 의사에 기한 서명이나 날인 또는 무인이 있으면 진정성립이 추정됨을 규정하고 있다.\n\n사안에서와 같이 인영부분은 인정하되 날인사실을 부인한 경우, 통설과 판례는 이른바 2단의 추정이론으로 사문서 전체의 진정성립을 추정하고 있다(작성명의인의 인영부분이 인정되면 그의 의사에 기해 날인행위가 행하여졌음이 추정되므로1) 결국 제358조에 의하여 문서전체의 진정성립이 추정된다). 따라서 을의 인장의 도용사실 또는 모용사실에 대하여(즉 제3자에 의해 날인행위가 행하여졌음에 대하여) 증명을 하지 못해 진위불명 상태에 빠진 이상 차용증서의 진정성립은 추정되므로 진정성립을 인정할 수 있다(12점).\n\n【원문 각주】\n\n1) 다만, 날인행위가 을의 의사에 기한 것이라는 추정은 사실상 추정이므로 만약 날인행위가 문서작성명의인인 을이 아닌 타인에 의하여 행해진 것임이 밝혀지거나 을의 의사에 반하여(강박에 의하여) 또는 을의 의사에 기하지 않고(도용되어) 행해진 것임이 밝혀진 경우에는 그 추정이 깨어진다(대판 93다4151, 94다41324). 이와 같이 날인행위가 작성명의인 이외의 자에 의하여 이루어진 것임이 밝혀져 사실상 추정이 깨진 경우, 문서제출자는 그 날인행위가 작성명의인으로부터 위임받은 정당한 권원에 의한 것이라는 사실까지 증명할 책임이 있다(대판 94다41324)."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-1주-문3":{"id":"class-1주-문3","question":{"segments":[{"sourceId":"sa975940342","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","pages":[1],"text":"<연습문제2>\n\n갑은 을을 상대로 금 1억 원의 지급을 구하는 매매대금 반환청구의 소를 제기하였다. 그 이후 진행된 1회 변론기일에 출석한 갑이 을과의 매매계약체결 사실을 주장하자 을은 ‘갑이 주장하는 매매계약의 성립 시에 나는 외국에 출장 중이었다’고 주장하였고 이에 대해 갑은 갑 자신과 을의 이름이 기재되어 있고 갑 자신의 인장과 을의 인장이 각 날인되어 있는 매매계약서를 증거방법으로 제출하였다. (아래 각 설문은 상호 독립적이고 무관한 것임).\n\n문3.\n\n만약 갑이 제출한 위 차용증서의 진정성립이 인정된다면, 법원은 갑과 을 사이에 위 매매계약서의 기재 내용과 같은 매매계약체결 사실을 그대로 인정하여야 하는가? (15점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sa975940342","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","pages":[3],"text":"문3. (15점)\n\n가. 결론\n\n특별한 사정이 없는 이상 소비대차계약체결 사실을 인정하여야 한다(3점).\n\n나. 논거\n\n처분문서란? 실질적 증명력이란?\n\n처분문서의 경우 보고문서와는 달리 형식적 증거력이 인정되면 즉 진정성립이 인정되면 특별한 사정이 없는 이상 실질적 증거력이 인정된다. 차용증서는 증명하고자 하는 소비대차계약이라는 법률행위의 존재를 나타내는 처분문서이므로 그 진정성립이 인정되면 특별한 사정이 없는 이상(그 기재내용을 부정해야 할 정도로 분명하고도 확실한 반증이 없는 이상) 그에 기재되어 있는 문언대로 소비대차계약이 체결된 사실을 인정하여야 한다(12점)."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-1주-문4":{"id":"class-1주-문4","question":{"segments":[{"sourceId":"sa975940342","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","pages":[1],"text":"<연습문제2>\n\n갑은 을을 상대로 금 1억 원의 지급을 구하는 매매대금 반환청구의 소를 제기하였다. 그 이후 진행된 1회 변론기일에 출석한 갑이 을과의 매매계약체결 사실을 주장하자 을은 ‘갑이 주장하는 매매계약의 성립 시에 나는 외국에 출장 중이었다’고 주장하였고 이에 대해 갑은 갑 자신과 을의 이름이 기재되어 있고 갑 자신의 인장과 을의 인장이 각 날인되어 있는 매매계약서를 증거방법으로 제출하였다. (아래 각 설문은 상호 독립적이고 무관한 것임).\n\n문4.\n\n만약 을이 위 매매계약서에 대한 날인사실을 인정한 후, 위 매매계약서가 백지상태로 작성·교부되었고, 갑이 추후 위 매매계약서에 그 내용을 기재한 것(즉 백지부분을 보충한 것)이라는 사실을 증명하였다면, 법원은 그 상태에서 위 매매계약서의 진정성립을 인정할 수 있는가? (15점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sa975940342","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","pages":[3],"text":"문4. (15점)\n\n가. 결론\n\n갑이 을로부터 백지부분(미완성부분)의 보충 내지 그에 관한 작성권한을 위임받았다는 사실을 증명하지 못하는 한 진정성립을 인정해서는 안 된다(3점).\n\n나. 논거\n\n이른바 2단의 추정이론은 사문서의 내용이 먼저 기재되어 완성된 상태에서 서명이나 날인이 행해진 경우에만 적용되는 것이고, 사안에서와 같이 문서가 미완성 상태에서 서명이나 날인이 행해진 경우에는 적용되지 않는다. 따라서 위 차용증서가 백지상태로 작성·교부되었고, 갑이 추후 위 차용증서에 그 내용을 기재한 것(백지부분을 보충한 것)이라는 사실이 증명된 이상, 거증자인 갑은 을로부터 백지부분의 보충 등 그 작성에 관한 권한을 위임받았음을 증명하여야 하고(증명책임), 이를 증명하지 못하면 위 차용증서의 진정성립은 인정될 수 없다(12점)."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-1주-문5":{"id":"class-1주-문5","question":{"segments":[{"sourceId":"sa975940342","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","pages":[1],"text":"<연습문제2>\n\n갑은 을을 상대로 금 1억 원의 지급을 구하는 매매대금 반환청구의 소를 제기하였다. 그 이후 진행된 1회 변론기일에 출석한 갑이 을과의 매매계약체결 사실을 주장하자 을은 ‘갑이 주장하는 매매계약의 성립 시에 나는 외국에 출장 중이었다’고 주장하였고 이에 대해 갑은 갑 자신과 을의 이름이 기재되어 있고 갑 자신의 인장과 을의 인장이 각 날인되어 있는 매매계약서를 증거방법으로 제출하였다. (아래 각 설문은 상호 독립적이고 무관한 것임).\n\n문5.\n\n만약 을이 위 매매계약서에 대한 성립의 인부절차에서 진정성립을 인정하였다가 그 후 소송절차가 불리하게 진행되자 위 매매계약서가 위조된 것이라고 하면서 이를 부인하는 항변을 제출하였다면 법원은 이에 대하여 어떻게 판단하여야 하는가? (10점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sa975940342","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","pages":[3,4],"text":"문5. (10점)\n\n가. 결론\n\n특별한 사정이 없는 한 위조항변을 배척하여야 한다(3점).\n\n나. 논거\n\n문서의 진정성립에 관한 자백은 보조사실에 관한 것이지만 이에 대하여 재판상 자백과 같은 구속력이 인정된다(판례). 따라서 법원은 이를 기초로 판단하여야 하고(차용증서의 진정성립을 인정하여야 하고) 당사자는 이에 관한 자백을 취소하거나 철회할 수 없다. 당사자가 이를 취소 내지 철회하기 위해서는 상대방의 동의가 있거나, 진실에 반하고 착오로 인해 자백하였음을 증명하거나 그 자백이 형사상 처벌받을 제3자의 행위로 인하여 행하여졌다는 점을 증명하여야만 한다(7점)."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-2주-문제1-1":{"id":"class-2주-문제1-1","question":{"segments":[{"sourceId":"s3844552031","sourceFile":"민사소송법사례연습 2주차 문제1.txt","pages":[1],"text":"〈 2021.2학기 민소법연습 기말시험문제 〉\n\n을은 갑 소유의 2층 건물을 갑의 아들 A로부터 임차하여 사용하고 있던 중 위 건물 중 1층 부분을 병에게 임대(전대)하여 줌으로써 현재 을은 위 건물 중 2층 부분을, 병은 1층 부분을 각 점유, 사용하고 있다. 이에 대하여 갑은 을과 병이 권원 없이 위 건물을 점유, 사용하고 있다고 주장하면서 을과 병을 상대로 소유권에 기한 각 점유부분의 인도 및 그 부분의 사용, 수익으로 인한 차임 상당의 부당이득반환청구의 소(이하 '전소' 라고 한다)를 제기하였다. 갑은 전소와 관련하여 점유이전금지가처분 등 보전처분을 하지 않았다.\n\n* 아래의 각 설문은 상호 독립적이고 무관한 것임.\n\n1. 만약 갑이 '병이 정에게 1층 부분을 다시 임대(전대)하여 현재 정이 1층 부분을 점유하고 있다는 사실' 을 전소의 사실심 변론종결 이전에 알았다면, 갑은 정에 대하여 어떠한 소송법적 조치를 할 수 있는가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sd518de2552","sourceFile":"민사소송법사례연습 2주차 답안1.txt","pages":[1],"text":"1. (20점)\n\n가. 정은 병으로부터 그 점유부분을 전대받아 점유 중인 자로서 정을 병의 승계인으로 볼 수 있는지를 검토해야 한다(2점).\n\n나. 승계인의 범위\n\n소송물인 권리관계 자체를 승계한 자뿐만 아니라 그 계쟁물을 승계 받은 자도 승계인에 포함된다. 사안의 경우 정은 물권적 청구권을 소송물로 하는 소송의 사실심 변론종결 이전에 피고로부터 계쟁물의 일부를 넘겨받았으므로 피고 적격의 승계인에 해당한다. 따라서 소송계속 중 제3자가 소송목적인 의무의 목적물을 승계한 경우에 해당되어 갑은 정으로 하여금 소송을 인수하게 할 수 있다(민소법 제82조 제1항). (15점)\n\n다. 결론: 갑은 정을 상대로 병의 지위를 이어받도록 하는 인수승계신청을 할 수 있다(3점)."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-2주-문제1-2":{"id":"class-2주-문제1-2","question":{"segments":[{"sourceId":"s3844552031","sourceFile":"민사소송법사례연습 2주차 문제1.txt","pages":[1],"text":"〈 2021.2학기 민소법연습 기말시험문제 〉\n\n을은 갑 소유의 2층 건물을 갑의 아들 A로부터 임차하여 사용하고 있던 중 위 건물 중 1층 부분을 병에게 임대(전대)하여 줌으로써 현재 을은 위 건물 중 2층 부분을, 병은 1층 부분을 각 점유, 사용하고 있다. 이에 대하여 갑은 을과 병이 권원 없이 위 건물을 점유, 사용하고 있다고 주장하면서 을과 병을 상대로 소유권에 기한 각 점유부분의 인도 및 그 부분의 사용, 수익으로 인한 차임 상당의 부당이득반환청구의 소(이하 '전소' 라고 한다)를 제기하였다. 갑은 전소와 관련하여 점유이전금지가처분 등 보전처분을 하지 않았다.\n\n* 아래의 각 설문은 상호 독립적이고 무관한 것임.\n\n2. 전소에서 제1심법원은 갑의 청구를 전부 인용하는 판결을 선고하였고, 그 판결은 그대로 확정되었다. 그 이후에 진행된 강제집행절차에서 병이 위 판결 확정 후 위 건물 중 1층 부분을 정에게 전대하여 정이 그 부분을 점유, 사용하고 있다는 사실이 밝혀지자 갑은 정을 상대로 전소에서와 같은 청구취지의 소(후소)를 제기하였다. 법원은 이에 대하여 어떤 판결을 선고하여야 하는가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sd518de2552","sourceFile":"민사소송법사례연습 2주차 답안1.txt","pages":[1],"text":"2. (20점)\n\n가. 병에 대한 확정판결의 효력이 정에게 확장되는 것인가가 쟁점이다. 이는 갑과 병 간의 소송의 소송물이 물권적 청구권에 기한 것인가 채권적 청구권에 기한 것인가의 여부, 정의 점유시점이 변론종결 후인지의 여부에 따라서 결정된다(2점).\n\n나. 기판력의 주관적 범위\n\n본 사안의 경우 갑과 병 간의 소송의 소송물은 물권적 청구권에 기한 것으로서 정은 변론종결 이후부터 위 건물 일부를 점유하게 되었다. 따라서 판례에 따르면 정은 변론종결 후에 계쟁물을 양수한 승계인에 해당하여 그에 대해 기판력이 미치게 된다(민사소송법 제218조 제1항). 따라서 갑은 승계집행문을 부여받아 정에 대하여 강제집행을 할 수 있다(15점).\n\n다. 그럼에도 갑이 동일한 소송물에 대하여 소를 제기한 것은 소의 이익이 없으므로 법원은 그 소를 각하하는 판결을 선고하여야 한다(3점)."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-2주-문제1-3":{"id":"class-2주-문제1-3","question":{"segments":[{"sourceId":"s3844552031","sourceFile":"민사소송법사례연습 2주차 문제1.txt","pages":[1],"text":"〈 2021.2학기 민소법연습 기말시험문제 〉\n\n을은 갑 소유의 2층 건물을 갑의 아들 A로부터 임차하여 사용하고 있던 중 위 건물 중 1층 부분을 병에게 임대(전대)하여 줌으로써 현재 을은 위 건물 중 2층 부분을, 병은 1층 부분을 각 점유, 사용하고 있다. 이에 대하여 갑은 을과 병이 권원 없이 위 건물을 점유, 사용하고 있다고 주장하면서 을과 병을 상대로 소유권에 기한 각 점유부분의 인도 및 그 부분의 사용, 수익으로 인한 차임 상당의 부당이득반환청구의 소(이하 '전소' 라고 한다)를 제기하였다. 갑은 전소와 관련하여 점유이전금지가처분 등 보전처분을 하지 않았다.\n\n* 아래의 각 설문은 상호 독립적이고 무관한 것임.\n\n3. 전소에서 1심법원은 갑의 청구를 모두 기각하는 판결을 선고하였고, 그 판결은 그대로 확정되었다. 갑은 그 이후 위 2층 건물 전부를 정에게 매도하고 그에 관한 소유권이전등기를 경료하여 주었는데, 정은 을과 병을 상대로 갑이 제기한 전소와 같은 내용의 소(후소)를 제기하였다. 정이 제기한 후소는 확정판결의 기판력에 저촉되는 것인가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sd518de2552","sourceFile":"민사소송법사례연습 2주차 답안1.txt","pages":[1,2],"text":"3. (20점)\n\n가. 정의 을과 병에 대한 인도청구 부분에 관하여\n\n- 건물 소유권에 기한 물권적 청구권을 원인으로 하는 건물인도청구소송의 소송물은 건물 소유권이 아니라 그 물권적 청구권인 건물인도청구권이므로 그 소송에서 청구기각된 확정판결의 기판력은 건물인도청구권의 존부 그 자체에만 미치는 것이고, 소송물이 되지 아니한 건물 소유권의 존부에 관하여는 미치지 아니하므로, 그 건물인도소송의 사실심 변론종결 후에 그 패소자인 건물 소유자 갑으로부터 건물을 매수하고 소유권이전등기를 마침으로써 그 소유권을 승계한 정의 건물 소유권의 존부에 관하여는 위 확정판결의 기판력이 미치지 않는다. 또한 이 경우 정이 가지게 되는 물권적 청구권인 건물인도청구권은 적법하게 승계한 건물 소유권의 일반적 효력으로서 발생된 것이고, 위 건물인도소송의 소송물인 패소자 갑의 건물명도청구권을 승계함으로써 가지게 된 것이라고는 할 수 없으므로, 정은 위 확정판결의 변론종결 후의 승계인에 해당한다고 할 수 없다(대법원 1999. 10. 22. 선고 98다6855 판결 참조)(9점).\n\n- 따라서 정의 이 부분 청구는 확정판결의 기판력에 저촉되지 않는다(1점).\n\n나. 정의 을과 병에 대한 부당이득반환청구에 관하여\n\n- 갑이 받는 확정판결의 기판력이 정에게 확장되는 것인가가 쟁점이다. 판례에 의하면 이는 갑이 을과 병을 상대로 제기한 전소의 소송물이 물권적 청구권에 기한 것인가 채권적 청구권에 기한 것인가의 여부에 따라 결정된다. 건물의 소유자인 갑이 소유권에 기하여 을과 병이 무단 점유자임을 주장하면서 이들을 상대로 차임 상당의 부당이득반환을 구하는 소송을 제기하여 그에 관한 판결이 확정된 경우, 이러한 소송의 소송물은 채권적 청구권인 부당이득반환청구권이므로, 전소의 변론종결 후에 건물의 소유권을 취득한 정은 민사소송법 제218조 제1항에 의하여 확정판결의 기판력이 미치는 변론을 종결한 뒤의 승계인에 해당한다고 볼 수 없다(대법원 2016.6.28. 선고 2014다31721 판결 참조)(9점).\n\n- 따라서 정의 이 부분 청구는 확정판결의 기판력에 저촉되지 않는다(1점)."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-2주-문제1-4":{"id":"class-2주-문제1-4","question":{"segments":[{"sourceId":"s3844552031","sourceFile":"민사소송법사례연습 2주차 문제1.txt","pages":[1],"text":"〈 2021.2학기 민소법연습 기말시험문제 〉\n\n을은 갑 소유의 2층 건물을 갑의 아들 A로부터 임차하여 사용하고 있던 중 위 건물 중 1층 부분을 병에게 임대(전대)하여 줌으로써 현재 을은 위 건물 중 2층 부분을, 병은 1층 부분을 각 점유, 사용하고 있다. 이에 대하여 갑은 을과 병이 권원 없이 위 건물을 점유, 사용하고 있다고 주장하면서 을과 병을 상대로 소유권에 기한 각 점유부분의 인도 및 그 부분의 사용, 수익으로 인한 차임 상당의 부당이득반환청구의 소(이하 '전소' 라고 한다)를 제기하였다. 갑은 전소와 관련하여 점유이전금지가처분 등 보전처분을 하지 않았다.\n\n* 아래의 각 설문은 상호 독립적이고 무관한 것임.\n\n4. 전소에서 제1심 법원은 갑의 청구를 전부 인용하는 판결을 선고하였는데, 이에 대하여 을만이 항소하였다. 항소법원이 심리한 결과 갑의 청구가 부당하다고 판단되면 항소심 법원은 병에 대하여서도 1심 법원의 판결내용과 다른 판결을 선고할 수 있는가? (10점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sd518de2552","sourceFile":"민사소송법사례연습 2주차 답안1.txt","pages":[2],"text":"4. (10점)\n\n- 갑이 을과 병을 상대로 하는 소송은 민소법 제65조 후문에 해당되는 통상공동소송이다. 따라서 공동소송인 독립의 원칙이 적용된다. 위 원칙의 개념(민소법 제66조)을 설시해야 한다. 그에 따라 을만이 항소할 경우 갑과 병 사이의 판결은 분리되어 확정된다(5점).\n\n- 결론적으로 피고 을만 항소하였으므로 그 항소의 효력은 병에게 미치지 않고 병에 대한 판결은 분리되어 그대로 확정되므로 항소심의 심판대상이 아니다. 따라서 항소심 법원은 병에 대하여는 1심법원의 판결내용과 다른 판결을 선고할 수 없다(5점)."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-2주-문제2-1":{"id":"class-2주-문제2-1","question":{"segments":[{"sourceId":"s5f94d32e5d","sourceFile":"민사소송법사례연습 2주차 문제2.txt","pages":[1],"text":"문1. 갑은 을을 상대로 매매를 원인으로 한 A부동산에 관한 소유권이전등기 청구의 소를 제기하여 승소판결을 받았다. 그 후 항소심 계속 중에 갑은 을과의 사이에 을로부터 A부동산 대신에 금 1억원을 지급받기로 하고 계속 중인 소를 취하하기로 하는 내용의 화해계약을 소송 외에서 체결한 다음, 위 소를 취하하였다. 그런데 을은 위 화해계약에 반하여 위 금 1억원을 지급하지 않고 있는데, 갑이 그 이유를 확인해 본 결과, 을은 애시당초부터 위 돈을 지급할 의사나 능력도 없는 상태에서 갑을 속이고 갑과 화해계약을 체결하였음을 확인하게 되었다. 갑은 을로부터 A부동산에 관한 소유권이전등기를 넘겨오고 싶은데, 이를 위하여 소송법상 어떠한 법적 수단을 취할 수 있는가? (30점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sbdd46b414e","sourceFile":"민사소송법사례연습 2주차 답안2.txt","pages":[1],"text":"문1.\n\n1. 문제의 소재 (2점)\n\n절차의 명확성과 안정성의 요청 때문에 민법상 의사표시의 하자에 관한 규정은 소송행위에 적용되지 않음이 원칙. 다만, 소의 취하와 같은 소송행위가 사기 등 제3자의 형사상 처벌받을 행위로 인하여 행해졌을 때, 소송법상 이에 대한 구제방법을 인정하는 것이 일반적인 견해임. 소취하의 무효를 주장하면서 변론기일 지정신청을 하는 방법과 다시 소유권이전등기청구의 소를 제기하는 방법을 생각할 수 있는데, 후자의 경우 재소금지에 해당하는 것은 아닌지의 문제가 있음.\n\n2. 변론기일 지정신청(14점)\n\n소의 취하가 형사상 처벌할 타인의 행위로 인하여 행해진 경우, 민소법 제451조 제1항 제5호의 규정을 유추 적용하여 그 효력을 부인할 수 있다고 보는 것이 판례와 다수설의 입장임. 이 때 유죄의 확정판결이 필요하다고 하는 입장(판례)과 불필요하다고 보는 입장(다수설)이 대립. 이에 따라 갑은 민소법 제165조 제1항, 민소규칙 제67조 제1항에 의거하여 소송종료의 효과를 다투면서 기일지정신청을 할 수 있을 것임. 법원은 기일지정신청에 대하여 변론을 열어 신청사유에 대하여 심리한 뒤, 소의 취하가 무효라고 인정되면 본안에 관한 변론절차를 속행하고 소의 취하가 유효라고 인정되면 소송종료선언을 하게 될 것임.\n\n3. 소유권이전등기청구의 소 제기(14점)\n\n갑은 본안에 대한 종국판결선고 후 소를 취하해 놓고서 다시 동일한 소(당사자와 소송물이 동일한 소)를 제기하게 되는 것이므로 재소금지에 해당되지 않는가라는 의문이 있을 수 있음. 그러나 후소가 전소와 동일한 소라 할지라도 전소와 권리보호의 이익을 달리할 경우에는 재소금지의 원칙이 부적용된다는 것이 판례 및 통설의 입장. 사안의 경우 을이 소 취하의 전제조건으로 하였던 금전지급의무를 이행하지 않음으로써 갑, 을간의 약정은 해제 또는 실효되는 사정변경이 발생하였음을 갑이 주장하면서 재소할 경우 이는 새로운 권리보호의 이익 내지 필요성이 인정된다 할 것임."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-2주-문제2-2":{"id":"class-2주-문제2-2","question":{"segments":[{"sourceId":"s5f94d32e5d","sourceFile":"민사소송법사례연습 2주차 문제2.txt","pages":[1],"text":"문2. 갑은 을을 상대로 주위적으로, 을과의 A물건에 관한 매매계약이 유효함을 전제로 그 매매대금의 지급을 청구하면서, 매매계약이 무효로 판단되는 것에 대비하여 예비적으로 이미 인도한 A물건의 반환을 구하는 소를 제기하였다. 그런데 법원은 매매대금지급 청구를 기각하는 판결만을 선고하였을 뿐, A물건 반환청구에 관하여는 아무런 판단을 하지 아니하였다. 이에 대해 갑은 항소를 하지 않은 채 위 제1심 판결을 그대로 확정시킨 뒤 다시 별도로 위 매매계약의 무효를 이유로 한 A물건의 반환청구의 소를 제기하였는데 이는 허용되는 것인가? (10점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sbdd46b414e","sourceFile":"민사소송법사례연습 2주차 답안2.txt","pages":[1,2],"text":"문2.\n\n1. 결론 • 허용되지 않는다.\n\n2. 이유 또는 근거\n\n선택적, 예비적 병합의 경우, 병합된 여러 개의 청구는 동일한 절차에 불가분적으로 결합되어 있기 때문에 일부판결을 선고할 수 없다(통설, 판례). 사안에서와 같이 법원이 주위적 청구만을 배척하고 예비적 청구에 대한 판단을 하지 않은 경우 이는 재판의 누락이 아니라 판단누락으로 보는 것이 통설, 판례임. 즉 예비적 병합의 경우와 성질상 일부판결이 허용되지 않는 소송에서는 재판의 누락이 있을 수 없으므로 추가판결로 시정할 것이 아니고 병합의 성질상 하나의 전부판결이라고 볼 것이므로 판단 누락에 준하여 상소로 다투어야 함. 따라서 이 경우 갑이 판단누락한 예비적 청구부분을 간편한 분쟁해결수단인 항소로 다투지 아니하고 이를 그대로 확정시킨 뒤 다시 별소를 제기한 것은 권리보호의 이익이 없어 부적법하게 되기 때문이다."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-2주-문제2-3":{"id":"class-2주-문제2-3","question":{"segments":[{"sourceId":"s5f94d32e5d","sourceFile":"민사소송법사례연습 2주차 문제2.txt","pages":[1],"text":"문3. 갑은 그 소유의 A토지를 을에게 임대하였고, 을은 A토지 지상에 건물을 신축하여 이를 소유하고 있다. 갑은 임대차계약 기간이 종료되었음을 이유로 을을 상대로 A 토지 지상에 건립된 건물의 철거 및 A토지의 인도를 구하는 소를 제기하였는데, 을은 갑에게 임대차계약 종료에 따른 건물매수청구권을 행사할 수 있었음에도 이를 행사하지 않는 바람에 결국 패소하여 그 판결이 확정되었다. 그 후 을은 갑을 상대로 건물매수청구권을 행사하면서 그 대금청구를 하는 소를 제기하였는데 이는 허용되는 것인가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sbdd46b414e","sourceFile":"민사소송법사례연습 2주차 답안2.txt","pages":[2],"text":"문3.\n\n1. 문제의 소재 (5점)\n\n기판력의 시점 범위, 표준시(사실심 변론종결시) 이후에 을이 건물매수청구권을 행사하면서 대금청구의 소를 제기하는 것이 기판력의 실권효 또는 차단효에 의해 금지되는가의 여부가 문제의 핵심임.\n\n2. 학설의 입장 (5점)\n\n실권설, 비실권설, 절충설(을이 매수청구권이 있음을 알았음에도 행사하지 않은 경우에는 실권되지만, 몰랐을 경우에는 실권되지 않는다)이 대립됨.\n\n3. 결론 (10점)\n\n건물매수청구권은 취소권, 해제권 등과 같이 소송물인 권리관계 자체에 부착된 권리가 아니고 이러한 권리를 언제 행사할 것인가는 권리자의 자유에 속하는 것이다. 또한 전소인 건물철거 및 토지인도청구의 소와 후소인 대금지급청구의 소는 그 소송물을 달리한다. 따라서 확정판결에 기하여 건물철거가 집행되지 아니한 이상 대금지급 청구의 소는 허용된다."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-2주-문제2-4":{"id":"class-2주-문제2-4","question":{"segments":[{"sourceId":"s5f94d32e5d","sourceFile":"민사소송법사례연습 2주차 문제2.txt","pages":[1,2],"text":"문4. 갑은 을을 상대로 1000만원의 지급을 구하는 소송을 제기하였는데, 이에 대하여 을은 1500만원의 매매대금채권을 가지고 상계한다는 취지의 항변을 제출하였다. 이 소송에서 상계의 항변이 인정되었고 결국 갑의 청구는 기각되어 그 판결이 확정되었다. 그 후,\n\n(1) 갑이 을의 채권은 애시당초부터 부존재하였다고 주장하면서 부당이득반환청구의 소를 제기하였는데 이는 허용되는 것인가? (10점)\n\n(2) 을이 갑의 채권은 애시당초부터 부존재하였다고 주장하면서 부당이득반환청구의 소를 제기하였는데 이는 허용되는 것인가? (10점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sbdd46b414e","sourceFile":"민사소송법사례연습 2주차 답안2.txt","pages":[2,3],"text":"문4의 (1)(2)\n\n1. 결론 : 모두 허용되지 않는다.\n\n2. 이유 또는 근거\n\n피고가 상계항변을 제출하였을 경우에 자동채권의 존부에 대하여 비록 판결이유 중에서 판단하게 되지만 상계로써 대항한 액수의 한도 내에서는 기판력이 생긴다(민소법 제216조 제2항). 상계항변이 채택되어 인정된 경우 어느 범위에 관하여 기판력이 인정되는가에 관하여 현재 반대채권(자동채권)이 소멸되어 존재하지 않는다는 점에 기판력이 생긴다는 견해와 소구채권(수동채권)과 반대채권이 함께 존재하였다가 그것이 상계에 의하여 소멸된다는 점에 기판력이 생긴다는 견해가 대립됨. 후자가 통설이지만 어떤 견해에 의하든 부당이득을 원인으로 한 재소가 금지된다는 점에 있어서는 동일함. 결국 사안(1)에서와 같이 원고인 갑이 반대채권이 당초부터 존재하지 않는다고 주장하면서 부당이득반환청구를 하는 것이나 사안(2)에서와 같이 피고인 을이 소구채권이 당초부터 존재하지 않는다고 주장하면서 부당이득반환청구를 하는 것은 기판력에 저촉되는 것으로써 허용되지 아니한다."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-2주-문제2-5":{"id":"class-2주-문제2-5","question":{"segments":[{"sourceId":"s5f94d32e5d","sourceFile":"민사소송법사례연습 2주차 문제2.txt","pages":[2],"text":"문5.\n\n(1) 고의에 의한 명예훼손을 원인으로 한 손해배상청구의 본소에 대하여 전혀 별개의 사실을 이유로 하는 영업방해에 의한 손해배상청구의 반소를 제기하는 것은 허용되는가? (10점)\n\n(2) 고의에 의한 상해행위를 원인으로 한 손해배상청구의 본소에 대하여 대여금채권으로 상계를 주장함과 아울러 나머지 대여금의 지급을 구하는 반소를 제기하는 것은 허용되는가? (10점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sbdd46b414e","sourceFile":"민사소송법사례연습 2주차 답안2.txt","pages":[3],"text":"문5의 (1)\n\n1. 결론 : 허용되지 않는다.\n\n2. 근거\n\n고의에 의한 명예훼손을 원인으로 한 손해배상청구의 본소에 대하여 전혀 별개의 사실을 이유로 하는 영업방해에 의한 손해배상청구의 반소를 제기한 경우, 양소의 청구 사이에 관련성이 없고 또한 본소에 대한 방어방법과도 관련성이 없으므로 반소의 요건을 갖추지 못하여 부적법하기 때문이다.\n\n문5의 (2)\n\n1. 결론 : 허용되지 않는다\n\n2. 이유\n\n반소의 요건 가운데 하나는, 반소가 본소에 대한 방어방법과 관련성이 있어야 하는 것인데 이에 해당하기 위해서는 방어방법이 현실적으로 제출되어야 하고 또한 법률상 허용되는 적법한 것이어야 한다. 따라서 사안에서와 같이 상계금지채권에 기한 원고의 본소청구에 대하여 피고가 상계주장 내지 항변을 하는 것은 민법상 금지되어 있으므로(제496조) 이러한 경우 이에 바탕을 둔 반소는 부적법한 것이 되기 때문이다."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-3주-사례1":{"id":"class-3주-사례1","question":{"segments":[{"sourceId":"s3e7fff1fe8","sourceFile":"민사소송법사례연습 3주차 문제.txt","pages":[1],"text":"<사례문제 1>\n\n갑은 2021.10.16. 을에게 5,000만원을 변제기 2021.12.16., 이율 월 1%로 정하여 대여하였는데, 을이 변제기가 지나도록 변제를 하지 아니하자 2022.5.1. 을을 상대로 대여금 청구의 소를 제기한 후 1차 변론기일에 출석하여 위 사실을 주장하였다. 이에 대해 을이 청구기각 판결을 구하면서 원고의 주장사실을 전부 부인하였고 법원은 피고 을의 신청에 따라 병을 증인으로 채택한 후 변론기일이 속행되었는데, 속행된 변론기일에 증인으로 출석한 병은 ‘갑이 2021.10.16. 을에게 5,000만원을 대여하는 장면과 을이 변제기로부터 두 달이 지난 2021.12.16. 갑에게 5,000만원과 이에 대한 2개월 치의 이자를 지급하는 장면을 직접 목격했다’고 증언하였다. 법원이 이와 같은 증인신문을 마친 후 그대로 변론을 종결하였다면 법원은 위 증언을 토대로 하여 갑의 대여사실과 을의 변제사실을 인정하여 원고의 청구를 기각하는 판결을 할 수 있는가?\n\n<2010년 사법시험문제를 각색한 것임>"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"s1deb1ca0bb","sourceFile":"민사소송법사례연습 3주차 답안.txt","pages":[1,2,3],"text":"〈 사례문제 1의 해결〉\n\n1. 문제의 소재\n\n사안에서는 먼저 갑의 대여사실과 관련하여 자유심증주의의 한 내용인 증거공통원칙에 따라 피고의 증인신청에 따라 법원에 현출된 병의 증언에 의하여 대여사실을 인정할 수 있는 것인지가 문제 되고, 을의 변제사실과 관련하여 변제사실이 변론주의의 주요 내용 중 하나인 사실의 주장책임의 적용대상이 되는 주요사실에 해당되는 것인지와 주요사실에 해당된다면 사실자료와 증거자료는 준별되어야 한다는 주장책임의 내용에 따라 피고의 변제사실에 관한 주장이 없으므로 법원은 병의 증언(증거자료)에 의하여 변제 사실을 인정해서는 안 되는 것인지 그렇다면 판례가 인정하는 간접적 주장이론을 본 사안에 적용할 수는 있는 것인지 등이 문제된다,\n\n2. 대여사실의 인정여부\n\n(1) 자유심증주의와 증거공통의 원칙\n\n자유심증주의란 법원이 형식적인 증거법칙의 제약을 받지 않고서 변론 전체의 취지와 증거조사의 결과인 증거자료를 참작하여 그에 따라 형성된 자유로운 심증으로 재판의 기초가 되는 주장사실의 진위여부(眞僞與否)를 판단한다는 원칙을 말한다. (민사소송법 제202조). 이에 따라 법원은 증거방법이나 증거능력에 관한 제한을 받지 않을 뿐만 아니라 당사자가 제출한 증거에 대한 증거력평가를 자유롭게 할 수 있기 때문에 증거에 대한 증거조사의 결과(증거자료)를 증거제출자에게 유리하게 평가(판단)할 수도 있고 즉, 유리한 사실의 인정자료로 삼을 수도 있고 반대로 상대방의 원용에 관계없이 그 제출자에게 불리하게도 평가할 수 있게, 즉 불리한 사실의 인정자료로도 삼을 수 있게 되는데 이를 증거공통의 원칙이라고 한다.1)\n\n(2) 사안의 경우\n\n갑은 청구원인사실로서 대여사실을 주장하고 있고 을의 신청에 따라 증인으로 채택된 병이 을에게 불리한 대여사실을 증언하였는데, 이러한 경우 법원은 증거공통의 원칙에 따라 증거조사의 결과인 병의 증언에 의하여 을에게 불리한 사실이라 할 수 있는 대여사실을 인정할 수 있다.\n\n3. 변제사실의 인정여부\n\n(1) 변론주의의 의의와 기능\n\n변론주의란 사실과 증거의 수집 • 제출책임을 당사자에게 맡기고 법원은 당사자가 수집하여 제출한 소송자료만을 판결의 기초로 삼아야 한다는 입장이다. 이는 사적 자치의 원칙을 소송법상 반영한 것임과 동시에 이에 의할 때 진실발견이 용이해지고 절차보장이 충실하게 됨으로써 공평한 재판이 보장된다는 점 등이 그 인정 근거로 설명되고 있고, 우리 민사소송절차를 관류하는 대원칙으로서 당사자에 대한 불의의 타격 즉 예상외 재판을 방지하는 기능을 수행한다. 변론주의는 사실의 주장책임, 자백의 구속력, 증거의 제출책임(직권증거조사 금지)등 세 가지 명제를 주요내용으로 하고 있는데, 사안에서는 변제사실이 주장책임의 적용대상이 되는 것인지가 문제된다.\n\n(2) 사실의 주장책임\n\n1) 의의\n\n권리의 발생 • 변경 • 소멸 즉 권리의 변동이라는 법률효과를 발생시키는 원인이 되는 실체법상의 구성요건사실인 주요사실은 당사자가 변론에서 주장하여야만 법원이 판결의 기초로 삼을 수 있고 주장하지 아니하면 판결의 기초로 삼을 수 없다. 따라서 당사자가 자기에게 유리한 사실을 주장하지 아니하면 그 사실은 없는 것으로 취급되어 불이익한 판단을 받게 되는데 이를 주장책임이라고 한다. 이와 같이 주장책임의 적용대상이 되는 사실은 주요사실로서 경험법칙 등의 도움을 받아 주요사실의 존부를 추인하게 하는 사실인 간접사실과 증거능력이나 증거가치에 관한 사실인 보조사실은 그 적용대상이 아니다.\n\n2) 주장책임의 분배 및 사실자료와 증거자료의 준별\n\n통설, 판례의 입장인 법률요건분류설에 따라 원고 또는 피고가 유리한 판결을 받기 위해서 원고는 청구원인사실(권리발생사실)을, 피고는 항변사실(권리장애사실, 권리멸각사실, 권리저지사실)을 주장하여야 하므로 원, 피고는 각각 그에 따른 주장책임을 부담하게 된다. 사안에 있어서와 같이 갑이 주장한 대여사실에 대한 관계에서 변제사실은 항변사실(권리멸각사실)로서 주요사실에 해당하므로 을이 그 사실을 주장하지 않은 이상 법원은 증인의 증언이나 그 밖의 증거자료에 의하여 변제사실을 알았다 하더라도 이를 판결의 기초로 삼아서는 안 된다. 왜냐하면 변론주의에 의해 심리되는 민사소송사건에서 사실자료는 증거자료와 엄격하게 구별되어야 하기 때문이다,2)\n\n3) 간접적 주장이론\n\n① 위와 같이 사실자료와 증거자료를 준별하는 입장을 강조하게 되면 때로는 부당한 결과가 생기게 되는데 이러한 경우에 대비하여 대법원은 간접적 주장이론을 인정하고 있다. 이는 당사자가 변론에서 직접적으로 주요사실을 주장하지는 않았다 하더라도 법원에 현출된 소송자료나 증거자료를 통해 일정한 경우 당사자가 그 사실을 주장한 것으로 의제하는 것을 말한다. 예컨대 당사자가 법원에 서증을 제출하면서 그 증명취지를 진술함으로써 서증에 기재된 사실을 주장한 경우나 당사자가 감정서나 서증을 이익으로 원용한 경우등에 있어서 주요사실에 관한 주장을 한 것으로 보는 것이다.3)\n\n② 사안의 경우\n\n을이 변론에서 변제사실을 주장한 바가 없으므로 법원은 이를 판결의 기초로 삼을 수 없음이 원칙이다. 그러나 일반적으로 당사자는 증거신청을 함에 있어서 증명할 사실과 특정의 증거방법 그리고 증명의 취지를 구체적으로 밝혀야 하는 것으로 되어 있으므로(민사소송법 제289조 제1항, 제308조, 민사소송규칙 제74조), 을은 변론에서 갑으로부터 돈을 대여받은 사실을 부인하고 병을 증인으로 신청함에 있어서 갑에게 변제한 사실을 증명하기 위한 것이라고 그 증명의 취지를 진술하면서 병을 증인으로 신청하였을 것으로 보이므로 간접적 주장이론을 적용하여 을이 변제사실을 주장한 것으로 볼 수 있을 것이다. 설사 그렇지 않았다 하더라도 갑으로부터의 대여사실을 전부 부인한 을의 입장에서 보면 그 대여사실에 대한 증명책임이 갑에게 있기 때문에 을은 증거신청을 할 필요가 없었음에도 불구하고 을이 굳이 증거(증인)신청을 한 사실에 비추어 볼 때 을이 증인신청을 한 취지는 변제사실을 증명하기 위함이었던 것으로 추정할 수도 있을 것이므로 간접적 주장이론을 본 사안에 적용하여 을이 변제사실을 주장한 것으로 볼 수 있을 것이다.\n\n4. 결론\n\n법원은 대여사실과 변제사실을 인정하여 갑의 청구를 기각하는 판결을 할 수 있다.\n\n【원문 각주】\n\n1) 증거공통의 원칙은 공동소송인 사이에서도 인정되는데, 공동소송의 경우에 공동소송인 1인이 제출한 증거로부터 얻은 증거자료가 다른 공동소송인에게도 공통으로 증거자료가 된다. 다만. 공동소송인 사이에 이해관계가 서로 상반되는 경우에는 그에 대한 원용이 없는 한 위 원칙은 적용되지 않는 것으로 보아야 한다.\n\n2) 대법원 198.8.11. 선고 81다262,263\n\n3) 대법원 2008.11.8.선고 2008다39361 판결; 93.2.12. 선고 91다33384 판결."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-3주-사례2":{"id":"class-3주-사례2","question":{"segments":[{"sourceId":"s3e7fff1fe8","sourceFile":"민사소송법사례연습 3주차 문제.txt","pages":[1],"text":"<사례문제 2>\n\n문Ⅰ. 갑은 을과 병을 상대로 하여 을에게는 자신이 매각한 A물건에 대한 금 2,000만원의 매매대금의 지급을 구하고, 병에게는 금 3,000만원의 대여금의 지급을 구하는 소를 제기하였다. 이 소송에서 을은 갑으로부터 위 A물건을 매수한 것이 아니라 무상으로 증여받았다고 주장하였고, 병은 갑이 자신에게 위 대여금 채무를 면제하여 주었다고 주장하였다. 이에 법원이 증거조사를 다 해 본 결과, 매매계약 체결 사실과 대여사실은 인정되었지만 을과 병이 주장한 증여사실과 면제사실의 진위는 밝혀지지 않은 채 변론이 종결되었다.\n\n(1) 이 경우 법원은 을과 병이 주장하는 사실의 존부를 어떻게 판단하여야 하는가?\n\n(2) 법원은 갑의 위 각 청구에 대하여 어떤 판결을 선고하여야 하고, 이 경우 위 각 청구에 대한 판결이유에서 설시하고 판단하여야 하는 사항은 무엇인가?"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"s1deb1ca0bb","sourceFile":"민사소송법사례연습 3주차 답안.txt","pages":[3,4,5,6],"text":"<사례문제 2의 해결>\n\n1. 문제의 소재\n\n피고가 원고의 청구를 배척시키기 위하여 소송법상 또는 실체법상의 이유를 들어 적극적인 방어를 하는 것을 널리 항변이라고 한다. 이에는 소송절차에 관한 항변인 소송상의 항변(실체법상의 효과에 관계 없는 항변)과 원고의 청구를 기각시키기 위한 목적의 실체관계에 관한 항변인 본안의 항변(실체법상의 효과에 관계있는 항변)이 있는데 설문은 본안의 항변과 간접부인의 구별기준과 그 차이점에 관하여 묻고 있다.\n\n2. 본안의 항변과 부인의 개념 및 형태\n\n(1) 본안의 항변이란 피고가 원고의 청구를 배척시키기 위하여 원고의 주장사실이 진실임을 전제로 하여 이와 양립 가능하며 자신에게 증명책임이 있는 별개의 요건사실에 대하여 하는 사실상의 진술을 말한다.\n\n(2) 일반적으로 원고는 소를 제기하여 청구인용판결을 청구함에 있어서 그 청구원인 사실로서 자신의 권리를 발생시키는 원인이 되는 사실 즉 권리근거규정의 요건사실을(권리발생사실)을 주장하게 되고, 이에 대하여 피고는 원고의 청구를 배척시키기 위하여 그 반대규정 즉 권리장애규정의 요건사실(권리장애사실) • 권리멸각규정의 요건사실(권리멸각사실) • 권리저지규정의 요건사실(권리저지사실)을 주장하게 되는데 이를 본안의 항변이라 한다.\n\n(3) 부인이란 일반적으로 상대방이 증명책임을 부담하는 주장사실을 아니라고 부정하는 진술로서 이를 피고가 하는 경우에는 원고의 청구를 배척시키기 위하여 행하는 사실상의 진술이라는 점에서 항변과 차이가 없다. 그러나 항변은 원고의 주장사실이 진실임을 전제로 하여 이와 양립 가능한 별개의 요건사실을 주장하는 것이므로 그 답변 태도가 “그렇다, 하지만”임에 대하여 부인은 원고의 주장사실이 아니라는 주장이므로 “아니다”인 점에서 차이가 있다.\n\n(4) 피고가 하는 부인에는 원고의 주장사실이 진실이 아니라고 한마디로 부정하는데 그치는 직접부인(단순부인, 소극부인)과 원고의 주장사실과 양립되지 않는 별개의 사실을 적극적으로 진술하면서 원고의 주장사실을 부정하는 간접부인(이유부 부인, 적극부인)이 있는데, 실무상 항변과 간접부인과의 구별이 대단히 중요하게 취급된다.\n\n2. 간접부인과 항변\n\n(1) 양자의 구별기준\n\n간접부인은 원고의 주장사실과 논리적으로 양립되지 않는(양립 불가능한) 별개의 사실을 진술하는 것임에 대하여, 항변은 원고의 주장사실이 진실임을 전제로 하여 그와 논리적으로 양립될 수 있는(양립 가능한) 별개의 사실을 진술하는 것임에 차이가 있다.\n\n(2) 양자 구별의 필요성\n\n1) 증명책임상의 차이점\n\n증명책임분배의 원칙상 부인의 경우에는 부인당한 사실에 대한 증명책임이 그 상대방 , 원고에게 돌아가지만, 항변의 경우에는 항변사실의 증명책임이 그 항변 제출자인 피고에게 있다.\n\n2) 판결이유에서의 판단(기재)요부\n\n피고의 항변이 이유가 없어서 원고의 청구를 인용할 경우, 법원은 반드시 판결이유에서 피고의 항변을 배척하는 판단을 하여야 하고 이를 하지 않은 경우에는 판단누락의 위법이 있게 되지만, 간접부인 사실에 관하여는 이를 배척하는 판단이 필요하지 않다.\n\n3) 청구원인 사실의 구체적 주장의 필요성\n\n원고의 청구원인 사실이 피고로부터 부인 당한 경우에는 원고는 청구원인사실을 구체적으로 밝혀야 할 부담(구체적 주장책임)이 따르지만 피고가 항변을 한 경우에는 원고에게 이와 같은 부담이 없다.\n\n3. 사안의 해결\n\n문1. (1)의 해결\n\n1) 사안에서 무상으로 증여받았다는 을의 주장은 갑이 주장하는 매각(매매계약체결)사실과는 양립 불가능한 것으로서 간접부인에 해당한다. 따라서 무상으로 증여받았다는 사실이 진위불명 상태에 빠졌다 하더라도 이에 대한 증명책임이 을에게 있는 것이 아니라 갑은 을에 의하여 부인당한 매매계약 체결 사실을 증명하여야 한다(즉 매매계약 체결 사실에 대한 증명책임은 갑에게 있다). 그런데 증거조사의 결과 갑과 을 간의 매매계약 체결 사실이 인정되므로 법원은 그 사실이 존재하는 것으로 판단하여야 한다.\n\n2) 한편 병의 대여금 채무 면제주장은 갑이 주장하는 금전 대여사실이 진실임을 전제로 그와 논리적으로 양립 가능한 주장이므로 항변에 해당한다. 따라서 병은 항변으로 주장된 면제사실에 관한 증명책임을 부담하는데 법원의 증거조사결과 갑과 병 간의 대여사실 만이 인정되고 면제사실은 진위불명 상태에 빠졌으므로 병은 그에 대한 증명책임을 부담한다. 따라서 법원은 면제사실은 존재하지 않는 것으로 판단하여야 한다.\n\n문1.(2)의 해결\n\n(1) 갑의 을과 병에 대한 청구에 관한 판결 법원은 갑과 을 간에 있어서 매매계약 체결 사실이 인정되므로 을에 대한 청구를 전부 인용하는 판결을 선고하여야 하고, 갑과 병 간에 있어서 대여사실이 인정되고 대여금채무에 대한 면제사실은 진위불명 상태에 빠지게 되어 그 사실은 존재하지 않는 것으로 취급하여 판결하여야 하므로 병에 대한 청구도 전부 인용하는 판결을 선고하여야 한다. 즉 법원은 갑의 을과 병에 대한 청구를 전부 인용하는 판결을 선고하여야 한다.\n\n(2) 판결이유에서 설시하여야 할 사항\n\n법원이 갑의 을에 대한 청구인용 판결을 선고함에 있어서 을이 주장한 무상증여사실은 간접부인으로서 법원이 매매계약 체결 사실이 인정된다고 판단함으로서 이미 피고의 간접부인(무상증여 사실)을 배척하는 판단을 한 것으로 볼 수 있으므로 판결이유에 무상증여 사실의 인정 여부에 관한 판단을 설시할 필요가 없고 매매계약 체결 사실이 인정됨을 설시하면 족하다. 반면에 법원이 갑의 병에 대한 청구인용 판결을 선고함에 있어서 병이 주장한 채무면제 사실은 항변에 해당하므로 판결이유에 대여사실이 인정됨을 설시함과 아울러 반드시 병이 주장한 채무면제 사실이 인정되지 아니함을 설시하여야 한다. 만약 이를 설시(판단)하지 아니한 경우 그 판결에는 판단누락의 위법이 있게 되어 상소이유가 된다."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-3주-사례3":{"id":"class-3주-사례3","question":{"segments":[{"sourceId":"s3e7fff1fe8","sourceFile":"민사소송법사례연습 3주차 문제.txt","pages":[2],"text":"<사례문제 3>\n\n갑은 을을 상대로 1억 원의 공사대금청구소송을 제기하였다. 위 소송에서 을은 위 대금을 전액 변제하였다고 주장하였고, 제2회 변론기일에서 '예비적으로 갑에 대한 5천만 원의 손해배상채권으로 대등액에서 상계한다'고 진술하였다. 위 소송진행 도중 법원은 이를 조정에 회부하였는데 법원의 관여하에 \"을은 갑에게 6천만 원을 지급한다, 갑은 나머지 청구를 포기한다\"는 내용으로 조정조서가 작성되고 위 소송(전소)은 종료되었다. 그 이후 을은 갑을 상대로 위 손해배상채권 5천만 원의 지급을 구하는 소송을 제기하였는데 갑은 이 소송에서 을의 손해배상채권은 전소에서의 상계권 행사에 의하여 소멸하였다고 주장하면서 항변하였다. 법원은 갑의 항변에 대하여 어떻게 판단하여야 하는가? (2016.8. 법전협모의고사, 대법원 2013. 3. 28. 선고 2011다3329 판결에 기초하여 각색한 것임)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"s1deb1ca0bb","sourceFile":"민사소송법사례연습 3주차 답안.txt","pages":[6,7,8,9],"text":"<사례문제 3에 대한 해결>\n\n1. 문제의 소재\n\n당사자가 소송절차 외에서 일단 형성권(해제권, 해지권, 취소권, 상계권)을 행사한 후 소송상 그 사법상의 효과를 진술하는 경우가 아니라 소송절차에서 비로소 형성권을 행사하면서 이를 공격방어방법으로서 주장하는 경우에 그에 따른 사법상(실체법상)의 효과가 어떻게 되는 것인지에 관하여 견해의 대립이 있다. 일반적으로 ① 소가 취하되거나 부적법 각하되는 경우 또는 ② 그 공격방어방법이 실기되어 각하되는 경우 ③ 사안에서와 같이 소송계속 중 수소법원의 조정(임의조정)이 성립되는 경우 등에 있어서, 특히 피고가 소송상 상계권을 행사하면서 상계항변을 했는데 위 ①, ②, ③과 같은 상황이 생긴 경우에 상계의 의사표시에 따른 사법상의 효과(반대채권소멸의 효과)가 잔존하는지의 여부에 관하여 논의가 있는데, 이는 그 법적 성질을 어떻게 볼 것인지에 따라 결론이 달라지게 된다.\n\n2. 소송상 형성권의 행사의 법적 성질과 그에 따른 사법상의 효과\n\n(1) 사법행위설(병존설)\n\n외관상 하나의 행위이지만 법률적으로 볼 때 형성권의 행사라는 상대방에 대한 사법상의 의사표시(사법행위)와 그러한 의사표시가 있었다는 것을 법원에 대하여 사실상 진술(소송행위) 하는 두 가지 행위가 병존한다고 보는 견해이다. 이에 의하면 위 ①, ②, ③의 경우에 형성권 행사에 따라 애당초 발생한 사법상의 효과가 그대로 존속되는 것으로 본다.\n\n(2) 양성설\n\n사법행위와 소송행위의 두 가지 성질을 모두 갖춘 하나의 행위인 것으로 보아 소송행위로서 소송법상의 효과가 생기지 않는 때에는 사법상의 효과도 생기지 않는다고 한다. 이에 의하면 위 ①, ②, ③의 경우에 형성권 행사에 따라 애당초 발생한 사법상의 효과는 소멸되는 것으로 본다.\n\n(3) 소송행위설\n\n형성권의 소송외의 행사와는 전혀 성질을 달리하는 소송상의 공격방어행위로서 소송법 고유의 소송행위인 것으로 보는 견해로서 이에 의하면 위 ①, ②, ③의 경우에는 애당초부터 아예 형성권 행사에 따라 사법상의 효과가 발생한 적이 없었던 것으로 취급된다.\n\n(4) 신병존설\n\n상계권을 제외한 형성권을 소송상 행사한 경우에는 병존설의 입장을 따르지만, 소송상 상계권을 행사한 경우(상계항변)에 있어서 만은 위 ①, ②, ③의 경우에 사법상의 효과(반대채권소멸의 효과)가 발생하지 않는 것으로 보는 견해이다. 즉 상계항변에 포함된 상계의 의사표시는 그 항변이 공격방어방법으로서 각하되거나 실효되지 않고 이것이 유효하게 취급되어 법원이 소구채권이나 반대채권의 존부등 상계항변에 관하여 판단한 경우에 한하여 그에 따른 사법상의 효과가 발생하는 것으로 보는 견해로서 현재 통설의 입장이다\n\n(4) 판례의 태도\n\n대법원은 “원고가 소제기를 함으로써 계약해제권을 행사한 것으로 보여지는 경우, 해제권은 형성권이므로 비록 그 후에 원고가 소를 취하했다 하여도 위 해제권 행사의 효력에 아무런 영향도 미치지 아니한다\"고 판시하고 있고,4) 소송상 방어방법으로서 상계항변이 있었으나 소송절차 진행 중 조정이 성립됨으로써 수동채권의 존재에 관한 법원의 실질적인 판단이 이루어지지 않은 경우, 상계항변의 효과가 발생하는지 여부에 관하여 “소송상 방어방법으로서의 상계항변은 그 수동채권의 존재가 확정되는 것을 전제로 하여 행하여지는 일종의 예비적 항변으로서 당사자가 소송상 상계항변으로 달성하려는 목적, 상호양해에 의한 자주적 분쟁해결수단인 조정의 성격 등에 비추어 볼 때 당해 소송절차 진행 중 당사자 사이에 조정이 성립됨으로써 수동채권의 존재에 관한 법원의 실질적인 판단이 이루어지지 아니한 경우에는 그 소송절차에서 행하여진 소송상 상계항변의 사법상 효과도 발생하지 않는다고 봄이 상당하다\"고 판시하고 있음과 아울러(대법원 2013. 3. 28. 선고 2011다3329 판결) \"소송상 상계는 소송상 상계의 의사표시에 의하여 확정적으로 효력이 발생하는 것이 아니라 해당 소송에서 수동채권의 존재 등 상계에 관한 실질적 판단이 이루어지는 경우에 비로소 실체법상의 효과가 발생한다\"고 판시하고 있는데(대법원 2014.6.12. 선고 2013다95964 판결), 이는 신병존설의 입장에 서 있는 것으로 평가된다.5)\n\n(5) 소결\n\n예컨대 원고의 매매대금청구의 소에 대하여 피고가 소송상 하자담보책임을 이유로 계약 해제의 의사표시를 하면서(해제권을 행사하면서) 이를 방어방법으로 주장하였지만 원고가 소를 취하한 경우, 소송행위설이나 양성설에 의하면 소송이 판결에 의하지 않고 종료되었으므로 해제의 의사표시에 따른 사법상의 효과는 발생하지 않는 것이 된다(해제의 의사표시는 없었던 것으로 취급된다). 그런데 원고가 장래에 다시 같은 소를 제기하여 온 경우에 피고는 하자담보책임을 이유로 해제권을 행사하려고 하여도 제척기간이 이미 경과됨으로써 이를 행사할 수 없게 되는 상황이 생길 수 있다. 이에 반하여 사법행위설에 의하면 해제권 행사의 효과는 소의 취하에 의하여 상실되는 것이 아니므로 소송행위설이나 양성설에 의할 때와 같은 불합리한 결과가 생기지 않게 된다는 점에서 기본적으로 병존설의 입장이 타당하다고 생각된다. 그러나 다른 형성권과는 달리 피고가 상계권을 소송상 행사한 경우에 있어서도 병존설의 입장에 서게 되면 위 ①, ②, ③의 경우에 피고에게는 상계의 의사표시에 따른 반대채권 소멸의 효과가 그대로 잔존하는 결과 피고는 애당초 상계의 항변을 하지 않았던 것보다 더 불리한 지위에 놓이게 되는 불합리한 결과가 발생하게 된다는 점에서 이러한 문제를 피할 수 있는 신병존설의 입장이 타당한 것으로 생각된다.\n\n3. 결론 - 법원의 갑의 항변에 대한 판단\n\n(1) 을의 손해배상채권이 잔존하는지의 여부\n\n신병존설 및 판례의 취지에 따를 경우 을이 전소에서 손해배상채권을 자동채권으로 하여 상계 항변을 하였지만 전소가 임의조정으로 종료됨으로써 그 소구채권(공사대금채권)이나 반대채권(손해배상채권)의 존부 등 상계항변에 관한 법원의 실질적 판단이 이루어지지 않았다. 따라서 위 상계항변은 그 사법상 효과도 발생하지 않는다고 보아야 하므로 반대채권인 을의 손해배상채권은 소멸하지 않고 잔존하게 된다.\n\n(2) 따라서 을의 손해배상채권은 전소에서의 상계권 행사에 의하여 소멸하였다고 주장하는 갑의 항변은 타당하지 않으므로 법원은 이를 배척하여야 한다.\n\n(3) 더구나 을의 손해배상채권은 전소의 소송물이 아니었을 뿐만 아니라 그 조정조서의 조정조항에 특정되거나 청구의 표시 다음에 부가적으로 기재되지 아니하였으므로 특별한 사정이 없는 한 위 조정조서의 효력이 을의 손해배상채권에 미치지 않으므로 갑의 항변은 타당하지 않아 법원은 이를 배척하여야 한다\n\n【원문 각주】\n\n4) 대법원 1982.5.11.선고 80다916판결\n\n5) 2015.3.20.선고 2012다107662 판결도 같은 취지이다.."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-3주-사례4-1":{"id":"class-3주-사례4-1","question":{"segments":[{"sourceId":"s3e7fff1fe8","sourceFile":"민사소송법사례연습 3주차 문제.txt","pages":[2],"text":"<사례문제 4 >\n\n1. 갑은 을에게 500만 원 상당의 건강기능식품을 매각했는데 을이 그 대금을 지급하지 않자 을을 상대로 매매대금 500만 원의 지급을 구하는 소를 제기하였다. 이에 대하여 을이 변론기일에 출석하여 위 식품의 중대한 하자를 이유로 매매대금의 지급을 거절한 것이라고 주장하였는데, 1심법원은 원고의 청구를 기각하는 판결을 선고하였고 갑은 이에 대하여 항소를 제기하였다. 그런데 갑과 을은 항소심 소송계속 중 ‘을이 갑에게 200만원을 지급하면 갑은 그 즉시 이사건 소를 취하한다”는 내용의 합의서를 작성하였다. (아래 각 설문은 상호 독립적인 것임)\n\n(1) 위 합의 이후 을은 갑에게 200만 원을 지급하였으나 갑은 이 사건 소를 취하하지 않았고 이에 을은 위 소송의 2차 변론기일에 갑과 을 사이에 소취하 합의가 있었다고 주장하면서 그 증거로 위 합의서를 제출하였다. 법원이 변론을 종결한 결과, 갑과 을 사이에 건강기능식품에 관해 대금 500만 원의 매매계약이 체결되었고 을이 매매대금을 지급하지 않은 사실, 위 합의서가 진정하게 작성된 사실, 위 합의서 작성 이후 을이 갑에게 200만 원을 지급한 사실이 인정되었다. 이러한 경우 법원은 어떤 판결을 선고하여야 하는가?"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"s1deb1ca0bb","sourceFile":"민사소송법사례연습 3주차 답안.txt","pages":[9,10],"text":"문제1. (1)의 경우\n\n1. 문제의 소재\n\n설문은 합의서가 처분문서임을 전제로 그것이 진정하게 작성된 것임이 인정되는 경우 (형식적 증거력이 인정되는 경우) 특별한 사정이 없는 한 실질적 증거력도 인정된다는 전제하에 정지조건부로 소를 취하하기로 하는 내용의 합의서가 작성되었고 피고가 그 합의에 따른 의무를 이행하여 그 조건이 성취되었음에도 불구하고 원고가 그 합의에 반하여 소취하를 하지 않고 있는 경우, 법원은 어떤 판결을 선고하여야 하는지를 묻고 있다. 이는 소취하 합의의 성질을 어떻게 파악할 것인지에 따라 결론이 달라질 것이다.\n\n2. 소취하 합의(계약)의 의의 및 법적 성질\n\n(1) 소취하 합의는 소송상 합의의 일종으로서 소송 외에서 원고가 피고에 대한 소를 취하하기로 하는 내용의 원고, 피고 간의 약정을 말하는데, 법규에 이를 허용하는 명문 규정은 없더라도 소송에 있어 당사자의 처분의 자유가 인정되는 영역 즉 처분권주의와 변론주의가 적용되는 영역에서는 그 유효성을 인정하는 것이 일반적이다. 그런데 그 법적 성질과 그에 위반된 행위의 효력에 관하여는 논의가 있다.\n\n(2) 성질\n\n1) 사법계약설\n\n소송행위의 개념을 좁게 파악하는 요건 • 효과설의 입장에서 소취하 합의는 '소를 취하하여야 한다는 사법상의 의무를 발생시키는 사법계약이라고 한다. 만약 원고가 이를 위반하여 소송을 계속 유지하는 경우 ① 피고는 그에 대응하여 의무이행을 소구하거나 손해배상을 청구할 수 있다는 입장(의무이행소구설)과 ② 의무이행의 소구나 손해배상청구는 우회적인 방법이므로 피고에게 당해 소송에서 항변권이라는 구제수단을 부여하여 피고가 원고의 소취하 합의 위반 사실을 항변으로 주장 • 증명하면 법원은 권리보호 이익의 흠결을 이유로 소 각하 판결을 하여야 한다는 입장(항변권 발생설)이 있는데 후자가 다수설과 판례의 입장이다.6)\n\n2) 소송계약설\n\n소송행위의 개념을 넓게 파악하는 효과설의 입장에서 소취하 합의는 소송계속의 소멸이라는 소송법상의 효과를 발생시키는 소송행위(소송계약)라고 한다. 이에는 ① 당사자의 주장을 통해 법원에 그 합의 사실이 알려지면 소송계속 소멸의 효과가 발생하므로 법원은 확인적 의미에서 소가 종료되었다는 소송종료선언판결을 하여야 한다는 입장(순수 소송효과설)과 ② 소취하 합의에는 소송계속의 소멸이라는 효과 뿐만 아니라 의무부과적 효과까지도 발생하므로 그 합의 위반자를 상대로 손해배상도 청구할 수 있다는 입장이 있다(발전적 소송계약설).\n\n3) 소결\n\n의무이행소구설은 피고에 대한 구제방법이 우회적이고 간접적이라는 점, 소송계약설에 의하면 소송 외에서 행한 소취하 합의와 소취하를 그 방식이나 효과면에서 동일하게 취급하게 된다는 점에서 문제가 있으므로 항변권발생설이 타당한 것으로 생각된다.\n\n3. 결론 ; 사안에의 적용\n\n법원이 심리를 종결한 결과 을이 소취하 합의가 있었음을 주장(항변)하면서 증거로 제출한 합의서(처분문서)가 진정하게 작성된 사실이 인정되므로 특별한 사정이 없는 한 그 내용(조건부 소취하 합의사실)은 인정되어야 한다. 한편 을이 갑에게 200 만 원을 지급한 사실이 인정됨으로써(조건이 성취됨으로써) 효력이 발생된(유효한 상태의) 소취하 합의가 존재함에도 불구하고 갑이 그에 위반하여 소를 유지하고 있으므로 을의 항변은 이유있고 증명된 것으로 보아야 한다. 따라서 법원은 항변권발생설에 따라 법원은 갑의 소에 대해 권리보호의 이익이 없다는 이유로 소각하 판결을 하여야 할 것이다.7)\n\n【원문 각주】\n\n6) 2005.6.10. 선고 2005다14861; 1982.3.9. 선고 81다1312 판결 등\n\n7) 만약 법원이 소송계약설을 따른다면 '이 사건 소송은 모년 모월 모일..자 소취하 합의에 의하여 종료되었음을 선언한다는 소송종료선언을 하여야 할 것이다"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-3주-사례4-2":{"id":"class-3주-사례4-2","question":{"segments":[{"sourceId":"s3e7fff1fe8","sourceFile":"민사소송법사례연습 3주차 문제.txt","pages":[2],"text":"<사례문제 4 >\n\n1. 갑은 을에게 500만 원 상당의 건강기능식품을 매각했는데 을이 그 대금을 지급하지 않자 을을 상대로 매매대금 500만 원의 지급을 구하는 소를 제기하였다. 이에 대하여 을이 변론기일에 출석하여 위 식품의 중대한 하자를 이유로 매매대금의 지급을 거절한 것이라고 주장하였는데, 1심법원은 원고의 청구를 기각하는 판결을 선고하였고 갑은 이에 대하여 항소를 제기하였다. 그런데 갑과 을은 항소심 소송계속 중 ‘을이 갑에게 200만원을 지급하면 갑은 그 즉시 이사건 소를 취하한다”는 내용의 합의서를 작성하였다. (아래 각 설문은 상호 독립적인 것임)\n\n(2) 갑은 소취하 합의 이후 소취하를 먼저 해주면 바로 합의금 200만원을 지급할 것을 확약한 을의 말을 믿고서, 을로부터 위 합의금을 지급 받기도 전에 항소심절차에서 소를 취하였는데, 을은 이에 반하여 원고에게 200만원을 지급하지 않았다. 이에 갑은 위 합의금 채권을 병에게 양도하고 양도사실을 을에게 통지하였는데, 병은 을을 상대로 위 200만 원의 지급을 구하는 소를 제기하였다. 이 소는 적법한 것인가?"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"s1deb1ca0bb","sourceFile":"민사소송법사례연습 3주차 답안.txt","pages":[11,12],"text":"문제1.(2)의 경우\n\n1. 문제의 소재\n\n본안에 관한 종국판결선고 후에 소를 취하한 자는 이미 취하한 소와 동일한 소를 재차 제기하는 것이 금지되는 제재를 받게 되는데 이를 재소금지의 원칙이라 한다. 이 원칙이 적용되기 위하여는 ① 전소와 후소의 당사자가 동일할 것 ② 전소와 후소의 소송물이 동일할 것 ③ 본안에 관한 종국판결선고 후에 소가 취하되었을 것 ④ 전소와 후소의 권리보호이익이 동일한 것이 요구되는데, 본 사안은 위 ①과 ④의 요건과 관련되어 문제 된다. 즉 ①의 요건과 관련하여 항소심에서 소를 취하한 갑으로부터 취하된 전소의 소송물인 권리관계를 그대로 양도받은 병이 특정승계인으로서 갑과 동일하게 재소금지의 효과를 받는 당사자가 되는지의 여부와 ④의 요건과 관련하여 피고인 을이 소취하의 전제조건을 위반한 경우 즉 합의금을 지급하겠다는 을의 말을 믿고 갑이 소를 취하했는데 을이 그 약속을 이행하지 않음으로써 갑 또는 그 특정승계인 병이 다시 소를 제기하는 경우, 이는 전소와는 권리보호의 이익이 다른 것이므로 재소금지 원칙은 그 적용이 없는 것으로 보아야 하는 것인지의 여부가 문제된다.\n\n2. 재소금지의 효력이 특정승계인 병에게도 미치는지의 여부\n\n(1) 견해의 대립\n\n재소금지의 효력이 당사자인 원고나 그의 변론종결 후의 일반승계인(포괄승계인)에게 미친다는 점에는 이론이 없으나 변론종결 후의 특정승계인에게도8) 미치는가에 대해는 논의가 있다.\n\n① 부정설\n\n재소금지의 효력은 기판력과 같이 법적 안정성을 위한 것이 아니고 소권남용에 대한 제재이므로 전소의 취하를 알면서 승계했다는 등의 특별한 사정이 없는 한 특정승계인에게는 그 효력이 미치지 않는다는 입장이다.\n\n② 긍정설\n\n원고가 본안에 관한 종국판결을 받은 이상 절차보장이 되었다고 보아야 하기 때문에 그 특정승계인에게도 그 효력이 미치는 것으로 보아야 한다는 견해인데, 판례는 기본적으로 후자의 입장이지만, 재소금지의 효력을 받는 특정승계인이라도 그에게 다시 소를 제기할 권리보호이익이 있는 때에는 재소를 허용한다.9)\n\n④ 소결\n\n생각건대 판례와 같이 원칙적으로 특정승계인에게도 재소금지의 효력이 미치는 것으로 보되 피고가 소취하의 전제조건을 위반한 경우 등과 같이 원고나 그 승계인에게 다시 소를 제기할 사정변경이 생기거나 새로운 권리보호이익이 생긴 때에는 재소를 제기할 수 있는 것으로 보는 것이 타당할 것이다.\n\n3. 권리보호의 이익이 동일한지의 여부\n\n재소의 권리보호의 이익과 취하한 전소의 권리보호의 이익이 서로 다를 때에는 재소금지의 원칙이 적용되지 않는다. 재소금지의 효력은 소취하의 남용과 재소의 남용을 금지하기 위한 것으로 소권을 박탈하는 제도는 아니기 때문이다. 따라서 예컨대 피고가 소취하의 전제조건인 약정사항을 이행하지 않아 그 약정이 실효되는 등의 사정변경이 생김으로써 원고가 다시 제기하는 소는 전소와는 권리보호이익을 달리 하는 것으로서 당연히 허용되어야 한다.\n\n4. 사안의 해결\n\n갑의 소취하는 본안에 관한 종국판결 선고 후인 항소심에서 행해졌으므로 갑은 재소금지의 효력을 받게 되고 원칙적으로 갑의 특정승계인인 병에게도 그 효력이 미치는 것으로 보아야 한다. 그러나 사안의 경우, 갑이 소취하를 하였음에도 을은 소취하의 전제조건이었던 갑과의 합의금 지급 약속을 이행하지 않음으로써 갑에게는 새로운 사정변경이 생긴 것으로 보아야 하고, 이에 원고가 재소를 제기하더라도 이는 취하된 전소와는 권리보호이익을 달리하는 것으로서 재소금지의 원칙의 적용대상이 되지 않는다. 이와 같이 재소금지의 제재를 받지 않고 다시 소를 제기할 수 있는 상태에 있던 갑으로부터 전소의 소송물인 권리관계를 양도받은 특정승계인 병에게도 재소금지의 원칙이 적용되지 않는다고 하여야 하므로 병이 제기한 소는 적법한 것으로 보아야 한다.\n\n【원문 각주】\n\n8) 여기서 특정승계인이라 함은 변론종결 후에 원고로부터 전소의 소송물인 권리관계 또는 계쟁물을 양수함으로서 소송물에 관한 당사자적격을 취득한 제3자를 의미한다.\n\n9) 대법원 1981.7.14.선고 81다64 판결"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-4주-문1":{"id":"class-4주-문1","question":{"segments":[{"sourceId":"s05455e5f8f","sourceFile":"민사소송법사례연습 4주차 문제.txt","pages":[1],"text":"문1. 갑은 2020.12.1. 을을 상대로 X토지에 관하여 매매를 원인으로 한 소유권이전등기절차의 이행을 구하는 소송을 제기하였다. 위 소송에서 을은 매매계약이 실효되었다고 주장하면서, 예비적 항변으로서 “만일 위 매매계약이 유효하다면, 을은 갑으로부터 잔금을 지급받지 못하였으므로 갑의 잔금 지급과 상환으로 소유권이전등기절차를 이행할 의무가 있다”고 주장하였다. 갑은 을의 위 주장에 대하여 “을에 대한 대여금채권으로 위 잔금채권과 대등액에서 상계한다는 상계재항변을 하였다. 법원은 “위 매매계약은 유효하나 갑 주장의 대여금채권이 인정되지 않는다는 심증을 형성하였고, 이에 따라 \"을은 갑으로부터 잔금을 지급받음과 동시에 갑에게 X토지에 관한 소유권이전등기절차를 이행하라”는 판결을 선고하였고 위 판결이 확정되었다. 이후 갑이 을을 상대로 위 대여금을 지급하라는 소송을 제기하였는데, 위 소송에서 을은 “갑 주장의 대여금 채권은 전소 확정판결의 기판력에 저촉된다\"고 항변하였다. 이 항변에 대하여 법원은 어떻게 판단하여야 하는가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"s7d6eb58f2f","sourceFile":"민사소송법사례연습 4주차 답안.txt","pages":[1],"text":"문1.\n\n1. 문제의 소재(쟁점) : 기판력의 객관적 범위, 상계항변에 제공된 채권에 대하여 기판력이 인정되는 범위 - 2점\n\n2. 기판력의 객관적 범위 - 7점\n\n- 판결주문에서 한 판단에 한하여 기판력이 인정되며(제216조 제1항), 판결이유 중의 항변사항에 대해서는 그것이 판결주문의 결론을 내리는 기초가 되었다 하더라도 기판력이 생기지 않음\n\n- 다만 상계항변은 예외. 피고가 상계항변을 제출하고 법원이 자동채권의 존부에 관하여 판결이유에서 판단하였을 경우에는 상계로써 대항한 액수의 한도 내에서 기판력이 발생함(제216조 제2항).\n\n- 판결이유 중의 판단임에도 상계 주장에 관한 법원의 판단에 기판력을 인정한 취지\n\n3. 상계항변의 경우 기판력의 인정 범위 - 8점\n\n- 자동채권의 존부에 관하여 실질적인 판단이 있었을 것 . 상계항변의 실기각하, 상계금지, 상계부적상 등의 이유로 상계항변이 배척된 경우에는 기판력이 발생하지 않음. 상계로써 대항한 액수에 한하여 기판력 발생\n\n- 수동채권이 소송물로서 심판의 대상일 것\n\n• 대법원 2005. 7. 22. 선고 2004다17207 판결의 결론 및 취지\n\n4. 사안에의 적용 및 결론 - 3점\n\n- 갑 주장의 대여금채권의 부존재에 기판력 발생하지 않으므로 후소에서 이와 다른 주장 가능, 따라서 갑의 후소에서의 청구가 전소 확정판결의 기판력에 저촉된다는 을의 항변은 타당하지 않음\n\n(그러나 전소확정판결이유에서 판단된 위 대여금채권 -부존재 사실이 후소에서 이를 채용할 수 없는 특별한 사정이 없는 한 유력한 증거자료가 되므로, 후소법원은 특별한 사정이 없는 한 청구 기각판결을 해야 할 것임)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-4주-문2":{"id":"class-4주-문2","question":{"segments":[{"sourceId":"s05455e5f8f","sourceFile":"민사소송법사례연습 4주차 문제.txt","pages":[1],"text":"문2. 갑은 을을 상대로 대여금반환청구의 소를 제기하였다. 이에 대해 을은 그 대여금을 이미 변제하였다고 주장하면서 그 증거방법으로 갑명의로 작성되고 갑의 인장이 날인되어 있는 변제영수증을 제출하였고, 갑이 그 변제사실을 다투자 법원은 변론기일에 위 영수증에 대해 증거결정을 한 후 그에 대한 증거조사를 하였다.\n\n(1) 갑은 위 영수증에 대한 성립의 인부를 함에 있어 위 영수증에 찍혀 현출되어 있는 인영은 자신의 인장에 의한 것이지만 자신은 스스로 날인한 적이 없다고 부인하였다. 이 경우 법원은 위 영수증의 형식적 증거력 및 실질적 증거력에 대하여 어떻게 판단하여야 하는가?(20점)\n\n(2) 만약 갑이 위 영수증에 대한 인부절차에서 진정성립을 인정하였다가 그 후 소송절차가 불리하게 진행되자 위 영수증이 위조된 것이라고 하면서 이를 부인하는 항변을 제출하였다면 법원은 이를 어떻게 처리해야 하는가? (10점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"s7d6eb58f2f","sourceFile":"민사소송법사례연습 4주차 답안.txt","pages":[1,2],"text":"문2.\n\nI. 문제의 제기 (보너스 점수 3점)\n\n문서가 증거로 제출된 경우 그에 대한 증거조사절차로서 먼저 문서에 대한 성립의 인부절차를 진행, 이에 대한 상대방의 답변태도로서 성립인정(자백), 침묵, 부인, 부지 등이 있는데 이에 대한 소송절차상의 취급이 각기 다르다.\n\nⅡ. 문2 (1)항의 해결\n\n1. 문서의 형식적 증거력의 의의 (10점)\n\n(1) 공문서와 사문서, 처분문서와 보고문서의 구별의 필요성 - 변제영수증은 사문서로서 처분문서임. 처분문서에 대한 형식적 증거력과 실질적 증거력에 대해서도 언급할 필요가 있음.\n\n(2) 위 영수증의 형식적 증거력 - 민소법 제358조의 해석론 (10점) 인영부분은 인정하되 날인사실을 부인한 경우, 판례는 이른바 2단의 추정이론을 정립. 따라서 갑이 자신의 인장이 도용된 사실(도용사실) 또는 모용사실을 증명하지 못하는 이상 영수증의 진정 성립은 추정되어 인정된다.\n\n2. 문서의 실질적 증거력의 의의 (10점)\n\n(1) 처분문서의 경우 형식적 증거력이 인정되면 특별한 사정이 없는 이상 실질적 증거력이 인정된다.\n\n(2) 위 영수증의 형식적 증거력이 추정되어 인정되므로 갑이 인장의 도용사실을 증명하지 못하면 법원은 특별한 사정이 없는 이상 영수증의 실질적 증거력을 인정하여야 한다. 즉 법원은 갑이 도용사실을 증명하지 못하면 특별한 사정이 없는 이상 영수증에 기재되어 있는 사실 즉 을이 갑에게 변제한 사실을 인정하여야 한다.\n\nⅢ. 문2 (2)항의 해결\n\n1.\n\n문서의 진정성립에 관한 자백은 보조사실에 관한 것이지만 이에 대하여 재판상 자백과 같은 구속력이 인정되는가. 판례의 입장은 무엇인가.(5점)\n\n2.\n\n문서의 진정성립에 관한 자백을 하였다가 위조주장을 하면서 이를 부인하는 항변을 하는 것이, 즉 이를 취소하는 것이 허용되기 위해서 필요한 요건은? (5점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-4주-문3-1":{"id":"class-4주-문3-1","question":{"segments":[{"sourceId":"s05455e5f8f","sourceFile":"민사소송법사례연습 4주차 문제.txt","pages":[2],"text":"문3.\n\n<공통된 사실관계>\n\n갑은 해외근무를 하여야 할 일이 생겨 친구인 을에게 갑 자신의 소유인 X건물에 관한 관리를 부탁하고 해외로 출국한 사실이 있는데, 을은 갑이 해외에 체류하고 있던 중 X건물에 관하여 자신의 명의로 소유권이전등기를 마쳤다. 장기간의 해외근무를 마치고 귀국한 후 이 사실을 알게 된 갑은 2021.4.1. 을을 상대로 을 명의의 위 소유권이전등기가 원인무효임을 주장하면서 소유권이전등기말소청구의 소(이하 이 사건 소라고 함)를 제기하였다.\n\n<사실관계1. 이는 아래 설문 (1)에만 해당되는 것임〉\n\n2021.5.1. 이 사건 소의 소장부본을 송달받은 을은 “갑의 승낙 없이 소유권이전등기를 마친 것은 사실이다. 이전등기를 말소하라면 말소해 주겠다”는 취지만을 기재한 답변서를 작성하여 법원에 제출하였고, 이 답변서는 2021.5.6. 법원에 접수되었다.\n\n(1) 을의 답변서가 법원에 접수된 이후로 을은 이 사건 소와 관련하여 아무런 소송행위도 하지 않았다. 법원은 이 상태에서 이 사건 소를 종결시킬 수 있는가?(10점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"s7d6eb58f2f","sourceFile":"민사소송법사례연습 4주차 답안.txt","pages":[2,3],"text":"제(1)항에 대한 답안 (10점)\n\n가. 결론(3점)\n\n법원은 무변론 원고 승소판결을 함으로써 사건을 종결시킬 수 있다.\n\n나. 근거 (7점)\n\n민소법 제257조 2항에 따라 피고가 청구원인 사실에 대해 모두 자백하는 취지의 답변서를 제출하고 따로 항변을 하지 않으면 법원은 원고의 주장이 주장자체로 실당한 경우를 제외하고 무변론 원고 승소판결을 할 수 있다.\n\n사안에서 을은 자신이 갑의 승낙 없이 소유권이전등기를 마쳤고 그 등기의 말소청구에 응하겠다는 취지의 답변서를 제출함으로써 원고의 청구원인사실을 모두 자백하였고 따로 항변을 제기하지 않았으므로 법원은 민소법 257조 2항에 의해 무변론 원고 승소판결을 할 수 있다."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-4주-문3-2":{"id":"class-4주-문3-2","question":{"segments":[{"sourceId":"s05455e5f8f","sourceFile":"민사소송법사례연습 4주차 문제.txt","pages":[2,3],"text":"문3.\n\n<공통된 사실관계>\n\n갑은 해외근무를 하여야 할 일이 생겨 친구인 을에게 갑 자신의 소유인 X건물에 관한 관리를 부탁하고 해외로 출국한 사실이 있는데, 을은 갑이 해외에 체류하고 있던 중 X건물에 관하여 자신의 명의로 소유권이전등기를 마쳤다. 장기간의 해외근무를 마치고 귀국한 후 이 사실을 알게 된 갑은 2021.4.1. 을을 상대로 을 명의의 위 소유권이전등기가 원인무효임을 주장하면서 소유권이전등기말소청구의 소(이하 이 사건 소라고 함)를 제기하였다.\n\n<사실관계 2. 이는 아래 설문 (2)에만 해당되는 것임>\n\n2021.5.1. 이 사건 소의 소장부본을 송달받은 을은 “을이 갑의 승낙 없이 임의로 이전등기를 마친 것이 아니라 갑의 대리인 A로부터 적법하게 X건물을 매수하여 이전등기를 마친 것이다\"는 취지의 답변서를 작성하여 법원에 제출하는 등 이 사건 소의 변론과정에서 원고의 주장사실을 적극적으로 다투었다.\n\n(2) 법원의 심리결과 갑의 A에 대한 대리권수여여부가 진위불명 상태에 빠졌다면 법원은 어떤 내용의 판결을 선고하여야 하는가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"s7d6eb58f2f","sourceFile":"민사소송법사례연습 4주차 답안.txt","pages":[3,4],"text":"제(2)항에 대한 답안. (20점)\n\n1. 문제의 제기\n\n등기의 추정력 : 부동산 등기부상 소유자로 등기되어 있는 자는 특별한 사정이 없는 한 그 부동산의 소유자로 추정된다. 즉 판례에 의하면 등기가 있으면 등기된 권리의 존재 및 귀속, 등기원인의 존재 및 등기절차의 적법성이 법률상 추정된다고 하고 있다. (5점)\n\n2. 사안의 해결\n\n1) 이와 같이 법률상 추정의 경우에는 상대방이 추정된 사실에 반하는 반대사실에 대한 증명책임을 진다. 즉 추정된 사실을 깨뜨리려면 반증으로 족한 것이 아니라 반대사실의 존재에 대하여 법관에게 확신을 주어야만 한다. 따라서 현 등기명의인인 피고 을이 갑의 대리인 A에 의한 계약체결사실을 주장한 경우에 전 소유명의인인 갑은 그 반대사실 즉 A에게 갑을 대리할 권한이 없었다든가 또는 A가 갑의 등기관계서류를 위조하였다는 등의 원인무효사실에 대한 증명책임을 진다. (10점)\n\n2) 따라서 사안의 경우 법원이 심리한 결과 A에 대한 대리권 수여 여부가 진위불명이 되어 버렸으므로(즉 법원이 A에게 대리권이 수여되지 않았다는 사실에 대하여 확신을 갖지 못하게 되었으므로) 법원은 원고의 청구를 기각하는 판결을 선고하여야 한다.(5점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-4주-문3-3":{"id":"class-4주-문3-3","question":{"segments":[{"sourceId":"s05455e5f8f","sourceFile":"민사소송법사례연습 4주차 문제.txt","pages":[2,3],"text":"문3.\n\n<공통된 사실관계>\n\n갑은 해외근무를 하여야 할 일이 생겨 친구인 을에게 갑 자신의 소유인 X건물에 관한 관리를 부탁하고 해외로 출국한 사실이 있는데, 을은 갑이 해외에 체류하고 있던 중 X건물에 관하여 자신의 명의로 소유권이전등기를 마쳤다. 장기간의 해외근무를 마치고 귀국한 후 이 사실을 알게 된 갑은 2021.4.1. 을을 상대로 을 명의의 위 소유권이전등기가 원인무효임을 주장하면서 소유권이전등기말소청구의 소(이하 이 사건 소라고 함)를 제기하였다.\n\n<사실관계 3. 이는 아래 설문 (3)에만 해당되는 것임 >\n\n2021.5.1. 이 사건 소의 소장부본을 송달받은 을이 급작스럽게 사망하는 바람에 을의 공동상속인인 병과 정은 이 사건 소에 관한 수계절차를 밟았고, 이에 따라 갑은 병과 정의 상속분에 따라서 청구취지를 변경하였다. 그 이후 진행된 변론절차에서 병은 갑의 주장사실을 다투지 않은 채 이를 그대로 시인하는 취지의 진술을 하였으나 정은 을 명의의 소유권이전등기가 적법하게 경료된 것이라고 주장하면서 갑의 주장사실을 적극적으로 다투었다.\n\n(3) 위와 같은 경우에 있어서 정의 진술은 병에게, 병의 자백은 정에게 각각 어떤 영향을 미치는가?(20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"s7d6eb58f2f","sourceFile":"민사소송법사례연습 4주차 답안.txt","pages":[4],"text":"제(3)항에 대한 답안 (20점)\n\n1. 문제의 소재(2점)\n\n병과 정은 피고 을의 공동상속인이고 상속재산은 공유재산으로서 그 관리처분권을 공동으로 행사하는 것이 실체법상 강제되는 관계에 있지 않으므로 병과 정의 공동소송형태는 통상공동소송이다. 이에는 민소법 66조 소정의 공동소송인독립의 원칙이 적용된다. 그러나 이를 그대로 관철할 경우 공동소송인들 간에 모순, 저촉되는 판단이 초래되는 상황이 생길 수 있는데 이를 시정하는 원리로서 공동소송인들 간에 주장공통의 원칙을 인정할 것인가가 문제 된다.\n\n2. 주장공통의 원칙의 의의(5점)\n\n- 공동소송인 중 1인이 상대방의 주장사실을 다투는 등 다른 공동소송인에게 유리한 소송행위를 할 때 다른 공동소송인의 원용이 없더라도 그에 대한 효력이 미친다는 원칙.\n\n3. 인정여부(3점)\n\n인정설(긍정설) : 이를 부정하면 역사적 사실은 하나 밖에 있을 수 없다는 논리의 거역, 재판불신의 원인이 된다.\n\n- 불인정설(부정설): 이를 인정하면 변론주의에 정면으로 배치됨. 판례는 부정설의 입장임.\n\n4. 결론(10점)\n\n병은 갑이 주장하는 청구원인사실에 대해 자백하고 정은 부인하고 있다. 위 인정설에 의하면 정의 부인진술에 따른 효력이 병에게도 그대로 생기는 것으로 보아야 하고, 위 부정설에 의하면 정의 부인진술에 따른 효력이 병에게 그대로 생기지 않으므로 법원은 병에 대한 소송관계에 있어서 정의 부인진술에도 불구하고 자백한 그대로 사실을 인정하여야 한다. 한편 정에 대한 소송관계에 있어서는 병의 자백이 있었더라도 자백의 효력은 생기지 않고 법원은 이를 단지 변론전체의 취지로 참작할 수 있다. (참조판결 1992.12.11.선고 92다18627판결, 1997.2.28.선고 96다53789판결)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-5주-문1":{"id":"class-5주-문1","question":{"segments":[{"sourceId":"s3fd74e102d","sourceFile":"민사소송법사례연습 5주차 문제.txt","pages":[1],"text":"민사소송법이론 기말고사\n\n[사례형]\n\n- 4문제 / 80점 만점\n\n- 각 해당 문제에서 “문제의 소재\" 또는 “쟁점\"을 기재하지 말 것(질문을 그대로 다시 기재하지 말 것)\n\n[공통된 사실관계]\n\n수원시 영통구(수원지방법원 관할구역)에 거주(주소지)하는 갑은, 서울시 서초구(서울중앙지방법원 관할구역)에 거주(주소지)하는 을과의 사이에서, 갑이 을로부터 을 소유의 서울시 노원구(서울북부지방법원 관할구역) 소재 X부동산을 매매대금 2억 원에 매수하는 내용의 매매계약을 체결하였고, 매매계약의 내용에 따라 을에게 매매대금 2억 원을 모두 지급하였다. 그런데 을이 위 부동산에 대한 소유권이전등기의무를 지체함에 따라, 갑은 매매계약을 해제하면서 수원지방법원에 을을 피고로 한 매매대금 반환청구소송을 제기하였다.\n\n(※ 아래 각 문항은 상호 독립적이며 무관함)\n\n1. 위 매매계약서에는 '1심 관할법원은 서울중앙지방법원으로 한다\"라고 되어 있었다. 위 조항의 해석과 관련하여 을은 “서울중앙지방법원에만 관할이 인정되고 수원지방법원에는 관할이 인정되지 않는다\"고 주장하면서, “가사 수원지방법원에 관할이 인정된다고 하더라도, 갑의 매매계약 해제는 최고 요건을 불비한 부적법한 것이다\"라고 다투는 내용의 답변서를 제출하였다. 1회 변론기일에서 원고의 소장, 피고의 답변서가 각각 진술되었고 재판부는 당사자에게 위 관할조항의 구체적인 의미에 관하여 석명하였으나 조항의 의미가 분명히 밝혀지지 않았다. 2회 변론기일에서 을은 관할위반을 이유로 소송이송을 신청하였는바(1회 변론기일 이후 2회 변론기일까지 당사자가 별도로 준비서면을 제출한 것은 없음), 수원지방법원은 을의 관할위반에 관한 주장 및 이송신청에 대하여 어떻게 판단 또는 조치하여야 하는가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sd944ab8460","sourceFile":"민사소송법사례연습 5주차 답안.txt","pages":[1],"text":"1. (20점)\n\n가. 갑과 을의 관할합의의 성질 (7점)\n\n- 관할합의를 함에 있어 전속적 합의인지, 부가적 합의인지 명시적으로 약정한 경우에는 그 합의에 따르나, 합의 내용이 불분명한 경우에는 당사자에게 석명을 구하고, 석명을 통해서도 내용이 불분명한 경우에 어느 것으로 보아야 할지에 관하여 논의가 있음\n\n- 판례는 법정관할법원 가운데 하나로 관할법원을 특정하는 경우에는 전속적 합의로, 법정관할 법원 외의 다른 법원을 관할법원으로 하는 경우를 부가적 합의로 봄.\n\n- 사안은 당사자의 합의 내용이 전속적 합의인지, 부가적 합의인지 불분명한 경우이고, 법정관할은 서울중앙지방법원(피고 주소지)과 수원지방법원(지참채무)에 인정됨. 따라서 서울중앙지법으로 정한 관할합의는 법정관할법원 중 하나를 특정한 것으로 전속적 합의에 해당함.\n\n- 따라서 서울중앙지법에만 관할이 인정되며 수원지방법원의 관할은 배제됨.\n\n다. 변론관할의 성립 여부 (5점)\n\n- 변론관할의 의미\n\n- 사안에서 수원지방법원에 변론관할이 생기는지 여부가 문제되나, 피고가 관할위반의 항변을 하면서, 조건적으로 본안에 관한 항변을 하였으므로, 수원지방법원에 변론관할이 성립되지 않음\n\n라. 을의 관할위반주장에 관한 법원의 판단 및 이송신청에 관한 법원의 조치 (8점)\n\n- 따라서 갑이 수원지방법원에 이 사건 소를 제기한 것은 관할권이 없는 법원에 소를 제기한 것으로서 을의 관할위반에 관한 주장은 타당함\n\n- 법원은 서울중앙지방법원에 직권으로 사건을 이송하여야 함\n\n- 소송당사자에게는 관할위반을 이유로 한 이송신청권이 인정되지 않으므로 당사자가 관할위반을 이유로 한 이송신청을 한 경우에도 이는 단지 법원의 직권발동을 촉구하는 의미밖에 없는 것이고 법원은 이러한 이송신청에 대하여는 재판을 할 필요가 없음. 따라서 사안에서 재판부는 을의 이송신청에 대해서는 따로 재판을 할 필요가 없음"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-5주-문2":{"id":"class-5주-문2","question":{"segments":[{"sourceId":"s3fd74e102d","sourceFile":"민사소송법사례연습 5주차 문제.txt","pages":[1,2],"text":"민사소송법이론 기말고사\n\n[사례형]\n\n- 4문제 / 80점 만점\n\n- 각 해당 문제에서 “문제의 소재\" 또는 “쟁점\"을 기재하지 말 것(질문을 그대로 다시 기재하지 말 것)\n\n[공통된 사실관계]\n\n수원시 영통구(수원지방법원 관할구역)에 거주(주소지)하는 갑은, 서울시 서초구(서울중앙지방법원 관할구역)에 거주(주소지)하는 을과의 사이에서, 갑이 을로부터 을 소유의 서울시 노원구(서울북부지방법원 관할구역) 소재 X부동산을 매매대금 2억 원에 매수하는 내용의 매매계약을 체결하였고, 매매계약의 내용에 따라 을에게 매매대금 2억 원을 모두 지급하였다. 그런데 을이 위 부동산에 대한 소유권이전등기의무를 지체함에 따라, 갑은 매매계약을 해제하면서 수원지방법원에 을을 피고로 한 매매대금 반환청구소송을 제기하였다.\n\n(※ 아래 각 문항은 상호 독립적이며 무관함)\n\n[추가적 사실관계]\n\n을은 소장 부본을 송달받은 후 A변호사를 소송대리인으로 선임하였고, 소송위임장에는 '1심에 관한 소 취하, 청구의 포기 • 인낙, 상소의 제기에 관한 특별수권을 부여한다\"는 내용이 명시되어 있었다. 그런데 을은 1회 변론기일 전에 사망하였고, 을의 상속인으로는 병, 정이 있다.\n\n(※ 아래 2, 3항은 상호 독립적이며 무관함)\n\n2. 위 1심 소송절차에서 병만이 수계절차를 밟았는데, 1심 법원은 재판을 진행하여 3회 변론기일에 변론을 종결한 후 원고(갑) 승소 판결을 선고하였다. 1심 판결문에는 병만이 피고로 기재되어 있었는바, 이에 A변호사는 상속인 전부라고 생각하고, 병만을 항소인으로 하여 항소장을 제출하였다. 이 경우 위 항소 제기가 정에게 효력이 있는지 여부를 설명하라. (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sd944ab8460","sourceFile":"민사소송법사례연습 5주차 답안.txt","pages":[1,2],"text":"2. (20점)\n\n가. 소송대리인이 있는 경우 소송계속 중 당사자 사망의 효력 (10점)\n\n- 소송계속 중 당사자가 사망하면 소송당사자의 지위가 상속인에 당연승계되고 소송절차는 중단됨\n\n- 그러나 소송대리인이 있는 경우 당해 소송대리인이 상속인들 모두를 위한 대리인이 되어 소송수행을 할 수 있으며 소송절차는 중단되지 않음. 이 경우 상속인의 수계 절차 여부와 상관없이 소송대리인이 소송을 수행하며, 상속인들 모두에 대하여 판결의 효력이 미침\n\n- 사안에서 A변호사가 있으므로 1심 소송절차는 중단되지 않고, A변호사는 병과 정의 대리인으로서 소송수행할 수 있으며, 수계절차를 밟지 않은 정에게도 1심 판결의 효력이 미침\n\n나. A변호사의 항소제기가 정에게 효력이 미치는지 (10점)\n\n- 심급대리의 원칙상 1심 판결정본 송달로 소송대리인의 소송수행권이 소멸하므로 위 시점에 소송이 중단되나, 소송대리인에게 상소제기의 특별수권 있는 경우에는 상소기간 도과시 또는 상소 제기시까지 소송대리인의 소송수행권이 존속하므로 위 시점에 소송이 중단됨\n\n- 사안에서 을의 소송대리인으로 A변호사가 선임되어 있고 A변호사는 상소제기의 특별수권을 받았는바, 상소제기의 특별수권 있는 A변호사가 항소한 것은 상속인 전원을 위하여 항소한 것이 되므로(항소인 표시에 정이 누락되어도 마찬가지임), A변호사의 항소는 정에게도 효력이 있음(대판 2007다22859)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-5주-문3":{"id":"class-5주-문3","question":{"segments":[{"sourceId":"s3fd74e102d","sourceFile":"민사소송법사례연습 5주차 문제.txt","pages":[2],"text":"민사소송법이론 기말고사\n\n[사례형]\n\n- 4문제 / 80점 만점\n\n- 각 해당 문제에서 “문제의 소재\" 또는 “쟁점\"을 기재하지 말 것(질문을 그대로 다시 기재하지 말 것)\n\n[공통된 사실관계]\n\n수원시 영통구(수원지방법원 관할구역)에 거주(주소지)하는 갑은, 서울시 서초구(서울중앙지방법원 관할구역)에 거주(주소지)하는 을과의 사이에서, 갑이 을로부터 을 소유의 서울시 노원구(서울북부지방법원 관할구역) 소재 X부동산을 매매대금 2억 원에 매수하는 내용의 매매계약을 체결하였고, 매매계약의 내용에 따라 을에게 매매대금 2억 원을 모두 지급하였다. 그런데 을이 위 부동산에 대한 소유권이전등기의무를 지체함에 따라, 갑은 매매계약을 해제하면서 수원지방법원에 을을 피고로 한 매매대금 반환청구소송을 제기하였다.\n\n(※ 아래 각 문항은 상호 독립적이며 무관함)\n\n[추가적 사실관계]\n\n을은 소장 부본을 송달받은 후 A변호사를 소송대리인으로 선임하였고, 소송위임장에는 '1심에 관한 소 취하, 청구의 포기 • 인낙, 상소의 제기에 관한 특별수권을 부여한다\"는 내용이 명시되어 있었다. 그런데 을은 1회 변론기일 전에 사망하였고, 을의 상속인으로는 병, 정이 있다.\n\n(※ 아래 2, 3항은 상호 독립적이며 무관함)\n\n3. 1심 진행 중 상속인 병과 정이 모두 수계절차를 밟았고 1심 법원은 재판을 진행하여 3회 변론기일에 변론을 종결한 후 갑의 병 • 정에 대한 청구를 모두 기각하는 판결을 선고하였다. 1심 판결정본이 각 당사자에게 모두 적법하게 송달되었는데, 당사자들 및 소송대리인은 항소기간이 지나도록 1심 판결에 대하여 항소하지 않아 그 판결은 그대로 확정되었다. 그런데 그 이후 갑은 을(상속인 병, 정)에 대한 X부동산에 관한 매매계약상 매매대금반환채권을 보전하기 위하여, 을(상속인 병, 정)에 대하여 부당이득반환채무를 부담하고 있던 무를 피고로 하여, 병 • 정을 대위하여 부당이득반환청구소송을 제기하였다. 갑은 병 • 정에게 위 부당이득반환청구소송의 계속 사실을 알렸으며, 위 부당이득반환청구소송에서는 갑과 병 • 정 사이에 진행되었던 위 매매대금반환소송의 경과에 관한 모든 자료가 제출되었다. 위 부당이득반환청구소송의 1심 심리 결과, 병 • 정의 무에 대한 부당이득반환청구권의 실체적 요건이 모두 갖추어진 것으로 밝혀졌다면, 1심 법원은 어떤 판결을 선고하여야 하는가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sd944ab8460","sourceFile":"민사소송법사례연습 5주차 답안.txt","pages":[2,3],"text":"3. (20점)\n\n가. 채권자대위소송의 법적 성격 (5점)\n\n- 채권자 대위소송의 법적성격을 법정소송담당이라고 보는 판례에 의할 경우 피보전권리는 당사자적격의 문제로 귀결되고, 소송물은 피대위권리임.\n\n나. 채권자대위소송에서 피보전채권 흠결의 소송법적 효과 (10점)\n\n- 채권자대위소송에서 피보전권리에 관하여 피보전채권의 존재 및 이행기 도래, 채무자의 권리 불행사, 보전의 필요성 등의 요건을 갖추어야 하는바, 이러한 요건 흠결시에는 당사자적격 흠결로 귀결됨\n\n- 채권자가 채무자를 상대로 피보전채권의 이행을 구하는 소를 제기하였으나 패소확정판결을 받았다면 그 확정판결의 기판력으로 말미암아 채무자에게 동일한 원인으로 동일한 청구를 할 수 없으므로, 그러한 권리를 보전하기 위하여 채무자의 제3채무자에 대한 권리를 행사하는 채권자대위소송은 보전의 필요성이 없어 당사자적격 흠결로 부적법\n\n라. 사안의 해결 (5점)\n\n- 사안에서 갑이 병,정에 대한 매매대금반환청구소송에서 패소하였고 당사자가 이에 항소하지 않아 위 판결은 확정되었음. 그 후에 갑이 다시 매매대금반환채권을 피보전권리로 하여 병, 정을 대위하여 무에게 부당이득반환청구소송을 제기하였는바, 위 채권자대위소송은 피보전채권에 관한 갑 패소의 확정판결이 존재하므로 보전의 필요성이 없어 당사자적격 흠결로 부적법함.\n\n- 법원은 소각하 판결을 선고하여야 함."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-5주-문4":{"id":"class-5주-문4","question":{"segments":[{"sourceId":"s3fd74e102d","sourceFile":"민사소송법사례연습 5주차 문제.txt","pages":[2],"text":"4. 갑은 자신이 운행하는 자동차에 관하여 병회사의 자동차보험에 가입하였다. 한편, 을은 파란색 보행등이 켜진 횡단보도를 건너다가 갑의 승용차와 충돌사고가 발생하여 상해를 입어, 병회사를 상대로 위 사고로 인한 손해배상청구의 소를 제기하였다. 을은 위 소송에서 \"갑의 승용차가, 파란색 보행등이 켜진 횡단보도를 지나던 을을 충돌하였다\"고 주장하였고, 이에 대해 병회사는 \"갑의 승용차가 횡단보도 앞 정지선에 정지하고 있었는데, 정이 운행하는 뒷차에 의한 충돌의 충격으로 횡단보도에 진입하게 된 것\"이라고 항변하였다. 법원은 '갑의 승용차가 파란색 보행등이 켜진 횡단보도 안에 진입한 사실″에 대해서는 심증을 형성하였으나, \"갑의 승용차가 정지된 상태에서 뒷차에 의한 충격의 결과로 횡단보도 안에 진입하였다는 사실\"에 대해서는 심증을 형성하지 못하였다. 이 경우 법원은 갑의 과실을 인정할 수 있는가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sd944ab8460","sourceFile":"민사소송법사례연습 5주차 답안.txt","pages":[3],"text":"4. (20점)\n\n가. (10점)\n\n- 법률요건분류설에 따라 불법행위에서 가해행위, 손해발생, 가해자의 고의 과실, 가해행위와 손해의 인과관계는 원고(피해자)인 을에게 입증책임이 있다.\n\n- 그런데 인과관계 및 가해자의 고의 과실과 관련하여, 고도의 개연성이 있는 경험법칙을 이용하여 간접사실로부터 주요사실을 추정할 수 있는바, 이를 일응의 추정(정형적 사상경과를 이용한 추정)이라 한다.\n\n- 을은 갑의 차량이 보행신호 중 횡단보도에 진입한 사실(간접사실)을 입증하여, 일응의 추정에 따라 요건사실인 인과관계와 가해자의 과실을 입증할 수 있다.\n\n- 이때 가해자는 간접반증을 통하여, 즉 그 간접사실과 양립하는 별개의 사실(갑 승용차의 횡단보도 진입이 뒷차에 의한 충격의 결과라는 사실)을 입증함으로써 일응의 추정을 복멸할 수 있다.\n\n나.(10점)\n\n사안에서, 법원이 '갑의 승용차가 파란색 보행등이 켜진 횡단보도 안에 진입한 사실' 에 대해 심증을 형성하였다면, 위 간접사실을 기초로 한 일응의 추정에 따라 '인과관계'와 '갑의 과실'이 입증된 것으로 볼 수 있다. 따라서 병회사는 '갑 승용차의 횡단보도 진입이 뒷차에 의한 충격의 결과라는 별개의 간접사실에 대하여 입증하여야 하는데 이를 입증하지 못한 것이므로, 일응의 추정의 복멸에 성공하지 못한 것이다.\n\n- 따라서 법원은 일응의 추정에 따라 (인과관계 및) 갑의 과실을 인정할 수 있다."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-6주-문제1-1":{"id":"class-6주-문제1-1","question":{"segments":[{"sourceId":"s27b66636e3","sourceFile":"민사소송법사례연습 6주차 문제.txt","pages":[1],"text":"문제1.\n\n〈기초적 사실관계〉\n\n갑은 을에 대하여 1억 원의 물품대금채권을 가지고 있는데, 위 물품대금채권 성립 이후 을은 자신의 유일한 재산인 X부동산을 병에게 매각하고 그에 관한 소유권이전등기를 병에게 경료하여 주었다. (※ 아래 각 지문은 상호 독립적이고 무관함)\n\n1. 갑은 을과 병 사이의 매매계약이 통정허위표시로서 무효라고 주장하면서, 을에 대한 물품대금채권을 보전하기 위하여 을을 대위하여 병을 상대로 병 명의의 소유권이전등기말소등기절차의 이행을 구하는 소(\"전소\")를 제기함과 아울러 그와 동시에 을에게 위 소 제기사실을 고지하였다. 위 소송에서 갑의 을에 대한 물품대금채권의 부존재를 이유로 소각하 판결이 선고되었고 그 판결은 확정되었다. 그 이후 갑이 을을 상대로 위 물품대금의 지급을 구하는 소(\"후소\")를 제기하였는데, 을은 후소가 전소의 기판력에 저촉되어 허용될 수 없다고 주장하였다. 후소 법원은 을의 주장에 대하여 어떻게 판단하여야 하는가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sa8c509fa84","sourceFile":"민사소송법사례연습 6주차 답안.txt","pages":[1],"text":"문제1의 1. (20점)\n\n가. 쟁점 (2점)\n\n- 채권자대위소송에서 피보전채권의 흠으로 소각하 판결이 확정된 이후, 채권자가 채무자를 상대로 피보전채권의 이행을 구하는 소송을 제기하는 것이 기판력에 저촉되는지 여부\n\n나. 채권자대위소송의 법적 성격 (3점)\n\n- 법정소송담당설 : 피보전채권은 원고적격의 문제, 피대위채권은 소송물로서 본안판단의 문제\n\n다. 채권자대위소송에서 피보전채권의 흠으로 소각하 판결이 확정된 경우 기판력의 발생 범위 (10점)\n\n: 대법원 2014. 1. 23. 선고 2011다108095 판결\n\n민사소송법 제218조 제3항은 '다른 사람을 위하여 원고나 피고가 된 사람에 대한 확정판결은 그 다른 사람에 대하여도 효력이 미친다.'고 규정하고 있으므로, 채권자가 채권자대위권을 행사하는 방법으로 제3채무자를 상대로 소송을 제기하고 판결을 받은 경우 채권자가 채무자에 대하여 민법 제405조 제1항에 의한 보존행위 이외의 권리행사의 통지, 또는 민사소송법 제84조에 의한 소송고지 혹은 비송사건절차법 제49조 제1항에 의한 법원에 의한 재판상 대위의 허가를 고지하는 방법 등 어떠한 사유로 인하였든 적어도 채권자대위권에 의한 소송이 제기된 사실을 채무자가 알았을 때에는 그 판결의 효력이 채무자에게 미친다고 보아야 한다. 이때 채무자에게도 기판력이 미친다는 의미는 채권자대위소송의 소송물인 피대위채권의 존부에 관하여 채무자에게도 기판력이 인정된다는 것이고, 채권자대위소송의 소송요건인 피보전채권의 존부에 관하여 당해 소송의 당사자가 아닌 채무자에게 기판력이 인정된다는 것은 아니다. 따라서 채권자가 채권자대위권을 행사하는 방법으로 제3채무자를 상대로 소송을 제기하였다가 채무자를 대위할 피보전채권이 인정되지 않는다는 이유로 소각하 판결을 받아 확정된 경우 그 판결의 기판력이 채권자가 채무자를 상대로 피보전채권의 이행을 구하는 소송에 미치는 것은 아니다.\n\n라. 사안의 해결 (5점)\n\n- 후소는 기판력에 저촉되지 않으므로 을의 주장을 배척하여야 한다."}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-6주-문제1-2":{"id":"class-6주-문제1-2","question":{"segments":[{"sourceId":"s27b66636e3","sourceFile":"민사소송법사례연습 6주차 문제.txt","pages":[1],"text":"문제1.\n\n〈기초적 사실관계〉\n\n갑은 을에 대하여 1억 원의 물품대금채권을 가지고 있는데, 위 물품대금채권 성립 이후 을은 자신의 유일한 재산인 X부동산을 병에게 매각하고 그에 관한 소유권이전등기를 병에게 경료하여 주었다. (※ 아래 각 지문은 상호 독립적이고 무관함)\n\n2. X부동산에는 갑의 물품대금채권 성립 이전부터 을에 대한 채권자 정명의의 근저당권이 설정되어 있었는데, 병이 X토지의 소유권을 이전받은 후에 정에게 그 피담보채무를 전액 변제함에 따라 정명의의 근저당권설정등기는 말소되었다. 이에 갑은 병을 상대로 을과 병간의 매매계약을 사해행위로서 전부취소하고 원상회복으로 병 명의의 소유권이전등기의 말소를 구하는 소송을 제기하였다. 위 소송에서 병은 자신이 선의임을 항변하면서, “설령 위 매매계약이 사해행위로서 취소된다 하더라도, 갑이 매매계약의 전부취소 및 원물반환을 구하는 것은 부당하다″는 취지로 항변하였으나 갑은 변론종결시까지 종전의 청구취지를 그대로 유지하였다. 법원의 심리 결과 사해행위의 실체적 요건에 관한 갑의 주장사실이 모두 인정될 경우 법원은 어떤 판결을 선고하여야 하는가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sa8c509fa84","sourceFile":"민사소송법사례연습 6주차 답안.txt","pages":[1,2],"text":"문제1의 2. (20점)\n\n가. 사해행위의 취소 및 원상회복의 범위 (10점)\n\n- 저당권이 설정되어 있는 부동산이 사해행위로 이전된 경우에 그 사해행위는 부동산의 가액에서 저당권의 피담보채권액을 공제한 잔액의 범위 내에서만 성립한다고 보아야 하므로, 사해행위 후 변제 등에 의하여 저당권설정등기가 말소된 경우 위 잔액의 범위 내에서만 사해행위를 취소하고 가액배상을 명하여야 한다는 것이 판례의 입장임\n\n나. 법원의 판단 (5점)\n\n- 판례는 사해행위인 계약의 전부취소와 부동산 자체의 반환을 구하는 청구취지 가운데에는 위와 같이 일부취소를 하여야 할 경우 그 일부취소와 가액배상을 구하는 취지도 포함되어 있다고 보고 있으므로 청구취지의 변경이 없더라도 바로 일부취소 및 가액배상을 구할 수 있다는 입장임\n\n다. 사안의 해결 (5점)\n\n- 따라서 갑이 매매계약을 전부 취소하고 병 명의의 소유권이전등기말소를 구하는 종전의 청구취지를 그대로 유지할 경우에도, 법원은 부동산의 가액에서 근저당권의 피담보채무를 공제한 잔액의 범위 내에서 매매계약의 일부취소와 가액배상을 명하여야 하며, 이는 처분권주의 위반이 아님"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-6주-문제2-1":{"id":"class-6주-문제2-1","question":{"segments":[{"sourceId":"s27b66636e3","sourceFile":"민사소송법사례연습 6주차 문제.txt","pages":[2],"text":"문제 2\n\n〈기초적 사실관계〉\n\n갑은 2018. 4. 1. 을에게 금 1억 원을 대여하였고, 병의 대리인인 정으로부터 '병이 위 대여금채무를 연대보증하는 내용’의 병 명의의 지급각서를 교부받았다. 갑은 2019. 2. 1. 병을 상대로 위 1억 원의 연대보증채무의 이행을 구하는 소(″전소\")를 제기하였고 병은 위 소송에서 \"주채무가 2018. 10. 1. 을의 변제로 소멸하였다″고 주장하였다. 위 1심 진행 도중 병의 소송고지에 따라 을이 병측에 보조참가하였다. (※ 아래 각 지문은 상호 독립적이고 무관함)\n\n1. 병은 주채무 소멸 사실의 입증에 실패하여 1심에서 패소하였고, 위 판결정본은 2019. 6. 11. 을에게, 2019. 6. 15. 갑과 병에게 각각 송달되었다. 이에 대하여 을만이 2019. 6. 17. 항소하였다. 그런데 병은 2019. 7. 20. 을의 항소를 취하한 후에, 2019. 8. 1. 을을 상대로 위 연대보증채무의 이행에 따른 구상금 청구소송(\"후소″)을 제기하였는데 을은 후소에서 \"주채무가 2018. 10. 1. 을의 변제로 소멸하였다″는 주장을 하였다. 을의 항소와 병의 항소 취하는 적법한 것인지의 여부를 설명하고, 후소에서의 을의 위 주채무 변제소멸 주장이 적법한 것인지의 여부에 대하여 설명하라. (30점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sa8c509fa84","sourceFile":"민사소송법사례연습 6주차 답안.txt","pages":[2,3],"text":"문제2의 1. (30점)\n\n가. 쟁점 (2점)\n\n- 보조참가인의 항소의 적법성, 보조참가인의 항소에 대한 피참가인의 항소취하의 적법성, 보조참가의 참가적 효력\n\n나. 보조참가인의 항소의 적법성 (8점)\n\n- 보조참가인은 피참가인의 승소를 위하여 필요한 소송행위를 자기의 이름으로 할 수 있으며, 이러한 참가인의 소송행위는 피참가인 자신이 행한 것과 같은 효력이 생김. 그러나 참가 당시의 소송진행 정도에 따라 피참가인도 할 수 없는 소송행위는 참가인도 할 수 없음. 따라서 보조참가인은 피참가인의 상소기간 내에서 자기의 이름으로 상소할 수 있음\n\n- 사안에서 보조참가인인 을은 피참가인인 병의 항소기간 내(판결정본 송달일로부터 2주 이내)에 항소를 제기하였으므로 을의 항소는 적법하며 병에게 효력이 있음\n\n다. 피참가인의 항소취하의 적법성 (5점)\n\n- 참가인은 피참가인의 행위에 어긋나는 소송행위를 할 수 없으며, 참가인의 행위와 어긋나는 행위를 피참가인이 뒤에 한 경우에도 참가인의 행위는 무효가 됨. 따라서 참가인이 제기한 항소를 피참가인이 취하할 수 있음.\n\n- 사안에서 피참가인인 병이 보조참가인인 을이 제기한 항소를 취하한 것은 적법\n\n라. 후소에서의 을의 위 주채무 변제소멸 주장이 적법한지 여부(보조참가의 참가적 효력) (15점)\n\n- 참가적 효력 : 피참가인이 전소에서 패소한 뒤에 피참가인이나 참가인이 소송을 제기하는 경우 피참가인에 대한 관계에서 참가인의 전소의 판결내용이 부당하다고 주장할 수 없는 구속력\n\n- 참가적 효력의 범위 : 판결주문에 대해서뿐만 아니라 판결이유 가운데 패소이유가 되었던 사실상·법률상 판단으로서 참가인이 피참가인과 공동이익으로 주장하거나 다툴 수 있었던 사항에 미침\n\n- 참가적 효력의 배제 : 그러나 참가인의 행위가 피참가인의 행위와 어긋나게 되어 효력을 가지지 않게 된 경우, 피참가인이 참가인의 행위를 방해한 경우 등에는 참가적 효력이 배제됨\n\n- 사안에서, 주채무 변제소멸 여부에 관한 주장은 전소에서의 판결이유 가운데 패소이유가 되었던 부분에 대한 판단으로서 참가인인 을과 피참가인인 병이 공동이익으로 주장할 수 있었던 사항에 해당하여 참가적 효력이 발생되는 범위임. 그러나 피참가인인 병이 보조참가인인 을이 제기한 항소를 취하한 것은 피참가인이 참가인의 행위를 방해한 경우에 해당하여 참가적 효력이 배제됨. 따라서 후소에서 을은 주채무 변제 소멸 사실을 주장할 수 있음"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-6주-문제2-2":{"id":"class-6주-문제2-2","question":{"segments":[{"sourceId":"s27b66636e3","sourceFile":"민사소송법사례연습 6주차 문제.txt","pages":[2],"text":"문제 2\n\n〈기초적 사실관계〉\n\n갑은 2018. 4. 1. 을에게 금 1억 원을 대여하였고, 병의 대리인인 정으로부터 '병이 위 대여금채무를 연대보증하는 내용’의 병 명의의 지급각서를 교부받았다. 갑은 2019. 2. 1. 병을 상대로 위 1억 원의 연대보증채무의 이행을 구하는 소(″전소\")를 제기하였고 병은 위 소송에서 \"주채무가 2018. 10. 1. 을의 변제로 소멸하였다″고 주장하였다. 위 1심 진행 도중 병의 소송고지에 따라 을이 병측에 보조참가하였다. (※ 아래 각 지문은 상호 독립적이고 무관함)\n\n2. 을은 1심의 소송계속 중인 2019. 4. 1. 보조참가신청을 취하하였는데, 병이 주채무 소멸 사실의 증명에 실패하여 2019. 5. 30. 1심 패소 판결이 선고되었고 그 판결은 그대로 확정되었다. 이후 병은 을을 상대로 보증채무의 이행에 따른 구상금 청구소송(\"후소\")을 제기하였다. 후소에서 을은 \"주채무가 2017. 10. 1. 을의 변제로 소멸하였다\"는 주장을 하였는데, 이러한 을의 주장은 적법한가? (10점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sa8c509fa84","sourceFile":"민사소송법사례연습 6주차 답안.txt","pages":[3],"text":"문제2의 2. (10점)\n\n가. 쟁점 (2점)\n\n- 보조참가인이 참가신청을 취하한 경우의 참가적 효력 유무\n\n나. 보조참가인이 참가신청을 취하한 경우의 참가적 효력 (8점)\n\n- 참가인은 참가신청을 취하할 수 있지만, 그러한 경우에도 참가적 효력이 미침. 앞서 본 바와 같이 참가적 효력은 판결주문 뿐만 아니라 판결이유 중 판단에도 미침\n\n- 따라서 을이 후소인 구상금청구소송에서 주채무가 변제로 소멸하였다는 주장을 하는 것은 전소의 참가적 효력에 따른 판결이유 중 판단에 반하므로, 적법하지 않음"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}},"class-6주-문제2-3":{"id":"class-6주-문제2-3","question":{"segments":[{"sourceId":"s27b66636e3","sourceFile":"민사소송법사례연습 6주차 문제.txt","pages":[2],"text":"문제 2\n\n〈기초적 사실관계〉\n\n갑은 2018. 4. 1. 을에게 금 1억 원을 대여하였고, 병의 대리인인 정으로부터 '병이 위 대여금채무를 연대보증하는 내용’의 병 명의의 지급각서를 교부받았다. 갑은 2019. 2. 1. 병을 상대로 위 1억 원의 연대보증채무의 이행을 구하는 소(″전소\")를 제기하였고 병은 위 소송에서 \"주채무가 2018. 10. 1. 을의 변제로 소멸하였다″고 주장하였다. 위 1심 진행 도중 병의 소송고지에 따라 을이 병측에 보조참가하였다. (※ 아래 각 지문은 상호 독립적이고 무관함)\n\n3. 위 소송에서 갑은 병에 대한 청구의 증거방법으로 지급각서를 제출하였는데, 병은 “지급각서 상의 인영이 병의 것임은 인정하나 이는 무권대리인인 정이 인장을 도용하여 날인한 것\"이라고 주장하였고 갑은 이에 대해 “정이 날인한 것은 맞지만 정은 병으로부터 위임받은 정당한 권원에 기하여 날인한 것\"이라고 주장하였다. 법원이 심리한 결과 '정이 날인할 때 병으로부터 위임받은 정당한 권원에 기하여 날인한 것이라는 점'에 대하여 확신을 갖지 못하였다. 이 경우 법원은 지급각서를 증거로 하여 병의 연대보증사실을 인정할 수 있는가? (20점)"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true},"answer":{"segments":[{"sourceId":"sa8c509fa84","sourceFile":"민사소송법사례연습 6주차 답안.txt","pages":[3,4],"text":"문제2의 3. (20점)\n\n가. 사문서의 진정성립과 증명책임 (15점)\n\n- 처분문서의 경우 진정성립이 인정되면, 법원은 그 기재내용을 부정할 만한 분명하고도 수긍할 수 있는 반증이 없는 한 그 처분문서에 기재된 문언대로의 의사표시의 존재와 내용을 인정해야 함, 지급각서는 사문서로써 처분문서임.\n\n- 문서제출자(거증자)는 사문서의 진정성립을 증명해야 함\n\n- 사문서의 진정성립에 관하여 판례는 인영의 진정이 인정되면 날인의 진정이 사실상 추정되고, 날인의 진정이 인정되면 민사소송법 제358조에 의하여 문서 전체의 성립의 진정이 추정된다는 입장(2단계의 추정)에 있음\n\n- 사문서에 날인된 작성명의인의 인영이 그의 인장임이 증명되면, 문서제출자의 상대방은 날인의 진정을 깨기 위해 인장도용, 자격모용 등의 사실을 적극적으로 증명해야 하며, 그 증명에 성공한 경우 사문서의 진정성립은 추정되지 않으므로, 문서제출자는 날인행위가 작성명의인으로부터 위임받은 정당한 권원에 기한 것이라는 사실을 증명해야 함\n\n나. 사안의 해결 (5점)\n\n- 사안에서 법원은 정이 날인할 때 병으로부터 적법한 권한을 위임받아 날인한 것이라는 점에 대하여 확신을 갖지 못하였으므로 병이 '인장도용 사실' 등에 대한 증명에 성공하고 갑이 '날인행위가 병으로부터 위임받은 정당한 권원에 의한 것이라는 사실을 증명하지 못한 것임\n\n- 따라서 지급각서의 진정성립은 추정되지 않으므로, 법원은 지급각서를 증거로 하여 병의 연대보증사실을 인정할 수 없음"}],"notice":"이미지 대조·교정된 수업 TXT. 법적 결론은 원문 기준.","contextIncluded":false,"imageReviewed":true}}},"sources":[{"id":"sd518de2552","name":"민사소송법사례연습 2주차 답안1.pdf","pages":2,"sha256":"2780835a2cd54aa1494259f54393eac0f010f79579dbc9caca8dc07271d05670","kind":"pdf","url":"sources/sd518de2552.pdf","scope":"수업 문제·답안"},{"id":"sbdd46b414e","name":"민사소송법사례연습 2주차 답안2.pdf","pages":4,"sha256":"9ec0b411b4bba270e18922130010557b43b49e46cf7a3e2449b5dbb53354b3a7","kind":"pdf","url":"sources/sbdd46b414e.pdf","scope":"수업 문제·답안"},{"id":"s3844552031","name":"민사소송법사례연습 2주차 문제1.pdf","pages":1,"sha256":"fff665b7b865d704c9501a22ef5e6eecde9cba77f79d5dbfac08412f52ec1a77","kind":"pdf","url":"sources/s3844552031.pdf","scope":"수업 문제·답안"},{"id":"s5f94d32e5d","name":"민사소송법사례연습 2주차 문제2.pdf","pages":2,"sha256":"67fb26ad154393ea7c363bbe4407e888447582304b3578e23104b9bc70095992","kind":"pdf","url":"sources/s5f94d32e5d.pdf","scope":"수업 문제·답안"},{"id":"s1deb1ca0bb","name":"민사소송법사례연습 3주차 답안.pdf","pages":12,"sha256":"d3e4e11cc783ea8081394cb856cf636707aa9898ff98c1728fad4422a17cbd55","kind":"pdf","url":"sources/s1deb1ca0bb.pdf","scope":"수업 문제·답안"},{"id":"s3e7fff1fe8","name":"민사소송법사례연습 3주차 문제.pdf","pages":2,"sha256":"4560772ea98f702ce914e6c9e3e33b159067534ea84c53a33dff56061c35892e","kind":"pdf","url":"sources/s3e7fff1fe8.pdf","scope":"수업 문제·답안"},{"id":"s7d6eb58f2f","name":"민사소송법사례연습 4주차 답안.pdf","pages":4,"sha256":"fb6ffdfe830233851202996ea762d70492396bcc495b31f7c7982434456a5903","kind":"pdf","url":"sources/s7d6eb58f2f.pdf","scope":"수업 문제·답안"},{"id":"s05455e5f8f","name":"민사소송법사례연습 4주차 문제.pdf","pages":4,"sha256":"23266980dce2f56422085235a04eef79fda14e09411b95e7d5e8de23e8a0735b","kind":"pdf","url":"sources/s05455e5f8f.pdf","scope":"수업 문제·답안"},{"id":"sd944ab8460","name":"민사소송법사례연습 5주차 답안.pdf","pages":3,"sha256":"c5dfc45ad40b68e8e059d17a6029391bddb73387bf31c7ef988b7f8d648a4f9b","kind":"pdf","url":"sources/sd944ab8460.pdf","scope":"수업 문제·답안"},{"id":"s3fd74e102d","name":"민사소송법사례연습 5주차 문제.pdf","pages":2,"sha256":"fc94607944036c0150dce1e9a43331fbbb1d25e09b951e3a73d148339ae80315","kind":"pdf","url":"sources/s3fd74e102d.pdf","scope":"수업 문제·답안"},{"id":"sa8c509fa84","name":"민사소송법사례연습 6주차 답안.pdf","pages":4,"sha256":"a6681365a93acaaa4dd3c03c068a78ad398e2394adf568568389eeb86966367d","kind":"pdf","url":"sources/sa8c509fa84.pdf","scope":"수업 문제·답안"},{"id":"s27b66636e3","name":"민사소송법사례연습 6주차 문제.pdf","pages":2,"sha256":"c5da2691b6c08cefad3b9f4f31c509cb0416cb7645860814248f430bfc40b56b","kind":"pdf","url":"sources/s27b66636e3.pdf","scope":"수업 문제·답안"},{"id":"sa975940342","name":"민사소송법사례연습 1주차 문제 답안.pdf","pages":4,"sha256":"374ce93c4f6fcb824ebcdd58d11a4a7e7ff357b5a890ed9af52db4a5dfccde17","kind":"pdf","url":"sources/sa975940342.pdf","scope":"수업 문제·답안"}],"links":{"class-1주-문1":["confession-scope","denial-defense"],"class-1주-문2":["document-authenticity"],"class-1주-문3":["document-substantive"],"class-1주-문4":["document-blank","document-authenticity"],"class-1주-문5":["confession-withdrawal","confession-scope"],"class-2주-문제1-1":["intervention-succession"],"class-2주-문제1-2":["resjudicata-subject","intervention-succession"],"class-2주-문제1-3":["resjudicata-subject","claim-object"],"class-2주-문제1-4":["joint-independent"],"class-2주-문제2-1":["withdrawal"],"class-2주-문제2-2":["claim-joinder"],"class-2주-문제2-3":["resjudicata-time"],"class-2주-문제2-4":["resjudicata-setoff","resjudicata-object"],"class-2주-문제2-5":["counterclaim"],"class-3주-사례1":["pleading-major","evidence-common"],"class-3주-사례2":["denial-defense"],"class-3주-사례3":["class-formative-right","settlement"],"class-3주-사례4-1":["withdrawal"],"class-3주-사례4-2":["withdrawal"],"class-4주-문1":["resjudicata-setoff","resjudicata-object"],"class-4주-문2":["document-authenticity","document-substantive","confession-withdrawal"],"class-4주-문3-1":["absence-confession"],"class-4주-문3-2":["registration-presumption"],"class-4주-문3-3":["joint-independent"],"class-5주-문1":["jurisdiction-agreement","jurisdiction-appearance"],"class-5주-문2":["party-death","appeal-scope"],"class-5주-문3":["subrogation-standing"],"class-5주-문4":["indirect-disproof"],"class-6주-문제1-1":["subrogation-standing","resjudicata-subject"],"class-6주-문제1-2":["disposition"],"class-6주-문제2-1":["intervention-assistance"],"class-6주-문제2-2":["intervention-assistance"],"class-6주-문제2-3":["document-authenticity","document-blank"]},"quotes":[{"caseId":"class-1주-문1","groupId":"confession-scope","sourceId":"sa975940342","sourcePages":[2],"text":"자백의 의의. 변론주의의 내용 중 하나로서 자백에는 법원 및 당사자에 대한 구속력이 발생. 그 대상이 되는 사실은 원칙적으로 주요사실에 한한다는 것이 통설, 판례의 입장. 그렇지 않을 경우 자유심증주의에 반하게 됨. 사안의 경우 을이 계약 성립 시에 외국에 출장 중이었다는 주장 내지 진술(현장에 부재하였다는 진술)은 갑이 주장, 증명책임을 부담하는 계약체결 사실과는 양립되지 않는 별개의 사실을 부가하면서 갑의 주장사실을 부정하는 것이기 때문에 이유부 부인에 해당함. 즉 이는 주요사실이 아니라 갑이 주장하는 계약체결사실의 부존재를 추인케 하는 간접사실에 불과하므로 이를 자백하였다 하더라도 자백으로서의 효력(구속력)은 발생하지 않는다(12점).","sha256":"ccb99e6946546510b229a06b8c84b597369c90c9578425d24a8159b83abdf915","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-1주-문1","groupId":"denial-defense","sourceId":"sa975940342","sourcePages":[2],"text":"자백의 의의. 변론주의의 내용 중 하나로서 자백에는 법원 및 당사자에 대한 구속력이 발생. 그 대상이 되는 사실은 원칙적으로 주요사실에 한한다는 것이 통설, 판례의 입장. 그렇지 않을 경우 자유심증주의에 반하게 됨. 사안의 경우 을이 계약 성립 시에 외국에 출장 중이었다는 주장 내지 진술(현장에 부재하였다는 진술)은 갑이 주장, 증명책임을 부담하는 계약체결 사실과는 양립되지 않는 별개의 사실을 부가하면서 갑의 주장사실을 부정하는 것이기 때문에 이유부 부인에 해당함. 즉 이는 주요사실이 아니라 갑이 주장하는 계약체결사실의 부존재를 추인케 하는 간접사실에 불과하므로 이를 자백하였다 하더라도 자백으로서의 효력(구속력)은 발생하지 않는다(12점).","sha256":"ccb99e6946546510b229a06b8c84b597369c90c9578425d24a8159b83abdf915","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-1주-문2","groupId":"document-authenticity","sourceId":"sa975940342","sourcePages":[2,3],"text":"사안에서와 같이 인영부분은 인정하되 날인사실을 부인한 경우, 통설과 판례는 이른바 2단의 추정이론으로 사문서 전체의 진정성립을 추정하고 있다(작성명의인의 인영부분이 인정되면 그의 의사에 기해 날인행위가 행하여졌음이 추정되므로1) 결국 제358조에 의하여 문서전체의 진정성립이 추정된다). 따라서 을의 인장의 도용사실 또는 모용사실에 대하여(즉 제3자에 의해 날인행위가 행하여졌음에 대하여) 증명을 하지 못해 진위불명 상태에 빠진 이상 차용증서의 진정성립은 추정되므로 진정성립을 인정할 수 있다(12점).","sha256":"bad476ee2290ee00b0b71dcab8d56013e779d0784cedb06d7c2baf119fe0d77a","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-1주-문3","groupId":"document-substantive","sourceId":"sa975940342","sourcePages":[3],"text":"처분문서의 경우 보고문서와는 달리 형식적 증거력이 인정되면 즉 진정성립이 인정되면 특별한 사정이 없는 이상 실질적 증거력이 인정된다. 차용증서는 증명하고자 하는 소비대차계약이라는 법률행위의 존재를 나타내는 처분문서이므로 그 진정성립이 인정되면 특별한 사정이 없는 이상(그 기재내용을 부정해야 할 정도로 분명하고도 확실한 반증이 없는 이상) 그에 기재되어 있는 문언대로 소비대차계약이 체결된 사실을 인정하여야 한다(12점).","sha256":"6f0fa753ace92a087caf7e50f0567a0e632b71af7fa132bd0617748b1a6fad9a","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-1주-문4","groupId":"document-blank","sourceId":"sa975940342","sourcePages":[3],"text":"이른바 2단의 추정이론은 사문서의 내용이 먼저 기재되어 완성된 상태에서 서명이나 날인이 행해진 경우에만 적용되는 것이고, 사안에서와 같이 문서가 미완성 상태에서 서명이나 날인이 행해진 경우에는 적용되지 않는다. 따라서 위 차용증서가 백지상태로 작성·교부되었고, 갑이 추후 위 차용증서에 그 내용을 기재한 것(백지부분을 보충한 것)이라는 사실이 증명된 이상, 거증자인 갑은 을로부터 백지부분의 보충 등 그 작성에 관한 권한을 위임받았음을 증명하여야 하고(증명책임), 이를 증명하지 못하면 위 차용증서의 진정성립은 인정될 수 없다(12점).","sha256":"9018debcb99116b0f7907eda0e035d5df3368429ef511b3b20bcfad3f7ddb917","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-1주-문4","groupId":"document-authenticity","sourceId":"sa975940342","sourcePages":[3],"text":"이른바 2단의 추정이론은 사문서의 내용이 먼저 기재되어 완성된 상태에서 서명이나 날인이 행해진 경우에만 적용되는 것이고, 사안에서와 같이 문서가 미완성 상태에서 서명이나 날인이 행해진 경우에는 적용되지 않는다. 따라서 위 차용증서가 백지상태로 작성·교부되었고, 갑이 추후 위 차용증서에 그 내용을 기재한 것(백지부분을 보충한 것)이라는 사실이 증명된 이상, 거증자인 갑은 을로부터 백지부분의 보충 등 그 작성에 관한 권한을 위임받았음을 증명하여야 하고(증명책임), 이를 증명하지 못하면 위 차용증서의 진정성립은 인정될 수 없다(12점).","sha256":"9018debcb99116b0f7907eda0e035d5df3368429ef511b3b20bcfad3f7ddb917","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-1주-문5","groupId":"confession-withdrawal","sourceId":"sa975940342","sourcePages":[3,4],"text":"문서의 진정성립에 관한 자백은 보조사실에 관한 것이지만 이에 대하여 재판상 자백과 같은 구속력이 인정된다(판례). 따라서 법원은 이를 기초로 판단하여야 하고(차용증서의 진정성립을 인정하여야 하고) 당사자는 이에 관한 자백을 취소하거나 철회할 수 없다. 당사자가 이를 취소 내지 철회하기 위해서는 상대방의 동의가 있거나, 진실에 반하고 착오로 인해 자백하였음을 증명하거나 그 자백이 형사상 처벌받을 제3자의 행위로 인하여 행하여졌다는 점을 증명하여야만 한다(7점).","sha256":"54194d989984b8c5ffc64f60f4d52f435ac4dd1a5a471e385c8bb533e1e8be02","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-1주-문5","groupId":"confession-scope","sourceId":"sa975940342","sourcePages":[3,4],"text":"문서의 진정성립에 관한 자백은 보조사실에 관한 것이지만 이에 대하여 재판상 자백과 같은 구속력이 인정된다(판례). 따라서 법원은 이를 기초로 판단하여야 하고(차용증서의 진정성립을 인정하여야 하고) 당사자는 이에 관한 자백을 취소하거나 철회할 수 없다. 당사자가 이를 취소 내지 철회하기 위해서는 상대방의 동의가 있거나, 진실에 반하고 착오로 인해 자백하였음을 증명하거나 그 자백이 형사상 처벌받을 제3자의 행위로 인하여 행하여졌다는 점을 증명하여야만 한다(7점).","sha256":"54194d989984b8c5ffc64f60f4d52f435ac4dd1a5a471e385c8bb533e1e8be02","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제1-1","groupId":"intervention-succession","sourceId":"sd518de2552","sourcePages":[1],"text":"소송물인 권리관계 자체를 승계한 자뿐만 아니라 그 계쟁물을 승계 받은 자도 승계인에 포함된다. 사안의 경우 정은 물권적 청구권을 소송물로 하는 소송의 사실심 변론종결 이전에 피고로부터 계쟁물의 일부를 넘겨받았으므로 피고 적격의 승계인에 해당한다. 따라서 소송계속 중 제3자가 소송목적인 의무의 목적물을 승계한 경우에 해당되어 갑은 정으로 하여금 소송을 인수하게 할 수 있다(민소법 제82조 제1항). (15점)","sha256":"7b0f2f8b2cd41c9ff6ed107c0040913b1d7fa477d1c125c3775da068ea56efdc","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제1-2","groupId":"resjudicata-subject","sourceId":"sd518de2552","sourcePages":[1],"text":"본 사안의 경우 갑과 병 간의 소송의 소송물은 물권적 청구권에 기한 것으로서 정은 변론종결 이후부터 위 건물 일부를 점유하게 되었다. 따라서 판례에 따르면 정은 변론종결 후에 계쟁물을 양수한 승계인에 해당하여 그에 대해 기판력이 미치게 된다(민사소송법 제218조 제1항). 따라서 갑은 승계집행문을 부여받아 정에 대하여 강제집행을 할 수 있다(15점).","sha256":"d3cb36eecc7080fed64b8f1ac3ffef407aca6659fc6fc330c8a71ac630726212","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제1-2","groupId":"intervention-succession","sourceId":"sd518de2552","sourcePages":[1],"text":"본 사안의 경우 갑과 병 간의 소송의 소송물은 물권적 청구권에 기한 것으로서 정은 변론종결 이후부터 위 건물 일부를 점유하게 되었다. 따라서 판례에 따르면 정은 변론종결 후에 계쟁물을 양수한 승계인에 해당하여 그에 대해 기판력이 미치게 된다(민사소송법 제218조 제1항). 따라서 갑은 승계집행문을 부여받아 정에 대하여 강제집행을 할 수 있다(15점).","sha256":"d3cb36eecc7080fed64b8f1ac3ffef407aca6659fc6fc330c8a71ac630726212","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제1-3","groupId":"resjudicata-subject","sourceId":"sd518de2552","sourcePages":[1,2],"text":"- 갑이 받는 확정판결의 기판력이 정에게 확장되는 것인가가 쟁점이다. 판례에 의하면 이는 갑이 을과 병을 상대로 제기한 전소의 소송물이 물권적 청구권에 기한 것인가 채권적 청구권에 기한 것인가의 여부에 따라 결정된다. 건물의 소유자인 갑이 소유권에 기하여 을과 병이 무단 점유자임을 주장하면서 이들을 상대로 차임 상당의 부당이득반환을 구하는 소송을 제기하여 그에 관한 판결이 확정된 경우, 이러한 소송의 소송물은 채권적 청구권인 부당이득반환청구권이므로, 전소의 변론종결 후에 건물의 소유권을 취득한 정은 민사소송법 제218조 제1항에 의하여 확정판결의 기판력이 미치는 변론을 종결한 뒤의 승계인에 해당한다고 볼 수 없다(대법원 2016.6.28. 선고 2014다31721 판결 참조)(9점).","sha256":"898e2ba2458c7e805a4b3ed696b88050f7ed3e9074da76c42d6c7494639d412f","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제1-3","groupId":"claim-object","sourceId":"sd518de2552","sourcePages":[1,2],"text":"- 건물 소유권에 기한 물권적 청구권을 원인으로 하는 건물인도청구소송의 소송물은 건물 소유권이 아니라 그 물권적 청구권인 건물인도청구권이므로 그 소송에서 청구기각된 확정판결의 기판력은 건물인도청구권의 존부 그 자체에만 미치는 것이고, 소송물이 되지 아니한 건물 소유권의 존부에 관하여는 미치지 아니하므로, 그 건물인도소송의 사실심 변론종결 후에 그 패소자인 건물 소유자 갑으로부터 건물을 매수하고 소유권이전등기를 마침으로써 그 소유권을 승계한 정의 건물 소유권의 존부에 관하여는 위 확정판결의 기판력이 미치지 않는다. 또한 이 경우 정이 가지게 되는 물권적 청구권인 건물인도청구권은 적법하게 승계한 건물 소유권의 일반적 효력으로서 발생된 것이고, 위 건물인도소송의 소송물인 패소자 갑의 건물명도청구권을 승계함으로써 가지게 된 것이라고는 할 수 없으므로, 정은 위 확정판결의 변론종결 후의 승계인에 해당한다고 할 수 없다(대법원 1999. 10. 22. 선고 98다6855 판결 참조)(9점).","sha256":"2b48498c903cbcfe2b31b7337f564f51b15e1cb87396622e5bbde047e39c90f5","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제1-4","groupId":"joint-independent","sourceId":"sd518de2552","sourcePages":[2],"text":"- 갑이 을과 병을 상대로 하는 소송은 민소법 제65조 후문에 해당되는 통상공동소송이다. 따라서 공동소송인 독립의 원칙이 적용된다. 위 원칙의 개념(민소법 제66조)을 설시해야 한다. 그에 따라 을만이 항소할 경우 갑과 병 사이의 판결은 분리되어 확정된다(5점).","sha256":"ba943903849f2d006f7136310bd99d058d0b0dccef78f301f13d4aea53763331","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제2-1","groupId":"withdrawal","sourceId":"sbdd46b414e","sourcePages":[1],"text":"절차의 명확성과 안정성의 요청 때문에 민법상 의사표시의 하자에 관한 규정은 소송행위에 적용되지 않음이 원칙. 다만, 소의 취하와 같은 소송행위가 사기 등 제3자의 형사상 처벌받을 행위로 인하여 행해졌을 때, 소송법상 이에 대한 구제방법을 인정하는 것이 일반적인 견해임. 소취하의 무효를 주장하면서 변론기일 지정신청을 하는 방법과 다시 소유권이전등기청구의 소를 제기하는 방법을 생각할 수 있는데, 후자의 경우 재소금지에 해당하는 것은 아닌지의 문제가 있음.","sha256":"31a01ee644b4d27003db06dc5438c08bd563ace9fefd7c57d67ef8a4bb9c8d1f","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제2-2","groupId":"claim-joinder","sourceId":"sbdd46b414e","sourcePages":[1,2],"text":"선택적, 예비적 병합의 경우, 병합된 여러 개의 청구는 동일한 절차에 불가분적으로 결합되어 있기 때문에 일부판결을 선고할 수 없다(통설, 판례). 사안에서와 같이 법원이 주위적 청구만을 배척하고 예비적 청구에 대한 판단을 하지 않은 경우 이는 재판의 누락이 아니라 판단누락으로 보는 것이 통설, 판례임. 즉 예비적 병합의 경우와 성질상 일부판결이 허용되지 않는 소송에서는 재판의 누락이 있을 수 없으므로 추가판결로 시정할 것이 아니고 병합의 성질상 하나의 전부판결이라고 볼 것이므로 판단 누락에 준하여 상소로 다투어야 함. 따라서 이 경우 갑이 판단누락한 예비적 청구부분을 간편한 분쟁해결수단인 항소로 다투지 아니하고 이를 그대로 확정시킨 뒤 다시 별소를 제기한 것은 권리보호의 이익이 없어 부적법하게 되기 때문이다.","sha256":"903f7d2a83596acd5704294d8de78b00695cf967ad3ac8d009938f1e2613abe5","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제2-3","groupId":"resjudicata-time","sourceId":"sbdd46b414e","sourcePages":[2],"text":"건물매수청구권은 취소권, 해제권 등과 같이 소송물인 권리관계 자체에 부착된 권리가 아니고 이러한 권리를 언제 행사할 것인가는 권리자의 자유에 속하는 것이다. 또한 전소인 건물철거 및 토지인도청구의 소와 후소인 대금지급청구의 소는 그 소송물을 달리한다. 따라서 확정판결에 기하여 건물철거가 집행되지 아니한 이상 대금지급 청구의 소는 허용된다.","sha256":"39c54cc3ddabdd85c02122afdb135f2ea9089fa475b7258b825447f193aaafe0","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제2-4","groupId":"resjudicata-setoff","sourceId":"sbdd46b414e","sourcePages":[2,3],"text":"피고가 상계항변을 제출하였을 경우에 자동채권의 존부에 대하여 비록 판결이유 중에서 판단하게 되지만 상계로써 대항한 액수의 한도 내에서는 기판력이 생긴다(민소법 제216조 제2항). 상계항변이 채택되어 인정된 경우 어느 범위에 관하여 기판력이 인정되는가에 관하여 현재 반대채권(자동채권)이 소멸되어 존재하지 않는다는 점에 기판력이 생긴다는 견해와 소구채권(수동채권)과 반대채권이 함께 존재하였다가 그것이 상계에 의하여 소멸된다는 점에 기판력이 생긴다는 견해가 대립됨. 후자가 통설이지만 어떤 견해에 의하든 부당이득을 원인으로 한 재소가 금지된다는 점에 있어서는 동일함. 결국 사안(1)에서와 같이 원고인 갑이 반대채권이 당초부터 존재하지 않는다고 주장하면서 부당이득반환청구를 하는 것이나 사안(2)에서와 같이 피고인 을이 소구채권이 당초부터 존재하지 않는다고 주장하면서 부당이득반환청구를 하는 것은 기판력에 저촉되는 것으로써 허용되지 아니한다.","sha256":"f30e878d91172c1eb367e21c0d803e156162289be0393d844d45594482292409","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제2-4","groupId":"resjudicata-object","sourceId":"sbdd46b414e","sourcePages":[2,3],"text":"피고가 상계항변을 제출하였을 경우에 자동채권의 존부에 대하여 비록 판결이유 중에서 판단하게 되지만 상계로써 대항한 액수의 한도 내에서는 기판력이 생긴다(민소법 제216조 제2항). 상계항변이 채택되어 인정된 경우 어느 범위에 관하여 기판력이 인정되는가에 관하여 현재 반대채권(자동채권)이 소멸되어 존재하지 않는다는 점에 기판력이 생긴다는 견해와 소구채권(수동채권)과 반대채권이 함께 존재하였다가 그것이 상계에 의하여 소멸된다는 점에 기판력이 생긴다는 견해가 대립됨. 후자가 통설이지만 어떤 견해에 의하든 부당이득을 원인으로 한 재소가 금지된다는 점에 있어서는 동일함. 결국 사안(1)에서와 같이 원고인 갑이 반대채권이 당초부터 존재하지 않는다고 주장하면서 부당이득반환청구를 하는 것이나 사안(2)에서와 같이 피고인 을이 소구채권이 당초부터 존재하지 않는다고 주장하면서 부당이득반환청구를 하는 것은 기판력에 저촉되는 것으로써 허용되지 아니한다.","sha256":"f30e878d91172c1eb367e21c0d803e156162289be0393d844d45594482292409","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-2주-문제2-5","groupId":"counterclaim","sourceId":"sbdd46b414e","sourcePages":[3],"text":"반소의 요건 가운데 하나는, 반소가 본소에 대한 방어방법과 관련성이 있어야 하는 것인데 이에 해당하기 위해서는 방어방법이 현실적으로 제출되어야 하고 또한 법률상 허용되는 적법한 것이어야 한다. 따라서 사안에서와 같이 상계금지채권에 기한 원고의 본소청구에 대하여 피고가 상계주장 내지 항변을 하는 것은 민법상 금지되어 있으므로(제496조) 이러한 경우 이에 바탕을 둔 반소는 부적법한 것이 되기 때문이다.","sha256":"359a126956a6240e6ee5540ade8eb5657898c202da4e4839da4a74a7f0890113","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-3주-사례1","groupId":"pleading-major","sourceId":"s1deb1ca0bb","sourcePages":[1,2,3],"text":"권리의 발생 • 변경 • 소멸 즉 권리의 변동이라는 법률효과를 발생시키는 원인이 되는 실체법상의 구성요건사실인 주요사실은 당사자가 변론에서 주장하여야만 법원이 판결의 기초로 삼을 수 있고 주장하지 아니하면 판결의 기초로 삼을 수 없다. 따라서 당사자가 자기에게 유리한 사실을 주장하지 아니하면 그 사실은 없는 것으로 취급되어 불이익한 판단을 받게 되는데 이를 주장책임이라고 한다. 이와 같이 주장책임의 적용대상이 되는 사실은 주요사실로서 경험법칙 등의 도움을 받아 주요사실의 존부를 추인하게 하는 사실인 간접사실과 증거능력이나 증거가치에 관한 사실인 보조사실은 그 적용대상이 아니다.","sha256":"10be688d8c9614df6a6000eaaa30c54ad71eca682fd2e47fcb288af89ebea1a7","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-3주-사례1","groupId":"evidence-common","sourceId":"s1deb1ca0bb","sourcePages":[1,2,3],"text":"자유심증주의란 법원이 형식적인 증거법칙의 제약을 받지 않고서 변론 전체의 취지와 증거조사의 결과인 증거자료를 참작하여 그에 따라 형성된 자유로운 심증으로 재판의 기초가 되는 주장사실의 진위여부(眞僞與否)를 판단한다는 원칙을 말한다. (민사소송법 제202조). 이에 따라 법원은 증거방법이나 증거능력에 관한 제한을 받지 않을 뿐만 아니라 당사자가 제출한 증거에 대한 증거력평가를 자유롭게 할 수 있기 때문에 증거에 대한 증거조사의 결과(증거자료)를 증거제출자에게 유리하게 평가(판단)할 수도 있고 즉, 유리한 사실의 인정자료로 삼을 수도 있고 반대로 상대방의 원용에 관계없이 그 제출자에게 불리하게도 평가할 수 있게, 즉 불리한 사실의 인정자료로도 삼을 수 있게 되는데 이를 증거공통의 원칙이라고 한다.1)","sha256":"c08b3159aaed0f3de273cfe36ccd1ae3e62b7233a37b2e2aa06b303a1d48e638","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-3주-사례2","groupId":"denial-defense","sourceId":"s1deb1ca0bb","sourcePages":[3,4,5,6],"text":"간접부인은 원고의 주장사실과 논리적으로 양립되지 않는(양립 불가능한) 별개의 사실을 진술하는 것임에 대하여, 항변은 원고의 주장사실이 진실임을 전제로 하여 그와 논리적으로 양립될 수 있는(양립 가능한) 별개의 사실을 진술하는 것임에 차이가 있다.","sha256":"a7b88c8402e7e1452c22e153b52ba22d8ff43dc1c59686db79acf655e1582562","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-3주-사례3","groupId":"class-formative-right","sourceId":"s1deb1ca0bb","sourcePages":[6,7,8,9],"text":"상계권을 제외한 형성권을 소송상 행사한 경우에는 병존설의 입장을 따르지만, 소송상 상계권을 행사한 경우(상계항변)에 있어서 만은 위 ①, ②, ③의 경우에 사법상의 효과(반대채권소멸의 효과)가 발생하지 않는 것으로 보는 견해이다. 즉 상계항변에 포함된 상계의 의사표시는 그 항변이 공격방어방법으로서 각하되거나 실효되지 않고 이것이 유효하게 취급되어 법원이 소구채권이나 반대채권의 존부등 상계항변에 관하여 판단한 경우에 한하여 그에 따른 사법상의 효과가 발생하는 것으로 보는 견해로서 현재 통설의 입장이다","sha256":"b8c67237ad6d777a52cc8738ad212e8bf5f4d8fc27d44c030e2540a9a78e6f5c","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-3주-사례3","groupId":"settlement","sourceId":"s1deb1ca0bb","sourcePages":[6,7,8,9],"text":"(3) 더구나 을의 손해배상채권은 전소의 소송물이 아니었을 뿐만 아니라 그 조정조서의 조정조항에 특정되거나 청구의 표시 다음에 부가적으로 기재되지 아니하였으므로 특별한 사정이 없는 한 위 조정조서의 효력이 을의 손해배상채권에 미치지 않으므로 갑의 항변은 타당하지 않아 법원은 이를 배척하여야 한다","sha256":"4f63da613626b90a133451fcb23929bf4306356da1b875e87741c46a4d95ee8e","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-3주-사례4-1","groupId":"withdrawal","sourceId":"s1deb1ca0bb","sourcePages":[9,10],"text":"(1) 소취하 합의는 소송상 합의의 일종으로서 소송 외에서 원고가 피고에 대한 소를 취하하기로 하는 내용의 원고, 피고 간의 약정을 말하는데, 법규에 이를 허용하는 명문 규정은 없더라도 소송에 있어 당사자의 처분의 자유가 인정되는 영역 즉 처분권주의와 변론주의가 적용되는 영역에서는 그 유효성을 인정하는 것이 일반적이다. 그런데 그 법적 성질과 그에 위반된 행위의 효력에 관하여는 논의가 있다.","sha256":"862262dd570e4e8b4fb2d588cc2e5c22e9d14f5001ac92a603243bb464697183","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-3주-사례4-2","groupId":"withdrawal","sourceId":"s1deb1ca0bb","sourcePages":[11,12],"text":"본안에 관한 종국판결선고 후에 소를 취하한 자는 이미 취하한 소와 동일한 소를 재차 제기하는 것이 금지되는 제재를 받게 되는데 이를 재소금지의 원칙이라 한다. 이 원칙이 적용되기 위하여는 ① 전소와 후소의 당사자가 동일할 것 ② 전소와 후소의 소송물이 동일할 것 ③ 본안에 관한 종국판결선고 후에 소가 취하되었을 것 ④ 전소와 후소의 권리보호이익이 동일한 것이 요구되는데, 본 사안은 위 ①과 ④의 요건과 관련되어 문제 된다. 즉 ①의 요건과 관련하여 항소심에서 소를 취하한 갑으로부터 취하된 전소의 소송물인 권리관계를 그대로 양도받은 병이 특정승계인으로서 갑과 동일하게 재소금지의 효과를 받는 당사자가 되는지의 여부와 ④의 요건과 관련하여 피고인 을이 소취하의 전제조건을 위반한 경우 즉 합의금을 지급하겠다는 을의 말을 믿고 갑이 소를 취하했는데 을이 그 약속을 이행하지 않음으로써 갑 또는 그 특정승계인 병이 다시 소를 제기하는 경우, 이는 전소와는 권리보호의 이익이 다른 것이므로 재소금지 원칙은 그 적용이 없는 것으로 보아야 하는 것인지의 여부가 문제된다.","sha256":"9b084a11e86eae68eced53d254e203e01f42f44cc39e3809737ace5a5b8b12e1","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-4주-문1","groupId":"resjudicata-setoff","sourceId":"s7d6eb58f2f","sourcePages":[1],"text":"- 다만 상계항변은 예외. 피고가 상계항변을 제출하고 법원이 자동채권의 존부에 관하여 판결이유에서 판단하였을 경우에는 상계로써 대항한 액수의 한도 내에서 기판력이 발생함(제216조 제2항).","sha256":"c0713471963ba641b2a1b247c82bea8b7631d523a815594e9de9b5f249aeba33","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-4주-문1","groupId":"resjudicata-object","sourceId":"s7d6eb58f2f","sourcePages":[1],"text":"- 판결주문에서 한 판단에 한하여 기판력이 인정되며(제216조 제1항), 판결이유 중의 항변사항에 대해서는 그것이 판결주문의 결론을 내리는 기초가 되었다 하더라도 기판력이 생기지 않음","sha256":"fbf1bfba5ac0babe4838f2ffaffde695bd7f6c238dabf4b2a1b146d51ab4fabc","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-4주-문2","groupId":"document-authenticity","sourceId":"s7d6eb58f2f","sourcePages":[1,2],"text":"(2) 위 영수증의 형식적 증거력 - 민소법 제358조의 해석론 (10점) 인영부분은 인정하되 날인사실을 부인한 경우, 판례는 이른바 2단의 추정이론을 정립. 따라서 갑이 자신의 인장이 도용된 사실(도용사실) 또는 모용사실을 증명하지 못하는 이상 영수증의 진정 성립은 추정되어 인정된다.","sha256":"b765cf6a728805039bfa695baf25a97e7dac0daef325b3d5081974765ee5763b","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-4주-문2","groupId":"document-substantive","sourceId":"s7d6eb58f2f","sourcePages":[1,2],"text":"(2) 위 영수증의 형식적 증거력이 추정되어 인정되므로 갑이 인장의 도용사실을 증명하지 못하면 법원은 특별한 사정이 없는 이상 영수증의 실질적 증거력을 인정하여야 한다. 즉 법원은 갑이 도용사실을 증명하지 못하면 특별한 사정이 없는 이상 영수증에 기재되어 있는 사실 즉 을이 갑에게 변제한 사실을 인정하여야 한다.","sha256":"4922f38585ca1fa61c5f77909f44302646e8817ac82fa35641929da5fa2f0fc1","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-4주-문3-1","groupId":"absence-confession","sourceId":"s7d6eb58f2f","sourcePages":[2,3],"text":"민소법 제257조 2항에 따라 피고가 청구원인 사실에 대해 모두 자백하는 취지의 답변서를 제출하고 따로 항변을 하지 않으면 법원은 원고의 주장이 주장자체로 실당한 경우를 제외하고 무변론 원고 승소판결을 할 수 있다.","sha256":"aa373cd032e4ce9614b34401b74f55e160d090d0b5fba8493379f46336701d5c","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-4주-문3-2","groupId":"registration-presumption","sourceId":"s7d6eb58f2f","sourcePages":[3,4],"text":"등기의 추정력 : 부동산 등기부상 소유자로 등기되어 있는 자는 특별한 사정이 없는 한 그 부동산의 소유자로 추정된다. 즉 판례에 의하면 등기가 있으면 등기된 권리의 존재 및 귀속, 등기원인의 존재 및 등기절차의 적법성이 법률상 추정된다고 하고 있다. (5점)","sha256":"59c45c7827bb94857644963667c2bcee80824837da2822a1a479be58f4145ae8","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-4주-문3-3","groupId":"joint-independent","sourceId":"s7d6eb58f2f","sourcePages":[4],"text":"병과 정은 피고 을의 공동상속인이고 상속재산은 공유재산으로서 그 관리처분권을 공동으로 행사하는 것이 실체법상 강제되는 관계에 있지 않으므로 병과 정의 공동소송형태는 통상공동소송이다. 이에는 민소법 66조 소정의 공동소송인독립의 원칙이 적용된다. 그러나 이를 그대로 관철할 경우 공동소송인들 간에 모순, 저촉되는 판단이 초래되는 상황이 생길 수 있는데 이를 시정하는 원리로서 공동소송인들 간에 주장공통의 원칙을 인정할 것인가가 문제 된다.","sha256":"f85de171989e92b829553a6c9ea930869bee4af565c52ce28e554011620933cd","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-5주-문1","groupId":"jurisdiction-agreement","sourceId":"sd944ab8460","sourcePages":[1],"text":"- 판례는 법정관할법원 가운데 하나로 관할법원을 특정하는 경우에는 전속적 합의로, 법정관할 법원 외의 다른 법원을 관할법원으로 하는 경우를 부가적 합의로 봄.","sha256":"c57a2b27c434424399879a8fcaf9f0b0664d921d7f287aaff84e2379f20f91e3","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-5주-문1","groupId":"jurisdiction-appearance","sourceId":"sd944ab8460","sourcePages":[1],"text":"- 사안에서 수원지방법원에 변론관할이 생기는지 여부가 문제되나, 피고가 관할위반의 항변을 하면서, 조건적으로 본안에 관한 항변을 하였으므로, 수원지방법원에 변론관할이 성립되지 않음","sha256":"eb6c6d89ba99906126d9df117ef588763377019cb124edf6b15888ad3ad38761","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-5주-문2","groupId":"party-death","sourceId":"sd944ab8460","sourcePages":[1,2],"text":"- 그러나 소송대리인이 있는 경우 당해 소송대리인이 상속인들 모두를 위한 대리인이 되어 소송수행을 할 수 있으며 소송절차는 중단되지 않음. 이 경우 상속인의 수계 절차 여부와 상관없이 소송대리인이 소송을 수행하며, 상속인들 모두에 대하여 판결의 효력이 미침","sha256":"59d2f7720d3318504f7ac8dea53e1520a0686c2c97a395e289c80f07abe53df3","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-5주-문2","groupId":"appeal-scope","sourceId":"sd944ab8460","sourcePages":[1,2],"text":"- 심급대리의 원칙상 1심 판결정본 송달로 소송대리인의 소송수행권이 소멸하므로 위 시점에 소송이 중단되나, 소송대리인에게 상소제기의 특별수권 있는 경우에는 상소기간 도과시 또는 상소 제기시까지 소송대리인의 소송수행권이 존속하므로 위 시점에 소송이 중단됨","sha256":"20ecbcf525cbcab4bf31ba67841080f8c3d30fb99ffdb59436c868ee50d32287","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-5주-문3","groupId":"subrogation-standing","sourceId":"sd944ab8460","sourcePages":[2,3],"text":"- 채권자대위소송에서 피보전권리에 관하여 피보전채권의 존재 및 이행기 도래, 채무자의 권리 불행사, 보전의 필요성 등의 요건을 갖추어야 하는바, 이러한 요건 흠결시에는 당사자적격 흠결로 귀결됨","sha256":"cb3e880abd0a6204d4282b864f2545f440071b6593214d878e28808881aaba02","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-5주-문4","groupId":"indirect-disproof","sourceId":"sd944ab8460","sourcePages":[3],"text":"- 이때 가해자는 간접반증을 통하여, 즉 그 간접사실과 양립하는 별개의 사실(갑 승용차의 횡단보도 진입이 뒷차에 의한 충격의 결과라는 사실)을 입증함으로써 일응의 추정을 복멸할 수 있다.","sha256":"af093a1e3878bf1b35665d6a20eb98cd5a840869fab436ed140c08d6ccd29896","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-6주-문제1-1","groupId":"subrogation-standing","sourceId":"sa8c509fa84","sourcePages":[1],"text":"- 채권자대위소송에서 피보전채권의 흠으로 소각하 판결이 확정된 이후, 채권자가 채무자를 상대로 피보전채권의 이행을 구하는 소송을 제기하는 것이 기판력에 저촉되는지 여부","sha256":"513ad444801cf5d0e103d13a3ec719e7615492b5d4cb88488a6a43f2e1f8e126","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-6주-문제1-1","groupId":"resjudicata-subject","sourceId":"sa8c509fa84","sourcePages":[1],"text":"- 채권자대위소송에서 피보전채권의 흠으로 소각하 판결이 확정된 이후, 채권자가 채무자를 상대로 피보전채권의 이행을 구하는 소송을 제기하는 것이 기판력에 저촉되는지 여부","sha256":"513ad444801cf5d0e103d13a3ec719e7615492b5d4cb88488a6a43f2e1f8e126","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-6주-문제1-2","groupId":"disposition","sourceId":"sa8c509fa84","sourcePages":[1,2],"text":"- 판례는 사해행위인 계약의 전부취소와 부동산 자체의 반환을 구하는 청구취지 가운데에는 위와 같이 일부취소를 하여야 할 경우 그 일부취소와 가액배상을 구하는 취지도 포함되어 있다고 보고 있으므로 청구취지의 변경이 없더라도 바로 일부취소 및 가액배상을 구할 수 있다는 입장임","sha256":"4814aa26762ab8f9e13aa18a13f41dde66a2f2fef28634f0d56e14229ce21f94","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-6주-문제2-1","groupId":"intervention-assistance","sourceId":"sa8c509fa84","sourcePages":[2,3],"text":"- 보조참가인은 피참가인의 승소를 위하여 필요한 소송행위를 자기의 이름으로 할 수 있으며, 이러한 참가인의 소송행위는 피참가인 자신이 행한 것과 같은 효력이 생김. 그러나 참가 당시의 소송진행 정도에 따라 피참가인도 할 수 없는 소송행위는 참가인도 할 수 없음. 따라서 보조참가인은 피참가인의 상소기간 내에서 자기의 이름으로 상소할 수 있음","sha256":"4fa98ee0d13964faf73e827112760e06dae8412df712903aafbed1b09c1322cb","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-6주-문제2-2","groupId":"intervention-assistance","sourceId":"sa8c509fa84","sourcePages":[3],"text":"- 참가인은 참가신청을 취하할 수 있지만, 그러한 경우에도 참가적 효력이 미침. 앞서 본 바와 같이 참가적 효력은 판결주문 뿐만 아니라 판결이유 중 판단에도 미침","sha256":"3a46376ad13dc01c7d2cbd7859d9c26a78ab324ac5bbf564396eab2fdcf46b07","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-6주-문제2-3","groupId":"document-authenticity","sourceId":"sa8c509fa84","sourcePages":[3,4],"text":"- 사문서에 날인된 작성명의인의 인영이 그의 인장임이 증명되면, 문서제출자의 상대방은 날인의 진정을 깨기 위해 인장도용, 자격모용 등의 사실을 적극적으로 증명해야 하며, 그 증명에 성공한 경우 사문서의 진정성립은 추정되지 않으므로, 문서제출자는 날인행위가 작성명의인으로부터 위임받은 정당한 권원에 기한 것이라는 사실을 증명해야 함","sha256":"e54d47befc3e69b2eaf94b268e7af4e4b52b9c06be95e8844967c5676e87602e","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true},{"caseId":"class-6주-문제2-3","groupId":"document-blank","sourceId":"sa8c509fa84","sourcePages":[3,4],"text":"- 사문서에 날인된 작성명의인의 인영이 그의 인장임이 증명되면, 문서제출자의 상대방은 날인의 진정을 깨기 위해 인장도용, 자격모용 등의 사실을 적극적으로 증명해야 하며, 그 증명에 성공한 경우 사문서의 진정성립은 추정되지 않으므로, 문서제출자는 날인행위가 작성명의인으로부터 위임받은 정당한 권원에 기한 것이라는 사실을 증명해야 함","sha256":"e54d47befc3e69b2eaf94b268e7af4e4b52b9c06be95e8844967c5676e87602e","kind":"literal","method":"이미지 대조 교정 TXT 발췌","important":true,"classMaterial":true}],"quoteTexts":{"ccb99e6946546510b229a06b8c84b597369c90c9578425d24a8159b83abdf915":{"text":"자백의 의의. 변론주의의 내용 중 하나로서 자백에는 법원 및 당사자에 대한 구속력이 발생. 그 대상이 되는 사실은 원칙적으로 주요사실에 한한다는 것이 통설, 판례의 입장. 그렇지 않을 경우 자유심증주의에 반하게 됨. 사안의 경우 을이 계약 성립 시에 외국에 출장 중이었다는 주장 내지 진술(현장에 부재하였다는 진술)은 갑이 주장, 증명책임을 부담하는 계약체결 사실과는 양립되지 않는 별개의 사실을 부가하면서 갑의 주장사실을 부정하는 것이기 때문에 이유부 부인에 해당함. 즉 이는 주요사실이 아니라 갑이 주장하는 계약체결사실의 부존재를 추인케 하는 간접사실에 불과하므로 이를 자백하였다 하더라도 자백으로서의 효력(구속력)은 발생하지 않는다(12점).","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","sourceId":"sa975940342","pages":[2]},"bad476ee2290ee00b0b71dcab8d56013e779d0784cedb06d7c2baf119fe0d77a":{"text":"사안에서와 같이 인영부분은 인정하되 날인사실을 부인한 경우, 통설과 판례는 이른바 2단의 추정이론으로 사문서 전체의 진정성립을 추정하고 있다(작성명의인의 인영부분이 인정되면 그의 의사에 기해 날인행위가 행하여졌음이 추정되므로1) 결국 제358조에 의하여 문서전체의 진정성립이 추정된다). 따라서 을의 인장의 도용사실 또는 모용사실에 대하여(즉 제3자에 의해 날인행위가 행하여졌음에 대하여) 증명을 하지 못해 진위불명 상태에 빠진 이상 차용증서의 진정성립은 추정되므로 진정성립을 인정할 수 있다(12점).","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","sourceId":"sa975940342","pages":[2,3]},"6f0fa753ace92a087caf7e50f0567a0e632b71af7fa132bd0617748b1a6fad9a":{"text":"처분문서의 경우 보고문서와는 달리 형식적 증거력이 인정되면 즉 진정성립이 인정되면 특별한 사정이 없는 이상 실질적 증거력이 인정된다. 차용증서는 증명하고자 하는 소비대차계약이라는 법률행위의 존재를 나타내는 처분문서이므로 그 진정성립이 인정되면 특별한 사정이 없는 이상(그 기재내용을 부정해야 할 정도로 분명하고도 확실한 반증이 없는 이상) 그에 기재되어 있는 문언대로 소비대차계약이 체결된 사실을 인정하여야 한다(12점).","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","sourceId":"sa975940342","pages":[3]},"9018debcb99116b0f7907eda0e035d5df3368429ef511b3b20bcfad3f7ddb917":{"text":"이른바 2단의 추정이론은 사문서의 내용이 먼저 기재되어 완성된 상태에서 서명이나 날인이 행해진 경우에만 적용되는 것이고, 사안에서와 같이 문서가 미완성 상태에서 서명이나 날인이 행해진 경우에는 적용되지 않는다. 따라서 위 차용증서가 백지상태로 작성·교부되었고, 갑이 추후 위 차용증서에 그 내용을 기재한 것(백지부분을 보충한 것)이라는 사실이 증명된 이상, 거증자인 갑은 을로부터 백지부분의 보충 등 그 작성에 관한 권한을 위임받았음을 증명하여야 하고(증명책임), 이를 증명하지 못하면 위 차용증서의 진정성립은 인정될 수 없다(12점).","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","sourceId":"sa975940342","pages":[3]},"54194d989984b8c5ffc64f60f4d52f435ac4dd1a5a471e385c8bb533e1e8be02":{"text":"문서의 진정성립에 관한 자백은 보조사실에 관한 것이지만 이에 대하여 재판상 자백과 같은 구속력이 인정된다(판례). 따라서 법원은 이를 기초로 판단하여야 하고(차용증서의 진정성립을 인정하여야 하고) 당사자는 이에 관한 자백을 취소하거나 철회할 수 없다. 당사자가 이를 취소 내지 철회하기 위해서는 상대방의 동의가 있거나, 진실에 반하고 착오로 인해 자백하였음을 증명하거나 그 자백이 형사상 처벌받을 제3자의 행위로 인하여 행하여졌다는 점을 증명하여야만 한다(7점).","sourceFile":"민사소송법사례연습 1주차 문제 답안.txt","sourceId":"sa975940342","pages":[3,4]},"7b0f2f8b2cd41c9ff6ed107c0040913b1d7fa477d1c125c3775da068ea56efdc":{"text":"소송물인 권리관계 자체를 승계한 자뿐만 아니라 그 계쟁물을 승계 받은 자도 승계인에 포함된다. 사안의 경우 정은 물권적 청구권을 소송물로 하는 소송의 사실심 변론종결 이전에 피고로부터 계쟁물의 일부를 넘겨받았으므로 피고 적격의 승계인에 해당한다. 따라서 소송계속 중 제3자가 소송목적인 의무의 목적물을 승계한 경우에 해당되어 갑은 정으로 하여금 소송을 인수하게 할 수 있다(민소법 제82조 제1항). (15점)","sourceFile":"민사소송법사례연습 2주차 답안1.txt","sourceId":"sd518de2552","pages":[1]},"d3cb36eecc7080fed64b8f1ac3ffef407aca6659fc6fc330c8a71ac630726212":{"text":"본 사안의 경우 갑과 병 간의 소송의 소송물은 물권적 청구권에 기한 것으로서 정은 변론종결 이후부터 위 건물 일부를 점유하게 되었다. 따라서 판례에 따르면 정은 변론종결 후에 계쟁물을 양수한 승계인에 해당하여 그에 대해 기판력이 미치게 된다(민사소송법 제218조 제1항). 따라서 갑은 승계집행문을 부여받아 정에 대하여 강제집행을 할 수 있다(15점).","sourceFile":"민사소송법사례연습 2주차 답안1.txt","sourceId":"sd518de2552","pages":[1]},"898e2ba2458c7e805a4b3ed696b88050f7ed3e9074da76c42d6c7494639d412f":{"text":"- 갑이 받는 확정판결의 기판력이 정에게 확장되는 것인가가 쟁점이다. 판례에 의하면 이는 갑이 을과 병을 상대로 제기한 전소의 소송물이 물권적 청구권에 기한 것인가 채권적 청구권에 기한 것인가의 여부에 따라 결정된다. 건물의 소유자인 갑이 소유권에 기하여 을과 병이 무단 점유자임을 주장하면서 이들을 상대로 차임 상당의 부당이득반환을 구하는 소송을 제기하여 그에 관한 판결이 확정된 경우, 이러한 소송의 소송물은 채권적 청구권인 부당이득반환청구권이므로, 전소의 변론종결 후에 건물의 소유권을 취득한 정은 민사소송법 제218조 제1항에 의하여 확정판결의 기판력이 미치는 변론을 종결한 뒤의 승계인에 해당한다고 볼 수 없다(대법원 2016.6.28. 선고 2014다31721 판결 참조)(9점).","sourceFile":"민사소송법사례연습 2주차 답안1.txt","sourceId":"sd518de2552","pages":[1,2]},"2b48498c903cbcfe2b31b7337f564f51b15e1cb87396622e5bbde047e39c90f5":{"text":"- 건물 소유권에 기한 물권적 청구권을 원인으로 하는 건물인도청구소송의 소송물은 건물 소유권이 아니라 그 물권적 청구권인 건물인도청구권이므로 그 소송에서 청구기각된 확정판결의 기판력은 건물인도청구권의 존부 그 자체에만 미치는 것이고, 소송물이 되지 아니한 건물 소유권의 존부에 관하여는 미치지 아니하므로, 그 건물인도소송의 사실심 변론종결 후에 그 패소자인 건물 소유자 갑으로부터 건물을 매수하고 소유권이전등기를 마침으로써 그 소유권을 승계한 정의 건물 소유권의 존부에 관하여는 위 확정판결의 기판력이 미치지 않는다. 또한 이 경우 정이 가지게 되는 물권적 청구권인 건물인도청구권은 적법하게 승계한 건물 소유권의 일반적 효력으로서 발생된 것이고, 위 건물인도소송의 소송물인 패소자 갑의 건물명도청구권을 승계함으로써 가지게 된 것이라고는 할 수 없으므로, 정은 위 확정판결의 변론종결 후의 승계인에 해당한다고 할 수 없다(대법원 1999. 10. 22. 선고 98다6855 판결 참조)(9점).","sourceFile":"민사소송법사례연습 2주차 답안1.txt","sourceId":"sd518de2552","pages":[1,2]},"ba943903849f2d006f7136310bd99d058d0b0dccef78f301f13d4aea53763331":{"text":"- 갑이 을과 병을 상대로 하는 소송은 민소법 제65조 후문에 해당되는 통상공동소송이다. 따라서 공동소송인 독립의 원칙이 적용된다. 위 원칙의 개념(민소법 제66조)을 설시해야 한다. 그에 따라 을만이 항소할 경우 갑과 병 사이의 판결은 분리되어 확정된다(5점).","sourceFile":"민사소송법사례연습 2주차 답안1.txt","sourceId":"sd518de2552","pages":[2]},"31a01ee644b4d27003db06dc5438c08bd563ace9fefd7c57d67ef8a4bb9c8d1f":{"text":"절차의 명확성과 안정성의 요청 때문에 민법상 의사표시의 하자에 관한 규정은 소송행위에 적용되지 않음이 원칙. 다만, 소의 취하와 같은 소송행위가 사기 등 제3자의 형사상 처벌받을 행위로 인하여 행해졌을 때, 소송법상 이에 대한 구제방법을 인정하는 것이 일반적인 견해임. 소취하의 무효를 주장하면서 변론기일 지정신청을 하는 방법과 다시 소유권이전등기청구의 소를 제기하는 방법을 생각할 수 있는데, 후자의 경우 재소금지에 해당하는 것은 아닌지의 문제가 있음.","sourceFile":"민사소송법사례연습 2주차 답안2.txt","sourceId":"sbdd46b414e","pages":[1]},"903f7d2a83596acd5704294d8de78b00695cf967ad3ac8d009938f1e2613abe5":{"text":"선택적, 예비적 병합의 경우, 병합된 여러 개의 청구는 동일한 절차에 불가분적으로 결합되어 있기 때문에 일부판결을 선고할 수 없다(통설, 판례). 사안에서와 같이 법원이 주위적 청구만을 배척하고 예비적 청구에 대한 판단을 하지 않은 경우 이는 재판의 누락이 아니라 판단누락으로 보는 것이 통설, 판례임. 즉 예비적 병합의 경우와 성질상 일부판결이 허용되지 않는 소송에서는 재판의 누락이 있을 수 없으므로 추가판결로 시정할 것이 아니고 병합의 성질상 하나의 전부판결이라고 볼 것이므로 판단 누락에 준하여 상소로 다투어야 함. 따라서 이 경우 갑이 판단누락한 예비적 청구부분을 간편한 분쟁해결수단인 항소로 다투지 아니하고 이를 그대로 확정시킨 뒤 다시 별소를 제기한 것은 권리보호의 이익이 없어 부적법하게 되기 때문이다.","sourceFile":"민사소송법사례연습 2주차 답안2.txt","sourceId":"sbdd46b414e","pages":[1,2]},"39c54cc3ddabdd85c02122afdb135f2ea9089fa475b7258b825447f193aaafe0":{"text":"건물매수청구권은 취소권, 해제권 등과 같이 소송물인 권리관계 자체에 부착된 권리가 아니고 이러한 권리를 언제 행사할 것인가는 권리자의 자유에 속하는 것이다. 또한 전소인 건물철거 및 토지인도청구의 소와 후소인 대금지급청구의 소는 그 소송물을 달리한다. 따라서 확정판결에 기하여 건물철거가 집행되지 아니한 이상 대금지급 청구의 소는 허용된다.","sourceFile":"민사소송법사례연습 2주차 답안2.txt","sourceId":"sbdd46b414e","pages":[2]},"f30e878d91172c1eb367e21c0d803e156162289be0393d844d45594482292409":{"text":"피고가 상계항변을 제출하였을 경우에 자동채권의 존부에 대하여 비록 판결이유 중에서 판단하게 되지만 상계로써 대항한 액수의 한도 내에서는 기판력이 생긴다(민소법 제216조 제2항). 상계항변이 채택되어 인정된 경우 어느 범위에 관하여 기판력이 인정되는가에 관하여 현재 반대채권(자동채권)이 소멸되어 존재하지 않는다는 점에 기판력이 생긴다는 견해와 소구채권(수동채권)과 반대채권이 함께 존재하였다가 그것이 상계에 의하여 소멸된다는 점에 기판력이 생긴다는 견해가 대립됨. 후자가 통설이지만 어떤 견해에 의하든 부당이득을 원인으로 한 재소가 금지된다는 점에 있어서는 동일함. 결국 사안(1)에서와 같이 원고인 갑이 반대채권이 당초부터 존재하지 않는다고 주장하면서 부당이득반환청구를 하는 것이나 사안(2)에서와 같이 피고인 을이 소구채권이 당초부터 존재하지 않는다고 주장하면서 부당이득반환청구를 하는 것은 기판력에 저촉되는 것으로써 허용되지 아니한다.","sourceFile":"민사소송법사례연습 2주차 답안2.txt","sourceId":"sbdd46b414e","pages":[2,3]},"359a126956a6240e6ee5540ade8eb5657898c202da4e4839da4a74a7f0890113":{"text":"반소의 요건 가운데 하나는, 반소가 본소에 대한 방어방법과 관련성이 있어야 하는 것인데 이에 해당하기 위해서는 방어방법이 현실적으로 제출되어야 하고 또한 법률상 허용되는 적법한 것이어야 한다. 따라서 사안에서와 같이 상계금지채권에 기한 원고의 본소청구에 대하여 피고가 상계주장 내지 항변을 하는 것은 민법상 금지되어 있으므로(제496조) 이러한 경우 이에 바탕을 둔 반소는 부적법한 것이 되기 때문이다.","sourceFile":"민사소송법사례연습 2주차 답안2.txt","sourceId":"sbdd46b414e","pages":[3]},"10be688d8c9614df6a6000eaaa30c54ad71eca682fd2e47fcb288af89ebea1a7":{"text":"권리의 발생 • 변경 • 소멸 즉 권리의 변동이라는 법률효과를 발생시키는 원인이 되는 실체법상의 구성요건사실인 주요사실은 당사자가 변론에서 주장하여야만 법원이 판결의 기초로 삼을 수 있고 주장하지 아니하면 판결의 기초로 삼을 수 없다. 따라서 당사자가 자기에게 유리한 사실을 주장하지 아니하면 그 사실은 없는 것으로 취급되어 불이익한 판단을 받게 되는데 이를 주장책임이라고 한다. 이와 같이 주장책임의 적용대상이 되는 사실은 주요사실로서 경험법칙 등의 도움을 받아 주요사실의 존부를 추인하게 하는 사실인 간접사실과 증거능력이나 증거가치에 관한 사실인 보조사실은 그 적용대상이 아니다.","sourceFile":"민사소송법사례연습 3주차 답안.txt","sourceId":"s1deb1ca0bb","pages":[1,2,3]},"c08b3159aaed0f3de273cfe36ccd1ae3e62b7233a37b2e2aa06b303a1d48e638":{"text":"자유심증주의란 법원이 형식적인 증거법칙의 제약을 받지 않고서 변론 전체의 취지와 증거조사의 결과인 증거자료를 참작하여 그에 따라 형성된 자유로운 심증으로 재판의 기초가 되는 주장사실의 진위여부(眞僞與否)를 판단한다는 원칙을 말한다. (민사소송법 제202조). 이에 따라 법원은 증거방법이나 증거능력에 관한 제한을 받지 않을 뿐만 아니라 당사자가 제출한 증거에 대한 증거력평가를 자유롭게 할 수 있기 때문에 증거에 대한 증거조사의 결과(증거자료)를 증거제출자에게 유리하게 평가(판단)할 수도 있고 즉, 유리한 사실의 인정자료로 삼을 수도 있고 반대로 상대방의 원용에 관계없이 그 제출자에게 불리하게도 평가할 수 있게, 즉 불리한 사실의 인정자료로도 삼을 수 있게 되는데 이를 증거공통의 원칙이라고 한다.1)","sourceFile":"민사소송법사례연습 3주차 답안.txt","sourceId":"s1deb1ca0bb","pages":[1,2,3]},"a7b88c8402e7e1452c22e153b52ba22d8ff43dc1c59686db79acf655e1582562":{"text":"간접부인은 원고의 주장사실과 논리적으로 양립되지 않는(양립 불가능한) 별개의 사실을 진술하는 것임에 대하여, 항변은 원고의 주장사실이 진실임을 전제로 하여 그와 논리적으로 양립될 수 있는(양립 가능한) 별개의 사실을 진술하는 것임에 차이가 있다.","sourceFile":"민사소송법사례연습 3주차 답안.txt","sourceId":"s1deb1ca0bb","pages":[3,4,5,6]},"b8c67237ad6d777a52cc8738ad212e8bf5f4d8fc27d44c030e2540a9a78e6f5c":{"text":"상계권을 제외한 형성권을 소송상 행사한 경우에는 병존설의 입장을 따르지만, 소송상 상계권을 행사한 경우(상계항변)에 있어서 만은 위 ①, ②, ③의 경우에 사법상의 효과(반대채권소멸의 효과)가 발생하지 않는 것으로 보는 견해이다. 즉 상계항변에 포함된 상계의 의사표시는 그 항변이 공격방어방법으로서 각하되거나 실효되지 않고 이것이 유효하게 취급되어 법원이 소구채권이나 반대채권의 존부등 상계항변에 관하여 판단한 경우에 한하여 그에 따른 사법상의 효과가 발생하는 것으로 보는 견해로서 현재 통설의 입장이다","sourceFile":"민사소송법사례연습 3주차 답안.txt","sourceId":"s1deb1ca0bb","pages":[6,7,8,9]},"4f63da613626b90a133451fcb23929bf4306356da1b875e87741c46a4d95ee8e":{"text":"(3) 더구나 을의 손해배상채권은 전소의 소송물이 아니었을 뿐만 아니라 그 조정조서의 조정조항에 특정되거나 청구의 표시 다음에 부가적으로 기재되지 아니하였으므로 특별한 사정이 없는 한 위 조정조서의 효력이 을의 손해배상채권에 미치지 않으므로 갑의 항변은 타당하지 않아 법원은 이를 배척하여야 한다","sourceFile":"민사소송법사례연습 3주차 답안.txt","sourceId":"s1deb1ca0bb","pages":[6,7,8,9]},"862262dd570e4e8b4fb2d588cc2e5c22e9d14f5001ac92a603243bb464697183":{"text":"(1) 소취하 합의는 소송상 합의의 일종으로서 소송 외에서 원고가 피고에 대한 소를 취하하기로 하는 내용의 원고, 피고 간의 약정을 말하는데, 법규에 이를 허용하는 명문 규정은 없더라도 소송에 있어 당사자의 처분의 자유가 인정되는 영역 즉 처분권주의와 변론주의가 적용되는 영역에서는 그 유효성을 인정하는 것이 일반적이다. 그런데 그 법적 성질과 그에 위반된 행위의 효력에 관하여는 논의가 있다.","sourceFile":"민사소송법사례연습 3주차 답안.txt","sourceId":"s1deb1ca0bb","pages":[9,10]},"9b084a11e86eae68eced53d254e203e01f42f44cc39e3809737ace5a5b8b12e1":{"text":"본안에 관한 종국판결선고 후에 소를 취하한 자는 이미 취하한 소와 동일한 소를 재차 제기하는 것이 금지되는 제재를 받게 되는데 이를 재소금지의 원칙이라 한다. 이 원칙이 적용되기 위하여는 ① 전소와 후소의 당사자가 동일할 것 ② 전소와 후소의 소송물이 동일할 것 ③ 본안에 관한 종국판결선고 후에 소가 취하되었을 것 ④ 전소와 후소의 권리보호이익이 동일한 것이 요구되는데, 본 사안은 위 ①과 ④의 요건과 관련되어 문제 된다. 즉 ①의 요건과 관련하여 항소심에서 소를 취하한 갑으로부터 취하된 전소의 소송물인 권리관계를 그대로 양도받은 병이 특정승계인으로서 갑과 동일하게 재소금지의 효과를 받는 당사자가 되는지의 여부와 ④의 요건과 관련하여 피고인 을이 소취하의 전제조건을 위반한 경우 즉 합의금을 지급하겠다는 을의 말을 믿고 갑이 소를 취하했는데 을이 그 약속을 이행하지 않음으로써 갑 또는 그 특정승계인 병이 다시 소를 제기하는 경우, 이는 전소와는 권리보호의 이익이 다른 것이므로 재소금지 원칙은 그 적용이 없는 것으로 보아야 하는 것인지의 여부가 문제된다.","sourceFile":"민사소송법사례연습 3주차 답안.txt","sourceId":"s1deb1ca0bb","pages":[11,12]},"c0713471963ba641b2a1b247c82bea8b7631d523a815594e9de9b5f249aeba33":{"text":"- 다만 상계항변은 예외. 피고가 상계항변을 제출하고 법원이 자동채권의 존부에 관하여 판결이유에서 판단하였을 경우에는 상계로써 대항한 액수의 한도 내에서 기판력이 발생함(제216조 제2항).","sourceFile":"민사소송법사례연습 4주차 답안.txt","sourceId":"s7d6eb58f2f","pages":[1]},"fbf1bfba5ac0babe4838f2ffaffde695bd7f6c238dabf4b2a1b146d51ab4fabc":{"text":"- 판결주문에서 한 판단에 한하여 기판력이 인정되며(제216조 제1항), 판결이유 중의 항변사항에 대해서는 그것이 판결주문의 결론을 내리는 기초가 되었다 하더라도 기판력이 생기지 않음","sourceFile":"민사소송법사례연습 4주차 답안.txt","sourceId":"s7d6eb58f2f","pages":[1]},"b765cf6a728805039bfa695baf25a97e7dac0daef325b3d5081974765ee5763b":{"text":"(2) 위 영수증의 형식적 증거력 - 민소법 제358조의 해석론 (10점) 인영부분은 인정하되 날인사실을 부인한 경우, 판례는 이른바 2단의 추정이론을 정립. 따라서 갑이 자신의 인장이 도용된 사실(도용사실) 또는 모용사실을 증명하지 못하는 이상 영수증의 진정 성립은 추정되어 인정된다.","sourceFile":"민사소송법사례연습 4주차 답안.txt","sourceId":"s7d6eb58f2f","pages":[1,2]},"4922f38585ca1fa61c5f77909f44302646e8817ac82fa35641929da5fa2f0fc1":{"text":"(2) 위 영수증의 형식적 증거력이 추정되어 인정되므로 갑이 인장의 도용사실을 증명하지 못하면 법원은 특별한 사정이 없는 이상 영수증의 실질적 증거력을 인정하여야 한다. 즉 법원은 갑이 도용사실을 증명하지 못하면 특별한 사정이 없는 이상 영수증에 기재되어 있는 사실 즉 을이 갑에게 변제한 사실을 인정하여야 한다.","sourceFile":"민사소송법사례연습 4주차 답안.txt","sourceId":"s7d6eb58f2f","pages":[1,2]},"aa373cd032e4ce9614b34401b74f55e160d090d0b5fba8493379f46336701d5c":{"text":"민소법 제257조 2항에 따라 피고가 청구원인 사실에 대해 모두 자백하는 취지의 답변서를 제출하고 따로 항변을 하지 않으면 법원은 원고의 주장이 주장자체로 실당한 경우를 제외하고 무변론 원고 승소판결을 할 수 있다.","sourceFile":"민사소송법사례연습 4주차 답안.txt","sourceId":"s7d6eb58f2f","pages":[2,3]},"59c45c7827bb94857644963667c2bcee80824837da2822a1a479be58f4145ae8":{"text":"등기의 추정력 : 부동산 등기부상 소유자로 등기되어 있는 자는 특별한 사정이 없는 한 그 부동산의 소유자로 추정된다. 즉 판례에 의하면 등기가 있으면 등기된 권리의 존재 및 귀속, 등기원인의 존재 및 등기절차의 적법성이 법률상 추정된다고 하고 있다. (5점)","sourceFile":"민사소송법사례연습 4주차 답안.txt","sourceId":"s7d6eb58f2f","pages":[3,4]},"f85de171989e92b829553a6c9ea930869bee4af565c52ce28e554011620933cd":{"text":"병과 정은 피고 을의 공동상속인이고 상속재산은 공유재산으로서 그 관리처분권을 공동으로 행사하는 것이 실체법상 강제되는 관계에 있지 않으므로 병과 정의 공동소송형태는 통상공동소송이다. 이에는 민소법 66조 소정의 공동소송인독립의 원칙이 적용된다. 그러나 이를 그대로 관철할 경우 공동소송인들 간에 모순, 저촉되는 판단이 초래되는 상황이 생길 수 있는데 이를 시정하는 원리로서 공동소송인들 간에 주장공통의 원칙을 인정할 것인가가 문제 된다.","sourceFile":"민사소송법사례연습 4주차 답안.txt","sourceId":"s7d6eb58f2f","pages":[4]},"c57a2b27c434424399879a8fcaf9f0b0664d921d7f287aaff84e2379f20f91e3":{"text":"- 판례는 법정관할법원 가운데 하나로 관할법원을 특정하는 경우에는 전속적 합의로, 법정관할 법원 외의 다른 법원을 관할법원으로 하는 경우를 부가적 합의로 봄.","sourceFile":"민사소송법사례연습 5주차 답안.txt","sourceId":"sd944ab8460","pages":[1]},"eb6c6d89ba99906126d9df117ef588763377019cb124edf6b15888ad3ad38761":{"text":"- 사안에서 수원지방법원에 변론관할이 생기는지 여부가 문제되나, 피고가 관할위반의 항변을 하면서, 조건적으로 본안에 관한 항변을 하였으므로, 수원지방법원에 변론관할이 성립되지 않음","sourceFile":"민사소송법사례연습 5주차 답안.txt","sourceId":"sd944ab8460","pages":[1]},"59d2f7720d3318504f7ac8dea53e1520a0686c2c97a395e289c80f07abe53df3":{"text":"- 그러나 소송대리인이 있는 경우 당해 소송대리인이 상속인들 모두를 위한 대리인이 되어 소송수행을 할 수 있으며 소송절차는 중단되지 않음. 이 경우 상속인의 수계 절차 여부와 상관없이 소송대리인이 소송을 수행하며, 상속인들 모두에 대하여 판결의 효력이 미침","sourceFile":"민사소송법사례연습 5주차 답안.txt","sourceId":"sd944ab8460","pages":[1,2]},"20ecbcf525cbcab4bf31ba67841080f8c3d30fb99ffdb59436c868ee50d32287":{"text":"- 심급대리의 원칙상 1심 판결정본 송달로 소송대리인의 소송수행권이 소멸하므로 위 시점에 소송이 중단되나, 소송대리인에게 상소제기의 특별수권 있는 경우에는 상소기간 도과시 또는 상소 제기시까지 소송대리인의 소송수행권이 존속하므로 위 시점에 소송이 중단됨","sourceFile":"민사소송법사례연습 5주차 답안.txt","sourceId":"sd944ab8460","pages":[1,2]},"cb3e880abd0a6204d4282b864f2545f440071b6593214d878e28808881aaba02":{"text":"- 채권자대위소송에서 피보전권리에 관하여 피보전채권의 존재 및 이행기 도래, 채무자의 권리 불행사, 보전의 필요성 등의 요건을 갖추어야 하는바, 이러한 요건 흠결시에는 당사자적격 흠결로 귀결됨","sourceFile":"민사소송법사례연습 5주차 답안.txt","sourceId":"sd944ab8460","pages":[2,3]},"af093a1e3878bf1b35665d6a20eb98cd5a840869fab436ed140c08d6ccd29896":{"text":"- 이때 가해자는 간접반증을 통하여, 즉 그 간접사실과 양립하는 별개의 사실(갑 승용차의 횡단보도 진입이 뒷차에 의한 충격의 결과라는 사실)을 입증함으로써 일응의 추정을 복멸할 수 있다.","sourceFile":"민사소송법사례연습 5주차 답안.txt","sourceId":"sd944ab8460","pages":[3]},"513ad444801cf5d0e103d13a3ec719e7615492b5d4cb88488a6a43f2e1f8e126":{"text":"- 채권자대위소송에서 피보전채권의 흠으로 소각하 판결이 확정된 이후, 채권자가 채무자를 상대로 피보전채권의 이행을 구하는 소송을 제기하는 것이 기판력에 저촉되는지 여부","sourceFile":"민사소송법사례연습 6주차 답안.txt","sourceId":"sa8c509fa84","pages":[1]},"4814aa26762ab8f9e13aa18a13f41dde66a2f2fef28634f0d56e14229ce21f94":{"text":"- 판례는 사해행위인 계약의 전부취소와 부동산 자체의 반환을 구하는 청구취지 가운데에는 위와 같이 일부취소를 하여야 할 경우 그 일부취소와 가액배상을 구하는 취지도 포함되어 있다고 보고 있으므로 청구취지의 변경이 없더라도 바로 일부취소 및 가액배상을 구할 수 있다는 입장임","sourceFile":"민사소송법사례연습 6주차 답안.txt","sourceId":"sa8c509fa84","pages":[1,2]},"4fa98ee0d13964faf73e827112760e06dae8412df712903aafbed1b09c1322cb":{"text":"- 보조참가인은 피참가인의 승소를 위하여 필요한 소송행위를 자기의 이름으로 할 수 있으며, 이러한 참가인의 소송행위는 피참가인 자신이 행한 것과 같은 효력이 생김. 그러나 참가 당시의 소송진행 정도에 따라 피참가인도 할 수 없는 소송행위는 참가인도 할 수 없음. 따라서 보조참가인은 피참가인의 상소기간 내에서 자기의 이름으로 상소할 수 있음","sourceFile":"민사소송법사례연습 6주차 답안.txt","sourceId":"sa8c509fa84","pages":[2,3]},"3a46376ad13dc01c7d2cbd7859d9c26a78ab324ac5bbf564396eab2fdcf46b07":{"text":"- 참가인은 참가신청을 취하할 수 있지만, 그러한 경우에도 참가적 효력이 미침. 앞서 본 바와 같이 참가적 효력은 판결주문 뿐만 아니라 판결이유 중 판단에도 미침","sourceFile":"민사소송법사례연습 6주차 답안.txt","sourceId":"sa8c509fa84","pages":[3]},"e54d47befc3e69b2eaf94b268e7af4e4b52b9c06be95e8844967c5676e87602e":{"text":"- 사문서에 날인된 작성명의인의 인영이 그의 인장임이 증명되면, 문서제출자의 상대방은 날인의 진정을 깨기 위해 인장도용, 자격모용 등의 사실을 적극적으로 증명해야 하며, 그 증명에 성공한 경우 사문서의 진정성립은 추정되지 않으므로, 문서제출자는 날인행위가 작성명의인으로부터 위임받은 정당한 권원에 기한 것이라는 사실을 증명해야 함","sourceFile":"민사소송법사례연습 6주차 답안.txt","sourceId":"sa8c509fa84","pages":[3,4]}},"newGroups":[{"id":"class-formative-right","unit":"u10","title":"소송상 형성권 행사: 신병존설·상계·조정","focus":"형성권 행사의 사법상 효과가 소송의 취하·각하·조정 뒤에도 남는지를 비교한다.","guide":{"issue":"소송 밖에서 이미 행사한 형성권의 효과를 주장한 것인지, 소송절차에서 처음 형성권을 행사하면서 방어방법으로 제출한 것인지를 구분한다. 소송이 판결에 이르지 않고 끝났을 때 사법상 효과가 남는지가 쟁점이다.","rule":"수업 답안은 신병존설에 따라 상계권 이외의 형성권과 소송상 상계를 구별한다. 상계항변의 사법상 효과는 수동채권의 존재 등 상계에 관한 법원의 실질적 판단이 이루어질 때 발생한다. 소송 도중 조정이 성립하여 그 판단이 없었다면 상계항변만으로 자동채권이 소멸하지 않는다.","checks":["어떤 형성권을 언제 행사했는지 특정한다.","소송상 상계라면 다른 항변과 구별하여 수동채권·자동채권을 확인한다.","소송이 판결·취하·각하·조정 중 무엇으로 종료되었는지 확인한다.","법원의 실질적 상계판단 여부와 조정조서에 반대채권까지 포함되었는지를 각각 검토한다."],"limits":"소송 밖에서 이미 유효하게 한 상계와 소송상 방어방법으로 처음 제출한 상계를 혼동하지 않는다. 상계효과의 발생 여부와 조정조서의 효력 범위는 별개의 논점이다.","flow":"행사 시점·권리 종류 → 종료 방식 → 실질적 판단 → 반대채권 존속·조정 효력","articles":[],"sourceLabel":"수업 3주차 답안 PDF 6~9쪽을 바탕으로 한 학습용 정리"}}]};
